window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s3-956","number":956,"surah":3,"verses":[193,147],"references":[{"surah":3,"verses":[193,147]}],"verseLabel":"آل عمران: 193، 147","question":"ما دلالة اختلاف خاتمة الدعاء بين ﴿وَتَوَفَّنَا مَعَ الْأَبْرَارِ﴾ و﴿وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾؟","answer":"دعاء الآية 193 جاء في مقام التضرع بعد سماع منادي الإيمان، فناسب أن يطلبوا حسن الخاتمة والوفاة مع الأبرار. أما آية 147 فجاءت في سياق قتال وثبات، فناسبها طلب تثبيت الأقدام والنصر، ولا يصح نقل خاتمة من سياق إلى سياق آخر.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف خواتيم دعاء آل عمران بحسب السياق.","url":""}]},{"id":"s3-969","number":969,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما سر ختم آية آل عمران بقوله: ﴿وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ﴾، في حين ختمت آية الحديد بقوله: ﴿وَاللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ﴾؟","answer":"سياق آل عمران في عمل وقع في معركة، وفيه مخالفة وتنازع، فناسبه إسناد الخبرة بالأعمال إلى الله. أما الحديد فبعد الحديث عن الفرح بالمتاع ظهر خطر الاختيال والفخر، فناسب أن يأتي النهي عن هذا الخلق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف الخاتمة بين آل عمران والحديد.","url":""}]},{"id":"s3-970","number":970,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سر التعبير بـ﴿إِلَى مَضَاجِعِهِمْ﴾، لا «من مضاجعهم»؟","answer":"«إلى» تجعل المضاجع غاية يتجهون إليها، والمقصود مضاجع الموت النهائية لا مجرد الأسرة التي خرجوا منها. فالمعنى أن من كتب عليه القتل سيبرز إلى الموضع الذي يكون فيه مصرعه، ولو بقي في بيته لما نجا من الأجل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، إلى مضاجعهم لا من مضاجعهم.","url":""}]},{"id":"s3-971","number":971,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما دلالة وصف الطائفة الأولى بأنها ﴿طَائِفَةً مِنْكُمْ﴾، وترك هذا الوصف عن الطائفة الثانية؟","answer":"وصف الطائفة الأولى بأنها «منكم» يثبت انتماءها إلى جماعة المؤمنين الذين غشيهم النعاس والأمان. أما الثانية فتركت بلا هذا الوصف؛ لأن الحديث عن المنافقين الذين أهتمتهم أنفسهم، فلم يثبت لهم الانتماء الإيماني الذي ثبت للأولى.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، منكم في الطائفة الأولى وحذفها عن الثانية.","url":""}]},{"id":"s3-1015","number":1015,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سر تقديم الابتلاء لما في الصدور على تمحيص ما في القلوب في قوله: ﴿وَلِيَبْتَلِيَ اللَّهُ مَا فِي صُدُورِكُمْ وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمْ﴾؟","answer":"الابتلاء يُظهر ما كان خافيًا في النفس عند وقوع الحدث، ثم يأتي التمحيص لتنقية الداخل من آثار الوهم والضعف. فترتيب الفعلين يصور مرحلتين تربويتين: كشف المكنون أولًا، ثم تخليص القلب مما لا يليق بالإيمان.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، برنامج لمسات بيانية — آية 154.","url":""}]},{"id":"s3-1041","number":1041,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما سر تقديم ﴿أَمَنَةً﴾ على ﴿نُعَاسًا﴾ في أُحد، مقابل تقديم النعاس في سورة الأنفال؟","answer":"قدمت آل عمران الأمنة تشريفًا لها وإبرازًا للمنة التي أنزلها الله بعد الغم؛ فالمقام مقام تسكين قلوب مجروحة. والأمن أطمأن للنفس من النعاس نفسه، إذ قد يخشى النائم أن يؤخذ على غرة، فجعلت الطمأنينة هي موضع العناية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم الأمنة على النعاس.","url":""}]},{"id":"s3-1016","number":1016,"surah":3,"verses":[155],"references":[{"surah":3,"verses":[155]}],"verseLabel":"آل عمران: 155","question":"ما سر ربط تولي بعض المؤمنين يوم أُحد بقوله: ﴿إِنَّمَا اسْتَزَلَّهُمُ الشَّيْطَانُ بِبَعْضِ مَا كَسَبُوا﴾؟","answer":"تكشف الآية أن الانهيار في ساعة الشدة قد تسبقه ذنوب لم تُعالج؛ فالشيطان استثمر بعض ما كسبوه حتى أوقعهم في الزلل. وهذا يجعل الثبات ثمرة تربية مستمرة، لا مجرد شجاعة طارئة ساعة المعركة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الذنوب السابقة من عقبات الثبات.","url":""}]},{"id":"s3-972","number":972,"surah":3,"verses":[159],"references":[{"surah":3,"verses":[159]}],"verseLabel":"آل عمران: 159","question":"ما دلالة تقديم ﴿فَبِمَا رَحْمَةٍ مِنَ اللَّهِ﴾ على ﴿لِنْتَ لَهُمْ﴾؟","answer":"تقديم سبب اللين يقرر أن الرحمة الإلهية هي العلة الحقيقية في حسن المعاملة، لا مجرد طبع بشري مستقل. كما يفيد اختصاص اللين بهذه الرحمة، ويهيئ لمقابلة اللين بما كان يمكن أن يقع من فظاظة وانفضاض.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم «فبما رحمة من الله».","url":""}]},{"id":"s3-974","number":974,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما سر التعبير في قوله تعالى: ﴿وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ﴾، ثم ختم الوعيد بقوله: ﴿مَا كَسَبَتْ﴾؟","answer":"الغلول أخذٌ من الغنيمة قبل قسمتها، فهو متعلق بالمال والكسب والاستحواذ؛ لذلك قيل: ﴿بِمَا غَلَّ﴾ في بيان عين المال المأخوذ، ثم قيل: ﴿مَا كَسَبَتْ﴾ لأن الجزاء يتناول ما كسبته النفس من عمل، مالًا كان أو غيره. فانتقل التعبير من الشيء المغلول إلى مسؤولية الكاسب عنه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، مناسبة «ما كسبت» لسياق الغلول.","url":""}]},{"id":"s3-975","number":975,"surah":3,"verses":[161],"references":[{"surah":3,"verses":[161]}],"verseLabel":"آل عمران: 161","question":"ما دلالة اختلاف الخطاب بين ﴿وَمَا كَانَ لِنَبِيٍّ أَن يَغُلَّ﴾ و﴿وَمَن يَغْلُلْ يَأْتِ بِمَا غَلَّ﴾؟","answer":"بدأت الآية بتنزيه مقام النبوة عن الغلول، ثم نقلت الحكم إلى كل من يقع فيه؛ فالأول نفيٌ عن النبي صلى الله عليه وسلم، والثاني وعيد عام لكل غالٍّ. وبذلك تجمع الآية بين حماية مقام الرسالة، وإقامة المسؤولية الفردية على من يخون في المال العام.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الغلول ونفيه عن مقام النبوة.","url":""}]},{"id":"s3-976","number":976,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سر اختيار لفظ ﴿رِضْوَانَ اللَّهِ﴾ بدل «مرضاة الله» في قوله تعالى: ﴿أَفَمَنِ اتَّبَعَ رِضْوَانَ اللَّهِ﴾؟","answer":"الرضوان يدل على الرضا الكثير العظيم، وقد خصّ القرآن هذا اللفظ بما كان من الله تعالى؛ لأن أعظم ما يطلبه العبد رضا الله. فالتعبير لا يذكر مجرد رضا عابر، بل يصور غايةً عليا يتبعها المؤمن، في مقابل السخط الذي باء به الفريق الآخر.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «رضوان» في التعبير القرآني.","url":""}]},{"id":"s3-977","number":977,"surah":3,"verses":[163],"references":[{"surah":3,"verses":[163]}],"verseLabel":"آل عمران: 163","question":"ما دلالة ختم الآية بقوله: ﴿وَاللَّهُ بَصِيرٌ بِمَا يَعْمَلُونَ﴾، مع أن المقام مقام تفاوت في الدرجات؟","answer":"البصر هنا إحاطة دقيقة بالأعمال التي نشأ عنها تفاوت الدرجات؛ فليس الحكم على الناس بمجرد دعوى أو مظهر، وإنما بما يعملون حقيقة. وجاء تقديم وصف البصر مناسبًا لمقام الكشف عن العمل ومراقبته، ثم يترتب على ذلك اختلاف الجزاء والمنزلة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التقديم بين «بصير بما يعملون» و«بما تعملون خبير».","url":""}]},{"id":"s3-978","number":978,"surah":3,"verses":[167],"references":[{"surah":3,"verses":[167]}],"verseLabel":"آل عمران: 167","question":"ما سر التعبير بـ﴿يَقُولُونَ بِأَفْوَاهِهِمْ﴾ في آل عمران، وبـ﴿يَقُولُونَ بِأَلْسِنَتِهِمْ﴾ في سورة الفتح؟","answer":"«باللسان» يناسب الكذبة العارضة التي ينطق بها المتخلف اعتذارًا. أما «بالأفواه» فيوحي بكلام طويل يملأ الدنيا ضجيجًا ودعاوى، مع خلو القلب من حقيقتها؛ فاختير الأوسع والأشد تصويرًا لمن جعل فمه أداة نشرٍ للباطل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «بأفواههم» و«بألسنتهم».","url":""}]},{"id":"s3-979","number":979,"surah":3,"verses":[169],"references":[{"surah":3,"verses":[169]}],"verseLabel":"آل عمران: 169","question":"ما دلالة الجمع بين ﴿أَحْيَاءٌ عِندَ رَبِّهِمْ﴾ و﴿يُرْزَقُونَ﴾ في وصف الشهداء؟","answer":"لم يكتف التعبير بإثبات الحياة، بل أضاف قربهم من ربهم وما يترتب عليه من رزق متجدد؛ فالحياة حياة كرامة ونعيم لا حياة وجود مجرد. ثم جاءت «فرحين» و«يستبشرون» لتكشف أثر ذلك الرزق في نفوسهم، وأنه فرح ممتد يتعدى إلى من يلحق بهم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، بلاغة وصف الشهداء بالحياة والرزق والفرح.","url":""}]},{"id":"s3-980","number":980,"surah":3,"verses":[172],"references":[{"surah":3,"verses":[172]}],"verseLabel":"آل عمران: 172","question":"ما سر اختلاف ﴿اسْتَجَابُوا لِلَّهِ وَالرَّسُولِ﴾ عن ﴿اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ﴾؟","answer":"في آل عمران جاء الكلام عن قوم استجابوا بالفعل، فجاءت اللام مرة واحدة في سياق يركّز على الله. أما الأنفال فجاء الأمر في سياق يكثر فيه ذكر الرسول، فكررت اللام توكيدًا وتفصيلًا: ﴿لِلَّهِ وَلِلرَّسُولِ﴾. فاختلاف الصيغة تابع للسياق والغرض من التوكيد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «استجابوا لله والرسول» و«استجيبوا لله وللرسول».","url":""}]},{"id":"s3-1028","number":1028,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"ما سر تنكير ﴿فَضْلٍ﴾ في ﴿وَاللَّهُ ذُو فَضْلٍ عَظِيمٍ﴾ بآل عمران، وتعريفه في ﴿ذُو الْفَضْلِ الْعَظِيمِ﴾ بالحديد؟","answer":"في آل عمران كان المذكور سلامة المؤمنين من السوء، وهي فضل عظيم لكنها دون العطاء المفصل في الحديد من كفلين من الرحمة والنور والمغفرة؛ فجاء الفضل منكرًا. أما التعريف في الحديد فيفيد العموم والشمول ويناسب كثرة العطاء وعظمه.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»، التعريف والتنكير في «ذو فضل عظيم».","url":""}]},{"id":"s3-981","number":981,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"ما وجه المقابلة بين ﴿يُخَوِّفُ أَوْلِيَاءَهُ﴾ و﴿فَلَا تَخَافُوهُمْ وَخَافُونِ﴾؟","answer":"الشيطان لا يملك ضرًا، لكنه يصنع الخوف في نفوس أوليائه ليصرفهم عن الثبات. فجاء النهي عن خوف البشر، وأُمر المؤمنون أن يستبدلوا به خوف الله؛ لأن الخوف منه يردع عن المعصية ويمنح القلب شجاعة في مواجهة التهديد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الخوف من الناس والخوف من الله.","url":""}]},{"id":"s3-1042","number":1042,"surah":3,"verses":[175],"references":[{"surah":3,"verses":[175]}],"verseLabel":"آل عمران: 175","question":"ما سر قوله في آل عمران: ﴿فَلَا تَخَافُوهُمْ وَخَافُونِ﴾، وقوله في المائدة: ﴿فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ﴾؟","answer":"سياق آل عمران مواجهة عدو جُمعت له الجموع، فالضرر متوقع قريب، وناسبه الخوف الذي يتعلق بتوقع المكروه. أما آية المائدة فبعد يأس الكفار من الدين وانتفاء الخطر المباشر، فناسبتها الخشية التي تمتزج بالتعظيم والعلم، وهي أخص وأشد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الخوف والخشية في السياقين.","url":""}]},{"id":"s3-982","number":982,"surah":3,"verses":[179],"references":[{"surah":3,"verses":[179]}],"verseLabel":"آل عمران: 179","question":"ما وجه اختلاف ختام ﴿مَا كَانَ اللَّهُ لِيَذَرَ الْمُؤْمِنِينَ﴾ عن ختام ﴿وَمَا كَانَ رَبُّكَ لِيُهْلِكَ الْقُرَى ... وَأَهْلُهَا مُصْلِحُونَ﴾؟","answer":"آية آل عمران في تمحيص الجماعة المؤمنة وكشف المنافقين، فناسبها ذكر التمييز. أما آية هود ففي إصلاح المجتمع والنهي عن الفساد، فناسبها نفي هلاك القرى ما دام أهلها مصلحين. يتغير الختام لأن العبرة في كل موضع متصلة بالسياق الذي سيقت فيه الآية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، مناسبة خواتيم الآيات للسياق.","url":""}]},{"id":"s3-983","number":983,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سر افتتاح الرد على قولهم: ﴿إِنَّ اللَّهَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ﴾ بقوله: ﴿لَقَدْ سَمِعَ اللَّهُ قَوْلَ الَّذِينَ قَالُوا﴾؟","answer":"«سمع الله» هنا ليس مجرد إثبات السماع، بل تهديدٌ لمن تفوه بهذا القول؛ أي إن الكلمة لم تذهب هدرًا، بل أحاط بها علم الله وسيسأل قائلها عنها. ثم عُطف عليها قتل الأنبياء لتظهر فداحة اجتماع القول الباطل والفعل الإجرامي.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، «سمع الله» في مقام التهديد.","url":""}]},{"id":"s3-984","number":984,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما دلالة الانتقال من ﴿لَقَدْ سَمِعَ اللَّهُ﴾ إلى ﴿سَنَكْتُبُ مَا قَالُوا﴾؟","answer":"السماع يحيط بالقول لحظة صدوره، أما الكتابة فتدل على إثباته وحفظه ليكون حجة عليهم. فالجملة تنتقل من العلم المحيط إلى تسجيل الجريمة، ثم إلى الجزاء، لتصور أن الكلمة الباطلة تمر بمراحل: تُسمع، وتُحفظ، ويُحاسب صاحبها عليها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، سماع القول وكتابته وتسجيل أثره.","url":""}]},{"id":"s3-1018","number":1018,"surah":3,"verses":[186],"references":[{"surah":3,"verses":[186]}],"verseLabel":"آل عمران: 186","question":"ما سر عطف ﴿وَلَتَسْمَعُنَّ﴾ على ﴿لَتُبْلَوُنَّ﴾ بالتوكيد نفسه؟","answer":"الابتلاء لا يقتصر على خسارة المال أو أذى النفس؛ فالكلمة الجارحة والتشويه المتكرر امتحان كذلك. وتوحيد صيغة التوكيد يهيئ المؤمنين للنوعين معًا، فلا يستهينون بأذى الخطاب ولا يجعلونه سببًا لترك الصبر والتقوى.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التوكيد في «لتبلون» و«لتسمعن».","url":""}]},{"id":"s3-1019","number":1019,"surah":3,"verses":[186,200],"references":[{"surah":3,"verses":[186,200]}],"verseLabel":"آل عمران: 186، 200","question":"ما وجه الصلة بين ﴿وَإِن تَصْبِرُوا وَتَتَّقُوا﴾ عند توقع الأذى، و﴿اصْبِرُوا وَصَابِرُوا... وَاتَّقُوا اللَّهَ﴾ في ختام السورة؟","answer":"آية 186 تعطي الاستجابة الأساسية للابتلاء: الصبر والتقوى، ثم تأتي الخاتمة فتجعل الصبر ممارسة متعدية بالمصابرة والمرابطة. وكأن السورة تنقل المؤمن من تحمل الأذى إلى بناء جماعة أطول نفسًا من خصمها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، لام القسم وخاتمة الابتلاء، ومحور الثبات وخاتمة السورة.","url":""}]},{"id":"s3-1031","number":1031,"surah":3,"verses":[187,199],"references":[{"surah":3,"verses":[187,199]}],"verseLabel":"آل عمران: 187، 199","question":"ما أثر تكرار عبارة ﴿ثَمَنًا قَلِيلًا﴾ في وصف من اشتروا بآيات الله، ومن امتنعوا عن ذلك؟","answer":"إعادة العبارة نفسها تقيم مقابلة مباشرة لا تخفى: فريق باع الحق بالعاجل القليل، وفريق صان الآيات عن المساومة. وبثبات العبارة وتغير النفي يظهر أن نقطة الافتراق ليست قيمة الثمن وحدها، بل قبول تحويل الوحي إلى سلعة أصلًا.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، اشتروا ولا يشترون.","url":""}]},{"id":"s3-1032","number":1032,"surah":3,"verses":[188,199],"references":[{"surah":3,"verses":[188,199]}],"verseLabel":"آل عمران: 188، 199","question":"ما وجه المقابلة بين ﴿وَلَهُمْ عَذَابٌ أَلِيمٌ﴾ و﴿أُولَئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ﴾؟","answer":"لما تقابل الموقفان تقابل الجزاءان: كتمان وفرح بما لم يفعلوا يقابله عذاب، وإيمان وخشوع وصيانة للآيات يقابله أجر محفوظ عند الرب. فالمقابلة تحول المفاضلة من مكسب دنيوي عاجل إلى ميزان العاقبة الحقيقية.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، العذاب والأجر في الفريقين.","url":""}]},{"id":"s3-985","number":985,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما دلالة تقديم ﴿خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ﴾ على ﴿اخْتِلَافِ اللَّيْلِ وَالنَّهَارِ﴾ في آل عمران، مع اختلاف الترتيب في سورة يونس؟","answer":"في آل عمران بُدئ بالأصل الأعظم، وهو خلق السماوات والأرض، ثم ذُكر ما يتجدد فيهما من اختلاف الليل والنهار. أما يونس فالسياق يتصل بآيات الزمن والحساب، فناسبه تقديم اختلاف الليل والنهار ثم ذكر ما خلق الله. فالتقديم يراعي مركز الدلالة في كل سياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم الخلق واختلاف الليل والنهار.","url":""}]},{"id":"s3-1022","number":1022,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سر قوله: ﴿فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ﴾، بدل الاقتصار على «في السماوات والأرض» كما في سورة الجاثية؟","answer":"ذكر «الخلق» يضيف إلى النظر في السماوات والأرض النظرَ في إنشائهما وكيفية إيجادهما؛ فالدلالة تشمل الفعل الإلهي والمخلوقات معًا. أما التصريح بالسماوات والأرض من غير «الخلق» فيوجه النظر ابتداءً إلى ذواتهما وما فيهما من الآيات.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الآيات في الخلق والآيات في السماوات والأرض.","url":""}]},{"id":"s3-986","number":986,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما سر حذف فعل القول في قوله تعالى: ﴿رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلًا﴾؟","answer":"لم يقل: «يقولون ربنا» أو «قائلين ربنا» ليشمل المعنى قول اللسان، وحديث النفس، ونتيجة التفكر في آن واحد. فالجملة ليست كلامًا منفصلًا عن التفكر، بل هي خلاصة ما انتهى إليه التفكر من تنزيه الله عن العبث والباطل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، حذف فعل القول وشمول اللسان والنفس والتفكر.","url":""}]},{"id":"s3-987","number":987,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما سر تقديم ﴿يَذْكُرُونَ اللَّهَ﴾ على ﴿يَتَفَكَّرُونَ﴾ في وصف أولي الألباب؟","answer":"الذكر يهيئ القلب والعقل، ثم يأتي التفكر في الخلق على أساس من الحضور مع الله لا من الغفلة عنه. ولذلك تقدم الذكر على التفكر، ثم جاء التنزيه والدعاء؛ فبُني الطريق من صلة القلب بالله إلى النظر في الكون ثم إلى سؤال النجاة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم الذكر على التفكر.","url":""}]},{"id":"s3-988","number":988,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة تكرار ﴿رَبَّنَا﴾ في دعاء أولي الألباب؟","answer":"التكرار يصور تتابع التضرع وتنوع المطالب: النجاة من النار، والمغفرة، والتكفير، وحسن الخاتمة، ثم طلب الوفاء بالوعد. وليس التكرار حشوًا، بل انتقالًا من مطلب إلى آخر مع بقاء القلب متعلقًا برب واحد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تكرار «ربنا» في دعاء أولي الألباب.","url":""}]},{"id":"s3-1024","number":1024,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة تقديم ﴿فَاغْفِرْ لَنَا ذُنُوبَنَا﴾ على ﴿وَكَفِّرْ عَنَّا سَيِّئَاتِنَا﴾؟","answer":"الذنوب أعظم وأشد أثرًا من السيئات التي يراد بها الصغائر، فقدم طلب مغفرة الأعظم قبل تكفير الأخف. كما أن الإسلام يمحو ما تقدمه من الذنوب، فناسب أن تبدأ به مراتب التطهير.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، تقديم مغفرة الذنوب على تكفير السيئات.","url":""}]},{"id":"s3-1025","number":1025,"surah":3,"verses":[193,195],"references":[{"surah":3,"verses":[193,195]}],"verseLabel":"آل عمران: 193، 195","question":"ما سر موافقة قوله: ﴿فَاسْتَجَابَ لَهُمْ رَبُّهُمْ﴾ لندائهم المتكرر: ﴿رَبَّنَا﴾؟","answer":"أضافوا الرب إليهم في الدعاء اعترافًا برعايته وقربه، فجاء الجواب باللفظ نفسه مضافًا إليهم: ﴿رَبُّهُمْ﴾. وهذه الموافقة تحمل لطفًا ظاهرًا؛ فالذي نادوه ربهم هو الذي تولى إجابتهم بربوبيته ورعايته.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، موافقة «ربهم» لنداء «ربنا».","url":""}]},{"id":"s3-989","number":989,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما وجه الصلة بين ﴿إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ﴾ في دعاء آخر السورة، ونظيرتها في دعاء أولها؟","answer":"في أول السورة يقر أولوا الألباب بأن الله جامع الناس ليوم لا ريب فيه، ويختمون بالثقة بأنه لا يخلف الميعاد. وفي آخرها يطلبون ما وعدهم الله على رسله، ثم يعيدون العبارة نفسها؛ فكأن خاتمة السورة تستجيب لدعاء فاتحتها وتربط أولها بآخرها بوعد القيامة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تناسب دعاء أول السورة وخاتمتها.","url":""}]},{"id":"s3-990","number":990,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر التعبير بـ﴿وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ﴾، لا «والله عنده الثواب الحسن»؟","answer":"«حسن» مصدر أضيف إلى الثواب، فصار المعنى أن الله عنده الحسن نفسه في الثواب، لا ثواب موصوف بالحسن فحسب. وهذا أبلغ في وصف الجزاء؛ لأنه يفتح معنى مضاعفة الأجر وتنوعه بما لا يحيط به تقدير البشر.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المبالغة في «حسن الثواب».","url":""}]},{"id":"s3-1026","number":1026,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما وجه الشبه بين ﴿فَاسْتَجَابَ لَهُمْ رَبُّهُمْ﴾ واستجابة دعاء يوسف: ﴿فَاسْتَجَابَ لَهُ رَبُّهُ﴾؟","answer":"في الموضعين دعا المؤمن ربه بصيغة الإضافة: «ربنا» و«ربِّ»، ثم جاء الجواب بإعادة الإضافة نفسها: «ربهم» و«ربه». فتتكرر اللمسة التي تربط الاستجابة بربوبية الله الخاصة لعباده ورعايته لهم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، دعاء الرب واستجابة الرب.","url":""}]},{"id":"s3-1027","number":1027,"surah":3,"verses":[196],"references":[{"surah":3,"verses":[196]}],"verseLabel":"آل عمران: 196","question":"ما دلالة توكيد النهي بالنون في ﴿لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا﴾؟","answer":"مظاهر تمكنهم في البلاد من تجارة وسفر وقوة وحروب شديدة الإغراء للناظر، ولا سيما بعد إيذائهم المؤمنين وإخراجهم. لذلك قُوّي النهي بالنون حتى يقطع أثر هذا المظهر في النفس، ويقرر أنه متاع زائل.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص56–57، توكيد النهي عن الاغترار.","url":""}]},{"id":"s3-991","number":991,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة قوله تعالى: ﴿وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ﴾، مع أن القائل قد يقول «وإن بعض أهل الكتاب يؤمن»؟","answer":"«من» تبعيضية، لكنها ألطف في الدلالة من التصريح ببعضٍ محصور؛ فهي تفتح الباب لوجود طائفة مؤمنة من أهل الكتاب من غير ادعاء أن الجميع كذلك. وجاء التوكيد بـ«إن» واللام لإبراز صدق هذه الشهادة في وسط ذم كثير من أهل الكتاب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «من أهل الكتاب لمن يؤمن».","url":""}]},{"id":"s3-1020","number":1020,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة مجيء ﴿أُنزِلَ إِلَيْكُمْ﴾ و﴿أُنزِلَ إِلَيْهِمْ﴾ بحرف «إلى»، لا «على»؟","answer":"«إلى» تبرز جهة انتهاء الوحي ووصوله إلى المخاطبين، وهو الأنسب في مقام جمع المؤمنين من الفريقين على ما وصل إليهم من الله. أما «على» فتستعمل حين يبرز معنى الاستعلاء والتكليف والنزول على الرسول، ولكل حرف زاوية يقتضيها السياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «أُنزل إليك» و«أُنزل عليك».","url":""}]},{"id":"s3-1033","number":1033,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما الذي يضيفه توكيد ﴿إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ﴾ إلى تصور حساب الخلائق الكثيرة؟","answer":"كثرة المحاسَبين توهم في خبرة البشر طول الانتظار، فجاء التوكيد ليقطع قياس فعل الله على فعل المخلوق؛ لا يشغله حساب عن حساب ولا شأن عن شأن. فسرعة الحساب هنا إعلان كمال القدرة، لا مجرد وصف للزمن.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، كثرة الخلق وسرعة الحساب.","url":""}]},{"id":"s3-1034","number":1034,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سر اتفاق آيتي آل عمران وغافر على توكيد ﴿إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ﴾؟","answer":"في غافر جاء التوكيد عقب جزاء كل نفس يوم القيامة، وهو عموم يستدعي نفي توهم التأخير. وفي آل عمران يتعلق السياق بتوفية الأجور ومراتب الاستحقاق؛ فالتوكيد في كليهما يربط شمول العلم بسرعة إيصال كل نفس إلى جزائها.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، كل نفس وسرعة الحساب.","url":""}]},{"id":"s3-1035","number":1035,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما دلالة توكيد سرعة الحساب في آل عمران، مقابل قوله في الرعد: ﴿وَهُوَ سَرِيعُ الْحِسَابِ﴾ بلا توكيد؟","answer":"آية الرعد تذكر سرعة الحساب صفة لله من غير أن تعرض جماعة محددة تُحاسب في السياق. أما آل عمران فتتحدث عن أناس لهم أعمال وأجور مستحقة، فزاد التوكيد لمناسبة الوعد وقرب الوفاء به.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، الصفة المجردة وخبر الجزاء المؤكد.","url":""}]},{"id":"s3-1036","number":1036,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما وجه اجتماع التوكيد في ﴿إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ﴾ في آل عمران والمائدة؟","answer":"آية المائدة حكم عام للمسلمين ومعه أمر بالتقوى، وكلاهما يناسب توكيد سرعة توفية الجزاء. وفي آل عمران ذُكر الخاشعون الذين رفضوا الثمن القليل؛ فناسب كذلك تأكيد قرب جزائهم وسرعة إيفائهم ما استحقوا.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، التقوى وعموم الخطاب وسرعة الحساب.","url":""}]},{"id":"s3-1037","number":1037,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما سر كون المصابرة أشق من الصبر المجرد؟","answer":"الصابر وحده يعالج ألمه أو تكليفه، أما المصابر فيواجه قرنًا صابرًا قد يساويه أو يفوقه ويحاول زعزعة ثباته. لذلك تكون المصابرة أقرب إلى التزلزل وأحوج إلى قوة النفس وطول المدى.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، الصبر في وجه صابر.","url":""}]},{"id":"s3-1038","number":1038,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما دلالة مجيء ﴿وَاتَّقُوا اللَّهَ﴾ بعد الصبر والمصابرة والمرابطة؟","answer":"التقوى أعم من المراتب السابقة، فهي تحفظ المؤمن من مخالفة أمر الله في السلم والحرب، وفي القوة والضعف. وبها لا تتحول المصابرة إلى عدوان، ولا المرابطة إلى غاية منفصلة عن طاعة الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، عموم التقوى بعد مراتب الصبر.","url":""}]},{"id":"s4-1","number":1,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿اتَّقُوا رَبَّكُمُ﴾، دون أن يقال: اتقوا الله؟","answer":"افتتاح الخطاب باسم الرب يستحضر نعمة الخلق والتربية التي قررتها الآية، فيكون الأمر بالتقوى مبنيًا على رابطة الربوبية؛ ثم جاء الاسم الجليل في التقوى الثانية عند الحقوق التي يُتساءل بها والأرحام.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص575–576، تحت «بلاغة أسلوب الترقي في إقرار الألوهية».","url":""}]},{"id":"s4-2","number":2,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا وصف أصل البشر بأنه ﴿نَفْسٍ وَاحِدَةٍ﴾، ولم يصرح باسم آدم عليه السلام؟","answer":"جاء الوصف ﴿نفس واحدة﴾ لإبراز المعنى الجامع لا مجرد الاسم: فالناس جميعًا يرجعون إلى أصل إنساني واحد، ولذلك هم متساوون في أصل الخلقة ومتصل بعضهم ببعض وإن تباعدت أنسابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص572، تحت «دلالة حرف الجر ﴿من﴾ وتكراره».","url":""}]},{"id":"s4-3","number":3,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا اختير فعل ﴿بَثَّ﴾، ولم يقل: نشر منهما رجالًا ونساء؟","answer":"البث نشرٌ مع تفريق وتكثير في جهات واسعة، فهو يصور امتداد البشر من أصل واحد أجيالًا وأقطارًا، وهو أبلغ حركةً من مجرد النشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص565، تحت «شرح المفردات»، مدخل ﴿وبث﴾.","url":""}]},{"id":"s4-4","number":4,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿رِجَالًا كَثِيرًا وَنِسَاءً﴾، فوصف الرجال بالكثرة، دون أن يقال: ونساء كثيرات؟","answer":"ذِكر الكثرة مع الرجال يغني عنها في المعطوف، فالمعنى: رجالًا كثيرًا ونساءً كثيرات؛ وحذفها يمنع الثقل ويحفظ الفاصلة من غير أن ينفي كثرة النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص574، تحت «سر تخصيص الرجال بالكثرة دون النساء».","url":""}]},{"id":"s4-5","number":5,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا تكرر الأمر بالتقوى مرتين في آية واحدة: ﴿اتَّقُوا رَبَّكُمُ﴾ ثم ﴿وَاتَّقُوا اللَّهَ﴾؟","answer":"الأولى تقوى الرب الذي خلق البشر من نفس واحدة، والثانية تقوى الله في الحقوق المتبادلة والأرحام؛ فتجدد الأمر لاختلاف العلة والمجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص575، تحت «نكتة تكرار صيغة الأمر بالتقوي»","url":""}]},{"id":"s4-6","number":6,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"لماذا ختمت الآية بـ﴿رَقِيبًا﴾، ولم تختم بـ«حفيظًا» مثلًا؟","answer":"الرقيب من يلاحظ الشيء ولا يغيب عنه، وهو أنسب بأحكام الحقوق الخفية وصلات الأرحام؛ أما الحفظ فقد يدل على الصيانة، ولا يستحضر المراقبة والمحاسبة بالوضوح نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص580–581، تحت «الفروق المعجمية: الرقيب والحفيظ».","url":""}]},{"id":"s4-7","number":7,"surah":4,"verses":[1],"references":[{"surah":4,"verses":[1]}],"verseLabel":"النساء: 1","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿وَخَلَقَ مِنْهَا زَوْجَهَا﴾، بينما قال في الأعراف والزمر: ﴿وَجَعَلَ مِنْهَا زَوْجَهَا﴾؟","answer":"قال في النساء ﴿خلق منها زوجها﴾ لأن الكلام على أصل خلق آدم وحواء؛ والخلق ابتداء إيجاد. وقال في الأعراف والزمر ﴿جعل منها زوجها﴾ لأن الكلام على ما بعد ذلك من عموم بني آدم، أي جعل الأنثى زوجًا للذكر بعد خلقها؛ فالجعل حالة تالية للخلق في الغالب.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج2، ص32؛ منقول في Quranpedia، ملاحظة 48388","url":""}]},{"id":"s4-8","number":8,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى في حقوق اليتامى: ﴿وَآتُوا الْيَتَامَى أَمْوَالَهُمْ﴾، واختار الإيتاء دون الإعطاء؟","answer":"الإيتاء يشعر بإيصال الحق وتمكين صاحبه منه، لا بمجرد المناولة؛ ولذلك ناسب رد مال اليتيم كاملًا بوصفه حقًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص595، تحت «سر إيثار فعل الإيتاء على غيره».","url":""}]},{"id":"s4-9","number":9,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّهُ كَانَ حُوبًا كَبِيرًا﴾، واختار «الحوب» بدل «الإثم»؟","answer":"الحوب هو الإثم العظيم الذي يوقع في الحرج والهلاك، وفي اللفظ زجر أشد من الاسم العام للإثم، ولا سيما في أكل مال اليتيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص599–600، تحت «علة إيثار لفظ (الحوب) منكرًا».","url":""}]},{"id":"s4-10","number":10,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما الصلة بين الخوف من عدم القسط في اليتامى وبين قوله مباشرة: ﴿فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ﴾؟","answer":"الشرط والجواب مرتبطان: إذا خاف الولي ألا يعدل في اليتيمة التي تحت ولايته، في مهرها وحقوقها، ترك الزواج بها وتزوج من غيرها؛ فقد وسّع الله له الاختيار، فلا يحمله طلب الزواج على ظلمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص600، تحت عنوان «بلاغة التعبير بـ﴿وإن﴾ الشرطية»","url":""}]},{"id":"s4-11","number":11,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا طَابَ لَكُمْ﴾، دون أن يقال: من طاب لكم؟","answer":"أوثر ﴿ما﴾ لأن المقصود وصف النساء اللاتي يحل نكاحهن والصنف الطيب المباح منهن؛ فالنظر هنا إلى الصفة والحكم، لا إلى مجرد ذوات أشخاص معينين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص602–603، تحت «إيثار التعبير بالاسم الموصول ﴿ما﴾ دون ﴿من﴾».","url":""}]},{"id":"s4-12","number":12,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾، دون أن يقال: اثنتين أو ثلاثًا أو أربعًا؟","answer":"هذه صيغ توزيع على جماعة المخاطبين: فمنهم من يختار اثنتين، ومنهم من يختار ثلاثًا أو أربعًا، وليس المراد جمع الأعداد لكل واحد. ولهذا كان التعبير مناسبًا لاختلاف اختيار المخاطبين مع الوقوف عند العدد المأذون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص603–604، تحت عنوان «سر العطف بالواو في ﴿مثنى وثلاث ورباع﴾»","url":""}]},{"id":"s4-13","number":13,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا عطف الأعداد بالواو: ﴿مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾، ولم يعطفها بـ«أو» الدالة على التخيير؟","answer":"جاءت الواو للتقسيم والجمع على سبيل البدل: فمن المخاطبين من يختار اثنتين، ومنهم من يختار ثلاثًا، ومنهم من يختار أربعًا؛ وليست لجمع هذه الأعداد في ذمة رجل واحد، وإلا لقيل تسعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص603–604، تحت «سر العطف بالواو في ﴿مثنى وثلاث ورباع﴾».","url":""}]},{"id":"s4-14","number":14,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكَ أَدْنَى أَلَّا تَعُولُوا﴾، واختار هذا التعبير دون التصريح بـ«ألا تجوروا»؟","answer":"﴿تعولوا﴾ كناية عن الميل والجور؛ فأدى التعبير المعنى بطريق ألطف وأبلغ من التصريح بـ«تجوروا»، وجعل العدل كأنه استقامة يقابلها ميل الميزان.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص604، تحت «بلاغة التعبير عن العول بالكناية».","url":""}]},{"id":"s4-15","number":15,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا سمى المهور ﴿صَدُقَاتِهِنَّ﴾، ولم يقل: مهورهن؟","answer":"اشتق الاسم من الصدق؛ لأن المهر علامة صدق الرغبة في النكاح وتكريم المرأة، لا ثمنًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص605، تحت «نكتة اصطفاء لفظ الصدقة».","url":""}]},{"id":"s4-16","number":16,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا وصف إعطاء المهر بأنه ﴿نِحْلَةً﴾؟","answer":"وُصف المهر بالنحلة ليؤدَّى عن طيب نفس وسماحة، وليُبعد عن معنى الثمن والعوض المالي. وهو حق واجب للمرأة فرضه الله، لا تفضّل من الزوج عليها؛ فسماه هدية واجبة إكرامًا لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص606–607، تحت عنوان «تنوع دلالة النحلة بين الزوج والزوجة»","url":""}]},{"id":"s4-17","number":17,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا خُص الأكل بالذكر في قوله تعالى: ﴿فكلوه هنيئًا مريئًا﴾؟","answer":"المقصود إباحة الانتفاع بما طابت نفس المرأة ببذله من مهرها، وذُكر الأكل لأنه معظم وجوه التصرف المالي، فيشمل الإذن سائر التصرفات المباحة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص608، تحت عنوان «نكتة تخصيص لفظ (الأكل) بالذكر»","url":""}]},{"id":"s4-472","number":472,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما دلالة الجمع بين ﴿هنيئًا مريئًا﴾ في الإذن بالانتفاع بما طابت به نفس المرأة؟","answer":"هما وصفان لما يسوغ من الطعام ولا تنغيص فيه، وفي ورودهما هنا تأكيد لحل الانتفاع ومبالغة في الإباحة وإزالة التبعة عما بُذل عن طيب نفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص608، تحت عنوان «سر تذييل الفاصلة بالوصفين ﴿هنيئًا مريئًا﴾»","url":""}]},{"id":"s4-18","number":18,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا سمى أموال السفهاء ﴿أَمْوَالَكُمُ﴾، مع أنها أموالهم هم؟","answer":"أضاف أموال السفهاء إلى الجماعة لأن المال قوام المجتمع ولأن الولي مؤتمن عليه كأنه ماله؛ فيمنعه ذلك من إضاعته كما يمنع إضاعة مال نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص609، تحت «التعريف بالإضافة».","url":""}]},{"id":"s4-19","number":19,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا وصف الأموال بأنها ﴿الَّتِي جَعَلَ اللَّهُ لَكُمْ قِيَامًا﴾؛ وكيف يكون المال قيامًا للناس؟","answer":"المال مما يقيم شؤون الناس ويصلح أحوالهم؛ فوصفه بأنه قيام يبين حاجتهم إليه في مصالحهم ومعاشهم، وحاجتهم إلى حفظه وحسن تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص609، تحت عنوان «توجيه القراءات في لفظ ﴿قيامًا﴾»","url":""}]},{"id":"s4-20","number":20,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿وَارْزُقُوهُمْ فِيهَا﴾، دون أن يقال: وارزقوهم منها؟","answer":"﴿فيها﴾ تدعو إلى تنمية أصل المال والإنفاق من ريعه، كأن الرزق واقع في محيط المال لا مقتطع من أصله حتى يفنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص610، تحت «سر إيثار ﴿في﴾».","url":""}]},{"id":"s4-21","number":21,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ آنَسْتُمْ مِنْهُمْ رُشْدًا﴾، دون أن يقال: فإن علمتم منهم رشدًا؟","answer":"الإيناس إدراك يتولد من أمارات متكررة ظاهرة، فليس المطلوب ظن الرشد أو معرفته مرة، بل اختباره حتى يطمئن الولي إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص613، تحت «علة إيثار لفظ الإيناس على غيره».","url":""}]},{"id":"s4-22","number":22,"surah":4,"verses":[2,3,4,5,6],"references":[{"surah":4,"verses":[2,3,4,5,6]}],"verseLabel":"النساء: 2–6","question":"لماذا أمر بالإشهاد عند دفع مال اليتيم: ﴿فَأَشْهِدُوا عَلَيْهِمْ﴾، ثم ختم بـ﴿وَكَفَى بِاللَّهِ حَسِيبًا﴾؟","answer":"أُمر بالإشهاد لحفظ الحق وقطع النزاع في الظاهر، ثم خُتم بـ﴿وكفى بالله حسيبًا﴾ ليعلم الولي أن الشهود لا يغنون عن رقابة الله وحسابه؛ فهو الكافي في الشهادة والمحاسب على الخفي والظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص616–618","url":""}]},{"id":"s4-23","number":23,"surah":4,"verses":[3],"references":[{"surah":4,"verses":[3]}],"verseLabel":"النساء: 3","question":"ما الفرق بين التعبير بـ﴿أَلَّا تُقْسِطُوا فِي الْيَتَامَى﴾ والتعبير بـ﴿أَلَّا تَعْدِلُوا﴾ في تعدد الزوجات؟","answer":"القسط استعمل مع حقوق اليتامى لأنه العدل في الحكم وإيصال الحق، ثم استعمل العدل في تعدد الزوجات لأنه التسوية المطلوبة في المعاملة والنفقة؛ فتقارب المعنى لا يلغي دقة كل مقام.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 43211","url":""}]},{"id":"s4-24","number":24,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا كرر: ﴿لِلرِّجَالِ نَصِيبٌ﴾ و﴿وَلِلنِّسَاءِ نَصِيبٌ﴾، ولم يجمعهما في عبارة واحدة؟","answer":"كرر ﴿نصيب﴾ وأعاد لام الاستحقاق ليقرر حق كل من الرجال والنساء مستقلًا تقريرًا لا يحتمل التبعية أو السقوط، وليؤكد خصوصًا أن نصيب النساء فرض ثابت بعد أن كانت الجاهلية تحرمهن منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص624، تحت «فائدة تكرار لفظ النصيب».","url":""}]},{"id":"s4-25","number":25,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"ما سرّ تقديم الرجال على النساء في آية الميراث؟","answer":"قدم الرجال لأن السياق يراعي ما حمّلوا من القوامة والنفقة والمسؤولية الأسرية؛ فكان تقديم ذكرهم مناسبًا لهذا التكليف، مع إثبات حق النساء مستقلًا عقبهم مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص623، تحت «سر تقديم الرجال على النساء».","url":""}]},{"id":"s4-26","number":26,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا ذكر ﴿الْوَالِدَانِ﴾ ثم ﴿الْأَقْرَبُونَ﴾، مع أن الوالدين من الأقربين؟","answer":"خُص الوالدان بالذكر أولًا مع دخولهما في الأقربين لشدة قرابتهما وعظم منزلتهما وأصالتهما في باب الميراث، ثم جاء ﴿الأقربون﴾ ليعم سائر المستحقين بحسب درجات القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص624–625، تحت «الإطناب البلاغي بذكر العام بعد الخاص».","url":""}]},{"id":"s4-27","number":27,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا أعاد قوله: ﴿مِمَّا تَرَكَ الْوَالِدَانِ وَالْأَقْرَبُونَ﴾، ولم يكتف بضمير يعود إلى المذكور؟","answer":"أعيدت العبارة ظاهرة مع نصيب النساء ليأتي حكمهن مستقلًا كاملًا كحكم الرجال، وليتقرر أن مصدر استحقاق الفريقين واحد: ما ترك الوالدان والأقربون، فلا يبدو حق النساء تابعًا أو مفهومًا بطريق الضمير فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص626، تحت «بلاغة الإظهار في موضع الإضمار».","url":""}]},{"id":"s4-28","number":28,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"ما سرّ التعبير في قوله تعالى: ﴿نَصِيبًا مَفْرُوضًا﴾، دون أن يقال: حظًا معلومًا؟","answer":"النصيب حصة مخصوصة، و﴿مفروضًا﴾ تثبت أنها مقدرة ملزمة من الله لا منحة عائلية قابلة للمنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص628، تحت «بلاغة الإيجاز بالحذف، ودلالة الاختزال بـ﴿مفروضًا﴾».","url":""}]},{"id":"s4-29","number":29,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا حَضَرَ الْقِسْمَةَ﴾ بـ«إذا»، دون أن يقال: وإن حضر القسمة؟","answer":"جيء بـ﴿إذا﴾ لأن حضور هؤلاء عند قسمة الميراث أمر متوقع كثير الوقوع، فصيغ الحكم على تحقق الحالة؛ أما ﴿إن﴾ فتناسب ما يشك في حصوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص630، تحت «نكتة التعبير بـ﴿واذا﴾ دون ان»","url":""}]},{"id":"s4-30","number":30,"surah":4,"verses":[7,8],"references":[{"surah":4,"verses":[7,8]}],"verseLabel":"النساء: 7–8","question":"لماذا سمى ما يعطى الحاضرين عند القسمة رزقًا: ﴿فَارْزُقُوهُمْ مِنْهُ﴾، ولم يقل: فأعطوهم؟","answer":"سماه رزقًا ليشعرهم أن ما يصل إليهم ساقه الله من غير منة من الورثة، وليطيب نفوسهم وهم يشهدون قسمة المال؛ فليس مجرد مناولة، بل رزق يسد شيئًا من الحاجة ويصون الخاطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص634–636، تحت «علة تسمية العطاء رزقًا».","url":""}]},{"id":"s4-31","number":31,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"لماذا جمع بين الأمر بالتقوى والأمر بالقول السديد في حماية اليتامى؟","answer":"أمر بالتقوى لتضبط باطن الولي وخشيته من ظلم اليتيم، وبالقول السديد ليكون خطابه ووصيته مستقيمين مصيبين للحق؛ فحماية اليتيم تحتاج رقيبًا في القلب واستقامة في القول والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص646–649، تحت «نكتة التفريع بالفاء في فعل الاتقاء».","url":""}]},{"id":"s4-32","number":32,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"ما سرّ التعبير في قوله تعالى: ﴿قَوْلًا سَدِيدًا﴾ هنا، بينما قال قبلها: ﴿قَوْلًا مَعْرُوفًا﴾؟","answer":"السديد هو المصيب المستقيم الذي يسد موضع الخلل؛ فناسب مقام الوصية بحماية اليتيم، أما المعروف ففي مقام الملاطفة والعطاء لمن حضر القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص640، تحت «شرح المفردات»، مدخل ﴿سديدًا﴾.","url":""}]},{"id":"s4-33","number":33,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"ما سر الصورة المروعة في قوله: ﴿يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا﴾، مع أنهم يأكلون أموالًا؟","answer":"صوّر المال الحرام بحقيقته التي يصير إليها: نارًا تملأ البطون؛ فانتقل من ظاهر اللذة العاجلة إلى باطن العاقبة المروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص652–653، تحت «بلاغة المجاز المرسل في التنبيه على أداء حقوق الضعفاء».","url":""}]},{"id":"s4-34","number":34,"surah":4,"verses":[9,10],"references":[{"surah":4,"verses":[9,10]}],"verseLabel":"النساء: 9–10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَسَيَصْلَوْنَ سَعِيرًا﴾ بالسين، ولم يأت بها في فعل الأكل؟","answer":"لم تدخل السين على الأكل لأنه فعلهم الواقع الآن، ودخلت على ﴿سيصلون﴾ لأن صلي السعير جزاؤهم المستقبل؛ وهي مع ذلك تقرب الوعيد وتجعله كأنه وشيك محقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص654، تحت «سر دخول السين في فعل الصلي دون الأكل».","url":""}]},{"id":"s4-35","number":35,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿يُوصِيكُمُ اللَّهُ﴾، دون أن يقال: نوصيكم؟","answer":"إظهار الاسم الجليل يرفع الحكم من عرف الأسرة إلى وصية الله الملزمة، ويورث المهابة والتسليم في موضع تنازع النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص664–665، تحت «براعة إظهار فاعل الإيصاء».","url":""}]},{"id":"s4-36","number":36,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي أَوْلَادِكُمْ﴾، دون أن يقال: في أبنائكم؟","answer":"الأولاد يشملون الذكور والإناث، بخلاف الأبناء الذي قد يتبادر منه الذكور؛ فاختير اللفظ الأجمع لأصحاب الأنصبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص665، تحت «التعبير بـ﴿الأولاد﴾ دون ﴿الأبناء﴾ وغيره».","url":""}]},{"id":"s4-37","number":37,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ﴾، دون أن يقال: للرجل مثل حظ المرأتين؟","answer":"اختير الذكر والأنثى لأن الحكم متعلق بوصف الجنس لا بسن الرجولة والبلوغ، وجعل نصيبه معيارًا مضاعفًا يختصر صور القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص666–667، تحت «وجه التعبير بـ﴿الذكر﴾ و﴿الأنثى﴾ دون ﴿الرجال﴾ و﴿النساء﴾».","url":""}]},{"id":"s4-38","number":38,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿فَوْقَ اثْنَتَيْنِ﴾، دون أن يقال: اثنتين فما فوق؟","answer":"جاء ﴿فوق اثنتين﴾ نصًا في حكم الثلاث فأكثر، أما البنتان فأُلحق حكمهما بالثلثين من أدلة أخرى، منها حكم الأختين وما ثبت بالسنة؛ ففصل النص بين ما صرح به هنا وما يستفاد من البيان الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص668","url":""}]},{"id":"s4-39","number":39,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"لماذا ذكر فرض البنت الواحدة صراحة، ولم يذكر فرض الابن الواحد؟","answer":"صُرح بفرض البنت الواحدة لأن العرب كانوا يؤثرون البنين ويحرمون البنات من الميراث، فاحتاج حقها إلى بيان مستقل مؤكد يهدم ذلك العرف؛ أما حق الابن فكان معروفًا غير منكور عندهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص670، تحت «سر ذكر فرض البنت المنفردة دون الابن».","url":""}]},{"id":"s4-40","number":40,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"لماذا توسط قوله: ﴿آبَاؤُكُمْ وَأَبْنَاؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا﴾ تفاصيل الأنصبة؟","answer":"توسطت الجملة اعتراضًا يقطع تقدير الأنصبة بالهوى؛ فالإنسان لا يعلم أي آبائه وأبنائه أقرب نفعًا في الحقيقة. لذلك رد الله القسمة إلى علمه وحكمته، وطيب النفوس للرضا بالفرائض والتسليم لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص671–672، تحت «نكتة الإطناب بالجملة الاعتراضية».","url":""}]},{"id":"s4-41","number":41,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"لماذا ختمت أحكام المواريث هنا بـ﴿إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا﴾؟","answer":"الخاتمة تثبت إحاطة العلم بالمصالح ووضع الأمر بالجهاد والنهي عن الوهن موضع الحكمة؛ جواب قسمة المواريث أجنبي عن الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص673–674، تحت «التذييل وتشابه الأطراف في فاصلة الآية الكريمة».","url":""}]},{"id":"s4-42","number":42,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا عبر عن الزوجات بلفظ ﴿أَزْوَاجُكُمْ﴾، ولم يقل: زوجاتكم؟","answer":"لفظ «الزوج» يستحضر رابطة الزوجية وما يقتضيه عقدها؛ فناسب الكلام على الميراث الناشئ عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص690–691، تحت «الزوج والمرأة».","url":""}]},{"id":"s4-43","number":43,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَرَكَ أَزْوَاجُكُمْ﴾، فاستعمل «ما» وأجمل أنواع التركة؟","answer":"استعمل ﴿ما﴾ وأجمل التركة ليعم الحكم كل ما يتركه الميت من مال وعقار ومنقول وحقوق ومنافع مما يدخل في الإرث، فلا يقيده بنوع مخصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص682، تحت «نكتة إيجاز الحذف في قوله: ﴿ولكم نصف ما ترك أزواجكم﴾».","url":""}]},{"id":"s4-44","number":44,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا قُيّد تنفيذ الوصية والدَّين بقوله تعالى: ﴿غير مضار﴾؟","answer":"احتراسٌ يمنع اتخاذ الوصية أو الإقرار بالدَّين وسيلةً للإضرار بالورثة وانتقاص حقوقهم؛ كأن يُقرّ المورِّث بدَين لا حقيقة له ليحرمهم بعض المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص687، تحت «بلاغة الإطناب بالاحتراس في قوله: ﴿غير مضار﴾».","url":""}]},{"id":"s4-45","number":45,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا أعيد اسم الله في ﴿والله عليم حليم﴾ بعد ﴿وصية من الله﴾، ولم يقل: وهو عليم حليم؟","answer":"لزيادة التعظيم وإثارة المهابة في النفوس؛ فالتصريح باسم الله يستحضر صفات الجلال والكمال، ويكون أشد وقعًا من الضمير العائد إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص688، تحت «بلاغة الإظهار في موضع الإضمار في قوله تعالى: ﴿والله عليم حليم﴾».","url":""}]},{"id":"s4-46","number":46,"surah":4,"verses":[12],"references":[{"surah":4,"verses":[12]}],"verseLabel":"النساء: 12","question":"لماذا ختمت آية المواريث الأولى بـ﴿عَلِيمًا حَكِيمًا﴾، وختمت الثانية بـ﴿عَلِيمٌ حَلِيمٌ﴾؟","answer":"ختمت الأولى بـ﴿عليمًا حكيمًا﴾ لأنها أصل تفصيل الأنصبة، فناسبها العلم بالمصالح والحكمة في التقدير. وختمت الثانية بـ﴿عليم حليم﴾ بعد التحذير من المضارة؛ فهو يعلم المتحايل ويمهله حلمًا ولا يهمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص688–689، تحت «بلاغة التذييل وتشابه الأطراف في الآية الكريمة»؛ ولخاتمة الآية الأولى: ج6، ص673–674.","url":""}]},{"id":"s4-47","number":47,"surah":4,"verses":[13,14],"references":[{"surah":4,"verses":[13,14]}],"verseLabel":"النساء: 13–14","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ حُدُودُ اللَّهِ﴾ بعد أحكام المواريث؟","answer":"شُبهت الأحكام بحدود تفصل الحق من الباطل، فلا يجوز تجاوزها؛ وفي الإضافة إلى الله تعظيم لحرمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص696–697، تحت «دلالة الاستعارة التصريحية في قوله: ﴿تلك حدود الله﴾».","url":""}]},{"id":"s4-48","number":48,"surah":4,"verses":[13,14],"references":[{"surah":4,"verses":[13,14]}],"verseLabel":"النساء: 13–14","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الطائعين: ﴿خَالِدِينَ فِيهَا﴾ بالجمع، وقوله تعالى في العاصي: ﴿خَالِدًا فِيهَا﴾ بالإفراد؟","answer":"الجمع في أهل الجنة يناسب الأنس بالاجتماع والصحبة، فيزيد الترغيب، والإفراد في العاصي يصور الوحشة والانفراد بالعذاب، فيزيد التهديد؛ ولا يفيد انحصار العصاة في واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص702–703، تحت «نكتة التغاير بين ﴿خالدين﴾ جمعًا و﴿خالدًا﴾ مفردًا».","url":""}]},{"id":"s4-49","number":49,"surah":4,"verses":[13,14],"references":[{"surah":4,"verses":[13,14]}],"verseLabel":"النساء: 13–14","question":"ما سرّ التعبير في قوله تعالى عن الجنة: ﴿وَذَلِكَ الْفَوْزُ الْعَظِيمُ﴾، وقال عن النار: ﴿وَلَهُ عَذَابٌ مُهِينٌ﴾؟","answer":"سمي دخول الجنة فوزًا عظيمًا لأنه يجمع النجاة والنعيم والخلود والكرامة، أما متجاوز حدود الله فناسبه عذاب مهين؛ إذ قابل استكباره على الحكم بإذلاله مع الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص701–703، تحت «دلالة المقابلة بين الطائعين والعاصين».","url":""}]},{"id":"s4-50","number":50,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"لماذا أسند التوفي إلى الموت في قوله: ﴿حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ﴾؟","answer":"أُسند التوفي إلى الموت على طريق المجاز العقلي؛ لأنه السبب الظاهر الذي تنتهي به الحياة وتستوفى المدة، أما المتوفي حقيقة فالله، وتقبض الملائكة الروح بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص715، تحت «دلالة المجاز في قوله: ﴿يتوفاهن الموت﴾».","url":""}]},{"id":"s4-51","number":51,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلًا﴾، فنكر «سبيلًا» ولم يبينه؟","answer":"أُبهم السبيل وترك تعيينه لما يشرعه الله بعد ذلك، وفي هذا الإبهام تخويف وترهيب. وليس في التنكير ما يقتضي أن يكون الحكم اللاحق أخف أو أن يكون فرجًا موعودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص716، تحت «دلالة الاستعارة في قوله تعالى: ﴿أو يجعل الله لهن سبيلًا﴾».","url":""}]},{"id":"s4-52","number":52,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"لماذا جمع بين التوبة والإصلاح: ﴿فَإِنْ تَابَا وَأَصْلَحَا فَأَعْرِضُوا عَنْهُمَا﴾؟","answer":"التوبة رجوع باطني وترك للذنب، والإصلاح تصحيح عملي لما أفسداه وتقويم للسلوك؛ فلا يكفي الادعاء حتى يظهر أثره. وحذف متعلق ﴿أصلحا﴾ ليعم إصلاح النفس والعمل وما ترتب على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص719، تحت «سر حذف المتعلق من ﴿فإن تابا وأصلحا﴾».","url":""}]},{"id":"s4-53","number":53,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"ما دلالة صيغتي ﴿توابًا رحيمًا﴾ في ختام الأمر بالإعراض عمن تاب وأصلح؟","answer":"تدلان على سعة توبة الله ورحمته وشمولهما للتائبين، وعلى كثرة قبوله لتوبة عباده؛ وفي ذلك ترغيب للعاصي في التوبة وحث على المبادرة إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص721، تحت عنوان «دلالة صيغة المبالغة في اسمي الله تعالى الواردين في قوله: ﴿توابًا رحيمًا﴾»","url":""}]},{"id":"s4-473","number":473,"surah":4,"verses":[15,16],"references":[{"surah":4,"verses":[15,16]}],"verseLabel":"النساء: 15–16","question":"لماذا قُدّم ﴿توابًا﴾ على ﴿رحيمًا﴾ في قوله تعالى: ﴿إن الله كان توابًا رحيمًا﴾؟","answer":"في الترتيب بشارة بأن الرحمة تتبع قبول التوبة؛ فمن تاب الله عليه رحمه، وهو انتقال من إزالة أثر الذنب إلى الإنعام على التائب، مع أن أصل قبول التوبة نفسه من رحمته سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص721، تحت عنوان «نكتة تقديم اسم الله تعالى (التواب) على اسمه تعالى (الرحيم) في قوله: ﴿إن الله كان توابًا رحيمًا﴾»","url":""}]},{"id":"s4-54","number":54,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"ما دلالة تعدية التوبة بـ﴿عَلَى﴾ في قوله تعالى: ﴿إِنَّمَا التَّوْبَةُ عَلَى اللَّهِ﴾؟","answer":"﴿على﴾ ليست إلزامًا من غيره، بل وعد أوجبه الله على نفسه تفضلًا وفق حكمته؛ فهي تفيد تحقق القبول لمن استوفى وصف التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص726، تحت «دلالة ﴿على﴾ في قول الله تعالى: ﴿إنما التوبة على الله﴾».","url":""}]},{"id":"s4-55","number":55,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"لماذا وصف أصحاب الذنب بأنهم ﴿يَعْمَلُونَ السُّوءَ بِجَهَالَةٍ﴾؛ أكل ذنب يقع بجهالة؟","answer":"كل معصية جهالة من جهة إيثار اللذة العاجلة على علم العاقبة، ولو عرف صاحبها الحكم؛ فالجهالة هنا سفه العمل لا انعدام المعلومة فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص726–727، تحت «نكتة التقييد بالحال ﴿بجهالة﴾ في قوله تعالى: ﴿إنما التوبة على الله للذين يعملون السوء بجهالة﴾».","url":""}]},{"id":"s4-56","number":56,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"ما سرّ التعبير في قوله تعالى: ﴿ثُمَّ يَتُوبُونَ مِنْ قَرِيبٍ﴾، دون أن يقال: سريعًا؟","answer":"أي قبل حضور الموت، والزمن كله قريب أمام الآخرة؛ واللفظ يحث على المبادرة من غير حصرها في مدة حسابية.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص728، تحت «دلالة التعبير بالقرب في قوله تعالى: ﴿ثم يتوبون من قريب﴾».","url":""}]},{"id":"s4-57","number":57,"surah":4,"verses":[17,18],"references":[{"surah":4,"verses":[17,18]}],"verseLabel":"النساء: 17–18","question":"لماذا قابل بين من يتوب ﴿مِنْ قَرِيبٍ﴾ ومن ينتظر حتى ﴿حَضَرَ أَحَدَهُمُ الْمَوْتُ﴾؟","answer":"أبرزت المقابلة الفرق بين توبة تصدر عن اختيار قبل المعاينة، فتدل على رجوع صادق، وبين اعتراف اضطراري عند حضور الموت وانكشاف المصير، حين ينقطع زمن التكليف والعمل فلا تكون التوبة المقبولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص735، تحت «سر الاختلاف بين قوله: ﴿ثم يتوبون﴾ وقوله: ﴿قال إني تبت الآن﴾».","url":""}]},{"id":"s4-58","number":58,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا﴾، فصور معاملة النساء على هيئة ميراث؟","answer":"صور الفعل ميراثًا لأنه كان عادة جاهلية حقيقية: يعد ولي الميت زوجته جزءًا من تركته، فيحبسها أو يتزوجها أو يزوجها بغير رضاها. فكشف التعبير بشاعة معاملتها كمال موروث ونفى حل ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص746، تحت «بلاغة قوله تعالى: ﴿ترثوا النساء﴾ بين التشبيه والإيجاز».","url":""}]},{"id":"s4-59","number":59,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"لماذا عُلّق الشرط بـ«إن» في قوله تعالى: ﴿فإن كرهتموهن﴾، ولم يقل: إذا كرهتموهن؟","answer":"عُلّق الشرط بـ«إن» دون «إذا» لأن الكراهة غير متيقنة، فلا تفترض في كل زوجة؛ وفي ذلك حث على التجمل والصبر قبل ترتيب أثر الكراهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص751، تحت «دلالة تعليق الشرط بـ(إن) في قوله تعالى: ﴿فإن كرهتموهن﴾».","url":""}]},{"id":"s4-60","number":60,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"لماذا انتقل من كراهية النساء إلى التعبير العام: ﴿فَعَسَى أَنْ تَكْرَهُوا شَيْئًا وَيَجْعَلَ اللَّهُ فِيهِ خَيْرًا كَثِيرًا﴾؟","answer":"عمم فقال ﴿شيئًا﴾ ليجعل التوجيه قاعدة تتجاوز كراهية الزوجة: قد يكره الإنسان أمرًا وتخفى عنه عاقبته التي يجعل الله فيها خيرًا كثيرًا. وفي السياق يحجز ذلك عن العجلة في المضارة أو الفراق ويدعو إلى حسن العشرة والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص752–753، تحت «دلالة تنكير ﴿شيئًا﴾ ونكتة إقامة الظاهر موقع المضمر في قوله تعالى: ﴿فإن كرهتموهن فعسى أن تكرهوا شيئًا ويجعل الله فيه خيرًا كثيرًا﴾».","url":""}]},{"id":"s4-61","number":61,"surah":4,"verses":[19],"references":[{"surah":4,"verses":[19]}],"verseLabel":"النساء: 19","question":"لماذا نُكّر الخير ووُصف بالكثرة في قوله تعالى: ﴿ويجعل الله فيه خيرًا كثيرًا﴾؟","answer":"في التنكير تعظيم للخير وتفخيم لشأنه، ووصفه بالكثرة يزيد الترغيب في الصبر وترك المفارقة؛ فقد يكون فيما يكرهه الإنسان خير عظيم كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص754، تحت عنوان «نكتة التنكير في قوله تعالى: ﴿خيرًا كثيرًا﴾»","url":""}]},{"id":"s4-62","number":62,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا مثل لأعلى المهر بقوله: ﴿آتَيْتُمْ إِحْدَاهُنَّ قِنْطَارًا﴾؟","answer":"ذكر القنطار للمبالغة في كثرة المهر، ليقرر أن حق المرأة لا يجوز استرداده ولو بلغ أقصى ما يتصوره المخاطب من المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص761–762، تحت «بلاغة الكناية في قوله تعالى: ﴿وآتيتم إحداهن قنطارًا﴾».","url":""}]},{"id":"s4-63","number":63,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا جاء الاستفهام المنكر: ﴿أَتَأْخُذُونَهُ بُهْتَانًا وَإِثْمًا مُبِينًا﴾؟","answer":"الاستفهام إنكار وتعجيب يواجه الزوج بقبح الاسترداد بعد الإفضاء والميثاق، ويسميه بهتانًا وإثمًا ظاهرًا ليقطع كل تسويغ له.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص763، تحت «دلالة الاستفهام في قوله تعالى: ﴿أتأخذونه بهتانًا وإثمًا مبينًا﴾».","url":""}]},{"id":"s4-64","number":64,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا وصف الزواج بقوله: ﴿وَأَخَذْنَ مِنْكُمْ مِيثَاقًا غَلِيظًا﴾؛ وكيف تأخذ النساء الميثاق؟","answer":"الميثاق عهد الزواج المؤكد الذي تترتب عليه الحقوق والحرمة. وأُسند أخذه إلى النساء مجازًا؛ لأنهن أصحاب الحق فيه، فكأنهن أخذن العهد الذي أخذه الله على الأزواج.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص772–773، تحت «بلاغة المجاز العقلي في قوله تعالى: ﴿وأخذن منكم ميثاقًا غليظًا﴾».","url":""}]},{"id":"s4-65","number":65,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا زادت هذه الآية ﴿وَمَقْتًا﴾ في قوله: ﴿إِنَّهُ كَانَ فَاحِشَةً وَمَقْتًا وَسَاءَ سَبِيلًا﴾؟","answer":"أضيف ﴿مقتًا﴾ ليدل على شدة البغض فوق كونه فاحشة، ولأن العرب سموا نكاح امرأة الأب نكاح المقت؛ فجمع قبح الفعل وبغضه وسوء طريقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص781، تحت «بلاغة التذييل في قوله تعالى: ﴿إنه كان فاحشة ومقتًا وساء سبيلًا﴾».","url":""}]},{"id":"s4-66","number":66,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا وصف الفعل بثلاثة أوصاف متتابعة: ﴿فَاحِشَةً وَمَقْتًا وَسَاءَ سَبِيلًا﴾؟","answer":"﴿فاحشة﴾ لقبحه المتجاوز، و﴿مقتًا﴾ لشدة بغضه، و﴿ساء سبيلًا﴾ لفساد الطريق المؤدي إليه وآثاره؛ فاستوعبت الأوصاف ذات الفعل وموقف النفوس ومسلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص781، تحت «بلاغة التذييل في قوله تعالى: ﴿إنه كان فاحشة ومقتًا وساء سبيلًا﴾».","url":""}]},{"id":"s4-67","number":67,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ﴾، فزاد قيد ﴿مِنْ أَصْلَابِكُمْ﴾؟","answer":"القيد يخرج أدعياء التبني الذين كانت العرب تسميهم أبناء وتجري عليهم حكم أبناء النسب؛ فبيّن أن المراد هنا الأبناء الذين من الأصلاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص796–797، تحت «دلالة الوصف ﴿الذين من أصلابكم﴾ في قوله تعالى: ﴿وحلائل أبنائكم الذين من أصلابكم﴾».","url":""}]},{"id":"s4-68","number":68,"surah":4,"verses":[20,21,22,23],"references":[{"surah":4,"verses":[20,21,22,23]}],"verseLabel":"النساء: 20–23","question":"لماذا ختم تعداد المحرمات بقوله: ﴿إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا﴾؟","answer":"الخاتمة تقرر المغفرة لما وقع قبل نزول التحريم، فتناسب قوله: ﴿إلا ما قد سلف﴾؛ والغفران تجاوز عما مضى، والرحمة بيان لسبب هذا التجاوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص798، تحت «مناسبة ختم الآية باسمي الله تعالى: الغفور والرحيم».","url":""}]},{"id":"s4-69","number":69,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا اسْتَمْتَعْتُمْ بِهِ مِنْهُنَّ﴾ بـ«ما»، دون أن يقال: فمن استمتعتم بها؟","answer":"جيء بـ«ما» الموصولة بدل «من» مع إرادة النساء؛ للتفخيم من أمر الاستمتاع والتنبيه إلى خطره وما يترتب عليه من حقوق وواجبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص22، تحت «نكتة التعبير بـ(ما) دون (من) في قوله تعالى: ﴿فما استمتعتم به منهن﴾».","url":""}]},{"id":"s4-70","number":70,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا سمى المهور هنا ﴿أُجُورَهُنَّ﴾، بينما سماها قبل ذلك ﴿صَدُقَاتِهِنَّ﴾؟","answer":"﴿صدقاتهن﴾ تبرز صدق الرغبة والعطية عند إنشاء الزواج، و﴿أجورهن﴾ تبرز المهر حقًا واجب الأداء في مقابل عقد الاستمتاع المشروع، لا ثمنًا للمرأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص24، تحت «بلاغة الاستعارة في قوله تعالى: ﴿فآتوهن أجورهن فريضة﴾»؛ وللمقارنة بصدقاتهن: ج6، ص605.","url":""}]},{"id":"s4-71","number":71,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ لَمْ يَسْتَطِعْ مِنْكُمْ طَوْلًا﴾، دون أن يقال: قدرة أو مالًا؟","answer":"الطول سعة وفضل وقدرة ممتدة، فيشمل المال ومؤن النكاح والقدرة عليه، وهو أوسع من مجرد لفظ المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص33، تحت «دلالة التعبير بلفظ الطول بدل السعة».","url":""}]},{"id":"s4-72","number":72,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ فَتَيَاتِكُمُ الْمُؤْمِنَاتِ﴾، واختار «فتياتكم»؟","answer":"الفتاة لفظ ملاطفة يرد للأَمَة كرامتها الإنسانية، وإضافتهن إلى جماعة المؤمنين توثّق أخوة الدين وتمنع الازدراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص36–37، تحت «سر التعبير بالفتيات بدل الجواري والإماء».","url":""}]},{"id":"s4-73","number":73,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا جمع بين الأوصاف: ﴿مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ وَلَا مُتَّخِذَاتِ أَخْدَانٍ﴾؟","answer":"الإحصان يثبت العفة إيجابًا، ونفي السفاح ينفي العلاقة المعلنة، ونفي الأخدان ينفي العلاقة السرية؛ فاستوعب الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص42–44، تحت «نكتة تقديم ذكر المسافحات على متخذات الأخدان».","url":""}]},{"id":"s4-74","number":74,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا جاء الشرط بـ﴿إذا﴾ في ﴿فإذا أُحصنَّ﴾، وبـ﴿إن﴾ في ﴿فإن أتين بفاحشة﴾؟","answer":"جاءت «إذا» مع الإحصان لتأكيد وقوعه، ثم جاءت «إن» لتقليل احتمال الفاحشة ممن أُحصنت؛ فاختلاف الأداة يُبرز أن الإحصان هو المتوقع، والفاحشة خلاف ما يُنتظر معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص45، تحت «نكتة التغاير بين أداتي الشرط (إذا) و(إن) من قوله: ﴿فإذا أحصن فإن أتين﴾».","url":""}]},{"id":"s4-75","number":75,"surah":4,"verses":[24,25],"references":[{"surah":4,"verses":[24,25]}],"verseLabel":"النساء: 24–25","question":"لماذا وصف المشقة الجنسية بـ﴿الْعَنَتَ﴾ في قوله: ﴿لِمَنْ خَشِيَ الْعَنَتَ مِنْكُمْ﴾؟","answer":"العنت هو المشقة والضرر والهلاك؛ فصور الخوف من الوقوع في الزنا وما يجره من إثم وعقوبة وفساد، لا مجرد ضيق الرغبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص46، تحت «نكتة التعبير بالعنت بدل الوقوع في الزنى في قوله تعالى: ﴿ذلك لمن خشي العنت منكم﴾».","url":""}]},{"id":"s4-76","number":76,"surah":4,"verses":[25],"references":[{"surah":4,"verses":[25]},{"surah":5,"verses":[5]}],"verseLabel":"النساء: 25؛ المائدة: 5","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء عن الإماء: ﴿مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ﴾ بصيغة المؤنث، وقوله تعالى في المائدة: ﴿مُحْصِنِينَ غَيْرَ مُسَافِحِينَ﴾ بصيغة المذكر؟","answer":"في النساء الحكم منصب على الإماء اللاتي ينكحن عند العجز، فوصفت حالهن مباشرة بالعفة؛ وفي المائدة الخطاب للرجال الذين أُحلت لهم المحصنات، فحمّلهم هم أيضًا شرط الإحصان ونفي السفاح، فاختلاف الصيغة تابع لجهة التكليف.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص137؛ إسلام ويب، باب النساء: 25","url":""}]},{"id":"s4-77","number":77,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا جاء قوله تعالى: ﴿يريد الله أن يخفف عنكم﴾ في جملة مستقلة؟","answer":"استؤنفت الجملة لتقرر حكمًا عامًا دائمًا يشمل ما خففه الله عن عباده، وتبين عنايته بهم وتفضله عليهم؛ فالتخفيف قاعدة تتجاوز الحكم الجزئي السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص65، تحت عنوان «دلالة الاستئناف والفصل في: ﴿يريد الله أن يخفف عنكم وخلق الإنسان ضعيفًا﴾»","url":""}]},{"id":"s4-78","number":78,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا قابل بين إرادة الله التوبة وإرادة متبعي الشهوات: ﴿أَنْ تَمِيلُوا مَيْلًا عَظِيمًا﴾؟","answer":"إرادة الله ترد العباد إلى الاستقامة بالتوبة، وإرادة أهل الشهوات تصرفهم عنها ميلًا عظيمًا؛ فالمقابلة تكشف تضاد طريق الإصلاح وطريق الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص63، تحت «بلاغة العدول عن الجملة الاسمية إلى الجملة الفعلية».","url":""}]},{"id":"s4-79","number":79,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما الصلة بين قوله: ﴿يُرِيدُ اللَّهُ أَنْ يُخَفِّفَ عَنْكُمْ﴾ وبين ﴿وَخُلِقَ الْإِنْسَانُ ضَعِيفًا﴾؟","answer":"ضعف الإنسان عن مقاومة الشهوة وتحمل المشقة هو علة التخفيف، فجاء التشريع ملائمًا للفطرة ومغلقًا أبواب الحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص65–66، تحت «حسن التذييل في قوله: ﴿وخلق الإنسان ضعيفًا﴾».","url":""}]},{"id":"s4-80","number":80,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ﴾، فسمى مال الآخرين أموالكم؟","answer":"أموال المؤمنين كأنها مال الجماعة لاتصال المصالح، وفي الإضافة تذكير بأن أكل مال غيرك اعتداء على البنية المالية التي أنت منها، كما تحب صيانة مالك.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص75–76، تحت «بلاغة قوله ﴿لا تأكلوا أموالكم بينكم﴾ و﴿ولا تقتلوا أنفسكم﴾ بين الحقيقة والاستعارة والمجاز المرسل».","url":""}]},{"id":"s4-81","number":81,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما دلالة الاستدراك بقوله تعالى: ﴿إِلَّا أَنْ تَكُونَ تِجَارَةً عَنْ تَرَاضٍ مِنْكُمْ﴾ بعد النهي عن أكل الأموال بالباطل؟","answer":"الاستثناء منقطع في المعنى: ليست التجارة عن تراض من أكل المال بالباطل، بل هي الطريق المشروع المقابل له. وخصت بالذكر لأنها أبرز صور انتقال الأموال بين الناس بالاختيار والمعاوضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص73–74، تحت «دلالة الاستثناء المنقطع في قوله: ﴿إلا أن تكون تجارة عن تراض منكم﴾».","url":""}]},{"id":"s4-82","number":82,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَقْتُلُوا أَنْفُسَكُمْ﴾، دون أن يقال: لا يقتل بعضكم بعضًا؟","answer":"جعل قتل الآخر قتلًا للنفس لأن المؤمنين كالجسد الواحد، ولأن النهي يشمل قتل الإنسان نفسه وتعريضها للهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص75–76، تحت «بلاغة قوله ﴿لا تأكلوا أموالكم بينكم﴾ و﴿ولا تقتلوا أنفسكم﴾ بين الحقيقة والاستعارة والمجاز المرسل».","url":""}]},{"id":"s4-83","number":83,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا جمع بين ﴿عُدْوَانًا وَظُلْمًا﴾؟","answer":"العدوان تجاوز الحق بإفراط، والظلم إتيان ما لا يستحق؛ والجمع للتغاير والتأكيد والتنبيه إلى جر الصغير إلى الأعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص78–79، تحت «مناسبة الجمع بين العدوان والظلم في قوله: ﴿عدوانًا وظلمًا﴾».","url":""}]},{"id":"s4-84","number":84,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"لماذا صرح باسم الله في قوله: ﴿وَكَانَ ذَلِكَ عَلَى اللَّهِ يَسِيرًا﴾، ولم يقل: عليه يسيرًا؟","answer":"أُظهر الاسم الجليل لتربية المهابة وتأكيد أن الإصلاء بالنار، مع شدته، يسير على قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص80، تحت «نكتة العدول إلى الاسم الظاهر في قوله: ﴿وكان ذلك على الله يسيرًا﴾».","url":""}]},{"id":"s4-85","number":85,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما سرّ التعبير في قوله تعالى: ﴿كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ﴾ بالبناء للمجهول، دون أن يقال: ما نهاكم الله عنه؟","answer":"بُني ﴿كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ﴾ للمفعول لأن المقام معقود بالفعل ووقوعه لا بتعيين فاعله، أو لأن الفاعل معلوم من السياق؛ فبرز الأثر المقصود من غير تشتيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص82، تحت «نكتة التعبير بصيغة المبني للمفعول في قوله ﴿تنهون﴾».","url":""}]},{"id":"s4-86","number":86,"surah":4,"verses":[26,27,28,29,30,31],"references":[{"surah":4,"verses":[26,27,28,29,30,31]}],"verseLabel":"النساء: 26–31","question":"ما المراد بالسيئات في قوله تعالى: ﴿نكفر عنكم سيئاتكم﴾ بعد اشتراط اجتناب الكبائر؟","answer":"المراد بالسيئات هنا الصغائر في مقابل الكبائر التي أُمر باجتنابها. ويبين المصدر أن اجتناب الكبائر يشمل أداء الواجبات أيضًا، لأن ترك الواجب قد يكون من الكبائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص81–82، تحت عنوان «براعة الكلام بين الحذف والذكر في قوله: ﴿إن تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم﴾»","url":""}]},{"id":"s4-87","number":87,"surah":4,"verses":[26],"references":[{"surah":4,"verses":[26]}],"verseLabel":"النساء: 26","question":"لماذا رُتبت المقاصد هكذا: ﴿لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ… وَيَتُوبَ عَلَيْكُمْ﴾؛ فقدم البيان ثم الهداية ثم التوبة؟","answer":"بدأ بالبيان لأنه يكشف الأحكام، ثم بالهداية إلى سنن الصالحين للعمل بها، ثم بالتوبة لإزالة أثر التقصير؛ فترتيبها ينتقل من معرفة الطريق إلى سلوكه ثم معالجة الزلل.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031","url":""}]},{"id":"s4-88","number":88,"surah":4,"verses":[26,27],"references":[{"surah":4,"verses":[26,27]}],"verseLabel":"النساء: 26–27","question":"لماذا عُدِّي فعل الإرادة باللام: ﴿يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ﴾، ثم عُدِّي بـ«أن»: ﴿يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ﴾؟","answer":"في ﴿يريد الله ليبين لكم﴾ تحتمل اللام أن تكون زائدة للتوكيد، أو لام تعليل لمفعول محذوف، نحو: يريد الله تشريع ذلك ليبين ويهدي؛ فازدادت العبارة توكيدًا لمقاصد متعددة. أما ﴿يريد أن يتوب عليكم﴾ فالتوبة هي المراد المباشر، فنصب الفعل بـ﴿أن﴾.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031","url":"https://quranpedia.net/note/48031"}]},{"id":"s4-89","number":89,"surah":4,"verses":[27],"references":[{"surah":4,"verses":[27]}],"verseLabel":"النساء: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ يُرِيدُ أَنْ يَتُوبَ عَلَيْكُمْ﴾ فقدم اسم الله، بينما قال قبلها وبعدها: ﴿يُرِيدُ اللَّهُ﴾؟","answer":"قُدم اسم الله في ﴿والله يريد أن يتوب عليكم﴾ لمقابلة إرادته الرحيمة بإرادة متبعي الشهوات في الجملة التالية؛ أما الموضعان الآخران فالمقصود تعداد ما يريده الله من بيان وتخفيف، فجرى الفعل أولًا.","sources":[{"label":"فاضل السامرائي، *أسئلة بيانية في القرآن الكريم*، ج1، ص42–46؛ منقول في Quranpedia، ملاحظة 48031","url":"https://quranpedia.net/note/48031"}]},{"id":"s4-90","number":90,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما دلالة عموم الخطاب في قوله تعالى: ﴿وَلَا تَتَمَنَّوْا مَا فَضَّلَ اللَّهُ بِهِ بَعْضَكُمْ عَلَى بَعْضٍ﴾ دون تخصيص الرجال أو النساء؟","answer":"جاء ﴿بَعْضَكُمْ عَلَى بَعْضٍ﴾ عامًا ليشمل كل صور التفاوت التي قد تثير التمني والحسد بين الرجال والنساء وبين أفراد الجنس الواحد؛ فالعلاج موجه إلى النفس الإنسانية كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص88–89، تحت «براعة الإيجاز في قوله: ﴿ما فضل الله به بعضكم على بعض﴾».","url":""}]},{"id":"s4-91","number":91,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلرِّجَالِ نَصِيبٌ مِمَّا اكْتَسَبُوا وَلِلنِّسَاءِ نَصِيبٌ مِمَّا اكْتَسَبْنَ﴾، فكرر «نصيب»؟","answer":"تكرار ﴿نَصِيبٌ﴾ يجعل لكل من الرجال والنساء حصة مستقلة مما اكتسب، فلا يذوب حكم أحدهما في الآخر؛ كما يوازن بينهما في ارتباط الجزاء بالسعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص90، تحت «بديع المقابلة في قوله ﴿للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن﴾».","url":""}]},{"id":"s4-92","number":92,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ﴾، وحذف ما يُسأل؟","answer":"حُذف المتعلق في ﴿وَاسْأَلُوا اللَّهَ مِنْ فَضْلِهِ﴾ لأن السياق يدل عليه، ولأن تركه يفتح المعنى على كل ما يناسب المقام؛ فالحذف إيجاز وتعميم لا نقص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص91، تحت «نكتة حذف المفعول في قوله: ﴿واسألوا الله من فضله﴾».","url":""}]},{"id":"s4-93","number":93,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِكُلٍّ جَعَلْنَا مَوَالِيَ﴾، دون أن يقال: ورثة؟","answer":"الموالي هم من تربطهم بالميت ولاية قرابة أو ولاء فيلون أمر ميراثه ويستحقونه؛ فاللفظ أوسع دلالة من لفظ ﴿ورثة﴾ من جهة رابطة القرب والولاية التي نشأ عنها الإرث.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص96، تحت «التنبيه على علاقتهم بالموروث، والتعليل لاستحقاقهم الإرث».","url":""}]},{"id":"s4-94","number":94,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿الرِّجَالُ قَوَّامُونَ عَلَى النِّسَاءِ﴾، دون أن يقال: الذكور؟","answer":"لأن وصف الرجولة يستحضر معاني الشهامة والمروءة والحزم والنخوة، وهي صفات تناسب القيام بالرعاية والحماية؛ فاختيار «الرجال» يلفت إلى مقتضيات هذه المسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص105، تحت «نكتة التعبير بـ﴿الرجال﴾».","url":""}]},{"id":"s4-95","number":95,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا اختيرت صيغة المبالغة ﴿قَوَّامُونَ﴾، ولم يقل: قائمون؟","answer":"صيغة «قوامون» تفيد كثرة القيام بشؤون النساء والاعتناء بحفظهن وأداء حقوقهن، وتدل على دوام هذه المسؤولية وتنوع أعمالها؛ فناسبت المقام أكثر من مجرد «قائمون».","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص106، تحت «دلالة التعبير بصيغة المبالغة ﴿قوامون﴾».","url":""}]},{"id":"s4-96","number":96,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا فَضَّلَ اللَّهُ بَعْضَهُمْ عَلَى بَعْضٍ﴾، دون أن يقال صراحة: الرجال على النساء؟","answer":"عدل إلى «بعضهم على بعض» لتجنب إيهام تفضيل كل رجل على كل امرأة، ولإبقاء التفضيل موزعًا داخل الجماعة بحسب ما أقيمت عليه القوامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص107–108، تحت «مناسبة قوله: ﴿بعضهم على بعض﴾».","url":""}]},{"id":"s4-97","number":97,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا رتب علاج النشوز هكذا: الوعظ، ثم الهجر في المضاجع، ثم الضرب؟","answer":"يفيد السياق التدرج من الأخف إلى الأشد، والاقتصار على الأخف متى حصل به المقصود؛ فإذا زال النشوز لم يجز تجاوز ذلك إلى ما بعده. فالترتيب مرتبط بتحقيق الإصلاح لا بإيقاع جميع الإجراءات.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص114–115، تحت «مناسبة الجمع بين المعطوفات في قوله: ﴿فعظوهن واهجروهن في المضاجع واضربوهن﴾».","url":""}]},{"id":"s4-98","number":98,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا ختمت آية القوامة بـ﴿إِنَّ اللَّهَ كَانَ عَلِيًّا كَبِيرًا﴾؟","answer":"الخاتمة تهديد لمن يبغي بعد الطاعة؛ فإن علت يد الزوج فالله أعلى منه وأكبر، فيكف ذلك عن التسلط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص118–119، تحت «حسن التذييل في قوله: ﴿إن الله كان عليًا كبيرًا﴾».","url":""}]},{"id":"s4-99","number":99,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"لماذا عبر عن النزاع الزوجي بقوله: ﴿شِقَاقَ بَيْنِهِمَا﴾؟","answer":"الشقاق يصور كل واحد في شق غير شق الآخر، فهو انشقاق وتباعد بعد ائتلاف حسي أو معنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص126، تحت «مجاز التعبير في قوله: ﴿وإن خفتم شقاق بينهما﴾».","url":""}]},{"id":"s4-100","number":100,"surah":4,"verses":[32,33,34,35],"references":[{"surah":4,"verses":[32,33,34,35]}],"verseLabel":"النساء: 32–35","question":"إلى من يعود الضمير في قوله: ﴿إِنْ يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا﴾، ولماذا جاء محتملًا؟","answer":"يحتمل أن يعود إلى الحكمين، أي إن قصدا الإصلاح وفق الله مسعاهما، وأن يعود إلى الزوجين، أي إن صدقت إرادتهما أصلح الله بينهما؛ والاحتمال يجمع مسؤولية الوساطة وإرادة الزوجين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص129–130، تحت عنوان «براعة التعبير بالضمير؛ لتكثير المعنى في قوله: ﴿إن يريدا إصلاحًا يوفق الله بينهما﴾»","url":""}]},{"id":"s4-101","number":101,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا أعيدت الباء في قوله تعالى: ﴿وبذي القربى﴾ في آية الحقوق، خلاف نظيرها في البقرة؟","answer":"أعيدت الباء مع ذي القربى لتأكيد الإحسان إليهم والاعتناء بحقهم، كأنه يستأنف الأمر به. وفي إعادة الباء في النساء، خلاف نظير البقرة، توكيد ومبالغة في صلة القرابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص140، تحت «دلالة إعادة حرف الجر في قوله: ﴿وبذي القربى﴾».","url":""}]},{"id":"s4-102","number":102,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا فرق بين ﴿الْجَارِ ذِي الْقُرْبَى﴾ و﴿الْجَارِ الْجُنُبِ﴾؟","answer":"الجار ذو القربى من اجتمع له حق الجوار والقرب نسبًا أو دارًا، والجار الجنب هو البعيد أو غير القريب؛ فشملت الوصية درجتي الجوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص141، تحت «دلالة المغايرة في التعبير بين قوله: ﴿والجار ذي القربى﴾ وقوله: ﴿والجار الجنب﴾».","url":""}]},{"id":"s4-103","number":103,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"من هو ﴿الصَّاحِبِ بِالْجَنْبِ﴾، ولماذا جاء بهذا التعبير الواسع؟","answer":"هو من لازم الإنسان إلى جنبه في سفر أو دراسة أو عمل أو مجلس ونحوها، فجاء الوصف واسعًا ليشمل صور الصحبة العارضة والدائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص141، تحت «دلالة الباء في قوله: ﴿والصاحب بالجنب﴾».","url":""}]},{"id":"s4-104","number":104,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا جمع بين ﴿مُخْتَالًا فَخُورًا﴾ من غير حرف عطف بينهما؟","answer":"ترك العطف لقرب الوصفين في المعنى والأثر، ولأن الاختيال الباطن والظاهر سبب للفخر بالقول والفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص142–143، تحت «حسن التذييل في قوله تعالى: ﴿إن الله لا يحب من كان مختالًا فخورًا﴾».","url":""}]},{"id":"s4-105","number":105,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا جمع في وصف البخلاء بين: يبخلون، ويأمرون الناس بالبخل، ويكتمون ما آتاهم الله؟","answer":"ذكرت الآية ثلاث جهات: بخلهم في أنفسهم، وأمرهم غيرهم بالبخل، وكتمان ما آتاهم الله من فضله. فالعطف يجمع صفات مستقلة من البخل، ويبين انتقاله من عمل صاحبه إلى إفساد غيره وإخفاء النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص150، تحت «توجيه عطف جمل وجوه البخل».","url":""}]},{"id":"s4-106","number":106,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما مناسبة وصف العذاب بـ﴿مهينًا﴾ بعد ذكر البخل وكتمان فضل الله؟","answer":"الإهانة هنا جزاء من جنس العمل؛ فمن أهان نعمة الله بالبخل بها وإخفائها، استحق عذابًا يهينه. فالوصف يصل العقوبة بصورة الجحود المذكورة في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص151، تحت «علة وضع الظاهر موضع المضمر».","url":""}]},{"id":"s4-107","number":107,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا سمى الشيطان ﴿قَرِينًا﴾، ولم يقل: صاحبًا؟","answer":"القرين صاحب ملازم يقرن نفسه بالإنسان ويخالطه حتى كأنهما شيء واحد، فهو أخص وأشد اتصالًا من مطلق الصاحب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص155–156، تحت «بديع السجع في فواصل الآي».","url":""}]},{"id":"s4-108","number":108,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا تقدم الإنفاق على الإيمان في آية، وتقدم الإيمان على الإنفاق في الآية التالية؟","answer":"قدم الإيمان في مقام التحريض لأنه الأصل ولا اعتداد بالإنفاق دونه، وقدم الإنفاق في وصف المرائين لمناسبته البخل والأمر به قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص157–158، تحت «نكتة تقديم الإيمان هنا، وتأخيره في الآية السابقة».","url":""}]},{"id":"s4-109","number":109,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ﴾، فجمع بين «مثقال» و«ذرة»؟","answer":"﴿مِثْقَالَ﴾ يحدد وزن الشيء ومقداره، و﴿ذَرَّةٍ﴾ تمثل غاية الصغر؛ فاجتماعهما ينفي أن يقع الظلم في أدنى مقدار يمكن وزنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص166، تحت «لطيفة التصوير البياني في التشبيه التمثيلي».","url":""}]},{"id":"s4-110","number":110,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا﴾، دون أن يقال: من عنده؟","answer":"﴿مِنْ لَدُنْهُ﴾ تدل على قرب الاختصاص وصدور الأجر تفضلًا من خزائن الله مباشرة، فهي أخص من مطلق ﴿من عنده﴾ وأقوى في تشريف العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص167–168، تحت «فائدة التعبير بالظرف ﴿لدن﴾ دون ﴿عند﴾».","url":""}]},{"id":"s4-111","number":111,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا خاطب النبي ﷺ في قوله: ﴿وَجِئْنَا بِكَ عَلَى هَؤُلَاءِ شَهِيدًا﴾، ولم يقل: وجئنا برسولهم؟","answer":"الخطاب المباشر يستحضر شخص النبي ﷺ في مشهد الشهادة، فيزيد الموقف تهويلًا ويخصه بالتشريف بدل الإخبار عنه بالغائب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص173–174، تحت «بلاغة الالتفات في الآية».","url":""}]},{"id":"s4-112","number":112,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿لَوْ تُسَوَّى بِهِمُ الْأَرْضُ﴾، دون أن يقال: لو يسوَّون بالأرض؟","answer":"الباء تصورهم مادة للتسوية مختلطين بالأرض، لا مجرد أناس تسوى الأرض عليهم؛ لشدة تمنيهم الزوال من هول العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص175–176، تحت «توجيه القراءات في ﴿تسوى﴾».","url":""}]},{"id":"s4-113","number":113,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا يَكْتُمُونَ اللَّهَ حَدِيثًا﴾، مع ورود ما يدل على كتمانهم في مواضع أخرى؟","answer":"يقع الكتمان في طور من الموقف، ثم تشهد الجوارح وتظهر الحقائق فلا يملكون كتمان حديث عن الله؛ فتختلف أحوال يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص291–292، تحت «سؤال عن بيان مواطن الاختلاف بين ما يحتمل التعارض في الآيات». يتناول القسم آية النساء:42 صراحة، والوجه الثالث ص292 يبين شهادة الجوارح بعد الكتمان.","url":""}]},{"id":"s4-114","number":114,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى﴾، دون أن يقال: لا تصلوا؟","answer":"النهي عن القرب أبلغ من النهي عن الفعل؛ لأنه يمنع مقدماته والدخول فيه قبل زوال المانع، فيصون حرمة الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص185، تحت «سر النهي عن القرب دون الفعل».","url":""}]},{"id":"s4-115","number":115,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا جعل الغاية: ﴿حَتَّى تَعْلَمُوا مَا تَقُولُونَ﴾، ولم يقل: ما تفعلون؟","answer":"القول أعم من المركب والمفرد، ويشمل المفهوم والهذيان؛ ولأن اختلال العمل يسبق اختلال القول جعل إدراك القول حدًا ظاهرًا لزوال السكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص186–187، تحت «نكتة إيثار لفظ القول على الكلام والفعل».","url":""}]},{"id":"s4-116","number":116,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا استثنى من الجنابة ﴿إِلَّا عَابِرِي سَبِيلٍ﴾؟","answer":"الاستثناء رخصة للجنب في عبور المسجد عند الحاجة من غير مكث، مراعاة للحاجة ودفعًا للحرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص187، تحت «دلالة تقديم المستثنى قبل تمام الكلام».","url":""}]},{"id":"s4-117","number":117,"surah":4,"verses":[36,37,38,39,40,41,42,43],"references":[{"surah":4,"verses":[36,37,38,39,40,41,42,43]}],"verseLabel":"النساء: 36–43","question":"لماذا ختمت آية الطهارة بـ﴿إِنَّ اللَّهَ كَانَ عَفُوًّا غَفُورًا﴾؟","answer":"الفاصلة تقرر حكم الرخصة؛ عفا الله عن إلزام العاجز بالغسل أو الوضوء، وغفر ورخص ويسر، واقتران الوصفين يذكر بأصل كمال الطهارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص190–191، تحت «توجيه فاصلة الآية الكريمة».","url":""}]},{"id":"s4-118","number":118,"surah":4,"verses":[43],"references":[{"surah":4,"verses":[43]},{"surah":5,"verses":[6]}],"verseLabel":"النساء: 43؛ المائدة: 6","question":"ما سرّ التعبير في قوله تعالى في تيمم النساء: ﴿فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ﴾، وزاد في المائدة: ﴿مِنْهُ﴾؟","answer":"آية المائدة فصّلت أحكام الطهارة ابتداءً، فزاد ﴿منه﴾ ليصرح بأن المسح يكون من الصعيد الطيب؛ أما النساء فجاء ذكر التيمم ضمن النهي عن الصلاة حال اختلال الإدراك، فناسب الإيجاز اعتمادًا على دلالة ﴿صعيدًا طيبًا﴾.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص138؛ إسلام ويب، باب النساء: 43","url":""}]},{"id":"s4-119","number":119,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا صور اختيارهم الضلالة بالشراء: ﴿يَشْتَرُونَ الضَّلَالَةَ﴾؟","answer":"صوّر اختيارهم الضلالة شراءً؛ لأنهم بذلوا الهدى الذي عرفوه وأخذوا بدله ما يضرهم، فكانت صفقة خاسرة عن قصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص197، تحت «سر استعارة لفظ الاشتراء».","url":""}]},{"id":"s4-120","number":120,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا عُرّف ﴿السبيل﴾ في قوله تعالى: ﴿ويريدون أن تضلوا السبيل﴾؟","answer":"التعريف للعهد؛ فالمراد طريق الحق المعروف البيّن، لا مطلق طريق. وبذلك يصور السياق إرادتهم صرف المخاطبين عن الطريق المستقيم الذي يوصل إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص198، تحت «دلالة (الـ) التعريف في ﴿السبيل﴾».","url":""}]},{"id":"s4-121","number":121,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا صرح باسم الله مرتين: ﴿وَاللَّهُ أَعْلَمُ بِأَعْدَائِكُمْ وَكَفَى بِاللَّهِ وَلِيًّا﴾؟","answer":"تكرار الاسم الجليل يجعل كل كفاية مستقلة: العلم بمكر الأعداء، ثم الولاية، ثم النصرة، وفيه تسلية وتقوية للتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص209، تحت «نكتة إظهار اسم الله الأعظم».","url":""}]},{"id":"s4-122","number":122,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا جمع بين ﴿وَلِيًّا﴾ و﴿نَصِيرًا﴾؟","answer":"اجتمع في الولاية والنصرة كفاية الله لعباده: يتولى أمرهم ويؤيدهم على أعدائهم، فيطمئن المؤمن إلى رعايته ونصره ولا يخشى عداوة من سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص209، تحت عنوان «نكتة إظهار اسم الله الأعظم»","url":""}]},{"id":"s4-123","number":123,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِهِ﴾، دون أن يقال: يغيرون الكلام؟","answer":"التحريف إمالة الكلام عن وجهه لفظًا أو معنى، فالفعل يصور نقل الدلالة من موضعها المقصود لا مجرد الكذب المنفصل عن النص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص214–215، تحت «دلالة معنى التحريف بين الحقيقة والمجاز».","url":""}]},{"id":"s4-124","number":124,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"كيف احتمل قولهم ﴿واسمع غير مسمع﴾ ظاهر التوقير وباطن الإساءة؟","answer":"يمكن أن تُفهم «غير مسمع» على معنى: لا أسمعك الله مكروهًا، فتبدو دعاءً بالخير؛ وتحتمل الدعاء بألّا يسمع، فتكون إساءة. استغلوا احتمال اللفظ لستر الطعن بظاهر الأدب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص217–219، تحت «بديع التوجيه في قوله تعالى: ﴿واسمع غير مسمع وراعنا﴾».","url":""}]},{"id":"s4-125","number":125,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا سمي تحريفهم ﴿لَيًّا بِأَلْسِنَتِهِمْ﴾؟","answer":"اللي يصور فتل اللسان وصرف اللفظ عن ظاهره إلى معنى خبيث، مع إبقاء صورة تسمح لهم بالتورية والبراءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص220–221، تحت «سر إيثار لفظ (اللي) دون غيره».","url":""}]},{"id":"s4-126","number":126,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿آمِنُوا بِمَا نَزَّلْنَا مُصَدِّقًا لِمَا مَعَكُمْ﴾، ولم يسم القرآن والتوراة؟","answer":"المنزل هو القرآن المعروف، و«ما معكم» يستحضر صلتهم بالتوراة ويلزمهم بما في أيديهم، فيقيم التصديق حجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص234–235، تحت «إيثار الاسم الموصول (ما) دون العلم».","url":""}]},{"id":"s4-127","number":127,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا هدد بطمس ﴿وُجُوهًا﴾ منكرة، ولم يقل: وجوهكم؟","answer":"التنكير للتهويل والتكثير، ومعه لطف بعدم مواجهتهم بلفظ «وجوهكم» واستدعاء لهم إلى الإيمان قبل العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص236، تحت «السر في تنكير الوجوه دون وصف».","url":""}]},{"id":"s4-128","number":128,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سر الصورة في قوله: ﴿نَطْمِسَ وُجُوهًا فَنَرُدَّهَا عَلَى أَدْبَارِهَا﴾؟","answer":"الصورة تحتمل محو معالم الوجه حتى يصير كالقفا، ورد أصحابه القهقرى إلى الضلالة؛ وفي الحالين وعيد بالانتكاس الحسي والمعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص237–238، تحت «دلالة الفاء بين التسبيب والتعقيب في قوله: ﴿فنردها على أدبارها﴾».","url":""}]},{"id":"s4-129","number":129,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا خيّر الوعيد بين طمس الوجوه وبين اللعن: ﴿أَوْ نَلْعَنَهُمْ كَمَا لَعَنَّا أَصْحَابَ السَّبْتِ﴾؟","answer":"نوعت «أو» التهديد بين الطمس واللعن، وشُبه اللعن بما وقع لأصحاب السبت لتذكيرهم بعقوبة يعرفونها وتشديد الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص240–241، تحت «بلاغة التشبيه المرسل».","url":""}]},{"id":"s4-130","number":130,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ﴾، ثم قال: ﴿وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾؛ فلم يذكر المشيئة مع الشرك؟","answer":"أكد النفي لأن الشرك ناقض لأصل التوحيد الذي تبنى عليه المغفرة، وعلق ما دونه بالمشيئة لأنه لا يهدم أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص244–245، تحت «سر تكرار ذكر الفعل (يغفر)».","url":""}]},{"id":"s4-131","number":131,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"ما سرّ التعبير في قوله تعالى: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يُزَكُّونَ أَنْفُسَهُمْ﴾، دون أن يقال: ألم تسمع؟","answer":"هي رؤية علم وتعجيب تجعل حال المزكين أنفسهم كالمشاهد المحقق، فتكون أبلغ من مجرد سماع خبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص253–254، تحت «دلالة الاستفهام الداخل على حرف النفي».","url":""}]},{"id":"s4-132","number":132,"surah":4,"verses":[44,45,46,47,48,49,50],"references":[{"surah":4,"verses":[44,45,46,47,48,49,50]}],"verseLabel":"النساء: 44–50","question":"لماذا قابل تزكيتهم أنفسهم بقوله: ﴿بَلِ اللَّهُ يُزَكِّي مَنْ يَشَاءُ﴾؟","answer":"«بل» تبطل دعواهم وتنقل الحكم إلى الله وحده؛ فالتزكية الحقيقية فضل منه وعلم بالسرائر لا شهادة المرء لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص254–255، تحت «سر الإضراب بعد الاستفهام».","url":""}]},{"id":"s4-133","number":133,"surah":4,"verses":[46],"references":[{"surah":4,"verses":[46]},{"surah":5,"verses":[13,41]}],"verseLabel":"النساء: 46؛ المائدة: 13، 41","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿يُحَرِّفُونَ الْكَلِمَ عَنْ مَوَاضِعِهِ﴾، وقوله تعالى في المائدة: ﴿مِنْ بَعْدِ مَوَاضِعِهِ﴾؟","answer":"﴿عن مواضعه﴾ أعم في إمالة الكلام عن وجهه بتأويل أو تبديل، أما ﴿من بعد مواضعه﴾ فتبرز أنهم عرفوا مواضعه الثابتة ثم أبطلوا العمل بها، ولا سيما حكم الرجم؛ فكانت أشد في وصف التحريف عن علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص162، تحت «(من بعد مواضعه) و(عن مواضعه)»، في المقارنة بين المائدة: 41 والنساء: 46.","url":""}]},{"id":"s4-134","number":134,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿يُؤْمِنُونَ بِالْجِبْتِ وَالطَّاغُوتِ﴾، واستعمل الإيمان لما هو باطل؟","answer":"سمّي تصديقهم بالجبت والطاغوت إيمانًا على المشاكلة التقديرية؛ إذ كان مقتضى إيتائهم الكتاب أن يؤمنوا بالله، فجاء اللفظ نفسه فيما ناقض ذلك، فكشف شدة المفارقة والتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص261، تحت «سر المشاكلة في الآية».","url":""}]},{"id":"s4-135","number":135,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما دلالة وصفهم الكافرين بقولهم: ﴿هَؤُلَاءِ أَهْدَى مِنَ الَّذِينَ آمَنُوا سَبِيلًا﴾، واختيار لفظ ﴿سَبِيلًا﴾؟","answer":"السبيل هو الطريق الموصل إلى الغاية؛ فادعاؤهم أن عبدة الأوثان أهدى طريقًا من المؤمنين يصور انقلاب موازينهم، إذ سموا طريق الضلال هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص263، تحت «سر مجيء الخبر بصيغة أفعل التفضيل».","url":""}]},{"id":"s4-136","number":136,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ لَهُمْ نَصِيبٌ مِنَ الْمُلْكِ فَإِذًا لَا يُؤْتُونَ النَّاسَ نَقِيرًا﴾، واختار النقير؟","answer":"النقير هو النقرة الدقيقة في ظهر نواة التمر، فضُرب به المثل في غاية القلة؛ أي لو كان لهم شيء من الملك لمنعهم بخلهم أن يعطوا الناس أدنى قدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص278، تحت «بلاغة التعبير بلفظة (النقير) في قوله: ﴿فإذا لا يؤتون الناس نقيرًا﴾».","url":""}]},{"id":"s4-137","number":137,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْ يَحْسُدُونَ النَّاسَ﴾، دون أن يقال: يحسدون محمدًا ﷺ؟","answer":"توجه الموسوعة لفظ «الناس» إلى النبي ﷺ وحده على المجاز المرسل بعلاقة الكلية؛ ففي إطلاق اسم الناس عليه تفخيم لشأنه، كأن ما فيهم من الكمال اجتمع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص281، تحت «فائدة المجاز المرسل في التعبير بـ﴿الناس﴾ عن النبي ﷺ».","url":""}]},{"id":"s4-138","number":138,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"لماذا قابل حسدهم بقوله: ﴿فَقَدْ آتَيْنَا آلَ إِبْرَاهِيمَ الْكِتَابَ وَالْحِكْمَةَ وَآتَيْنَاهُمْ مُلْكًا عَظِيمًا﴾؟","answer":"أُلزموا بما يقرون به؛ فقد أعطى الله آل إبراهيم النبوة والحكمة والملك، ومحمد ﷺ من آله، فلا وجه لإنكار الفضل عليه حسدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص282، تحت «مغزى الإطناب بعد الإيجاز بطريق الالتفات».","url":""}]},{"id":"s4-139","number":139,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"أين تتجلى براعة التصوير بحركية مشهدية، تتجلى في تبديل الجلود الناضجة باستمرار في قوله تعالى: ﴿كُلَّمَا نَضِجَتْ جُلُودُهُمْ بَدَّلْنَاهُمْ جُلُودًا غَيْرَهَا لِيَذُوقُوا الْعَذَابَ﴾؟","answer":"التبديل عند كل نضج يصور دوام الإحساس وتجدد الألم بلا انقطاع، و«ليذوقوا» تصرح بأن بقاء ذوق العذاب هو علة التبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص293–294، تحت «براعة التصوير بحركية مشهدية، تتجلى في تبديل الجلود الناضجة باستمرار».","url":""}]},{"id":"s4-140","number":140,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"لماذا وُصفت الأزواج في قوله تعالى: ﴿أزواج مطهرة﴾ بالمفرد، ولم يقل: مطهَّرات؟","answer":"يشير الإفراد إلى شدة توافقهن في الطهر، حتى كأنهن ذات واحدة؛ فالوصف يصور اشتراكهن جميعًا في طهارة دائمة لا تتخلف عن واحدة منهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص301، تحت «سر العدول عن الجمع إلى الإفراد، وغرض تقديم المسند».","url":""}]},{"id":"s4-141","number":141,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنُدْخِلُهُمْ ظِلًّا ظَلِيلًا﴾، فكرر مادة الظل؟","answer":"﴿ظِلًّا﴾ هو النعيم المظلل، و﴿ظَلِيلًا﴾ تؤكد كثافته ودوامه وكمال الإظلال؛ فاشتقاق الصفة من الموصوف للمبالغة، لا تكرار خالٍ من المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص302، تحت «بديع الجناس بالصفة المشتقة».","url":""}]},{"id":"s4-142","number":142,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"لماذا كرر ﴿أَطِيعُوا﴾ مع الله والرسول، ولم يكرره مع ﴿أُولِي الْأَمْرِ﴾؟","answer":"أولو الأمر أصحاب الولاية العلمية أو التنفيذية الذين يقوم بهم نظام الجماعة؛ وطاعتهم تابعة لطاعة الله والرسول، ولذلك لم يُعَد الفعل معها استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص316–317، تحت «سر إعادة العامل مع ﴿الرسول﴾ لا مع غيره، في قوله: ﴿وأطيعوا الرسول وأولي الأمر﴾».","url":""}]},{"id":"s4-143","number":143,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ﴾، فنكر «شيئًا»؟","answer":"نُكرت ﴿شَيْءٍ﴾ في سياق الشرط لتعم أي أمر يقع فيه التنازع، صغيرًا أو كبيرًا؛ فلا يخرج شيء من وجوب رده إلى الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص318، تحت «سر تنكير لفظ ﴿شيء﴾ المتنازع عليه، في قوله: ﴿فإن تنازعتم في شيء﴾».","url":""}]},{"id":"s4-144","number":144,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ التعبير في قوله تعالى: ﴿فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ﴾، وكيف يكون الرد إلى الله؟","answer":"الرد إلى الله يكون بالرجوع إلى كتابه، والرد إلى الرسول بالرجوع إليه في حياته وإلى سنته بعد وفاته. واستعير الرد للتحاكم؛ لأن الفصل في النزاع يُرجع فيه إلى حكم الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص318–319، تحت «سر استعارة لفظ (الرد) إلى معنى (التحاكم)».","url":""}]},{"id":"s4-145","number":145,"surah":4,"verses":[51,52,53,54,55,56,57,58,59],"references":[{"surah":4,"verses":[51,52,53,54,55,56,57,58,59]}],"verseLabel":"النساء: 51–59","question":"ما سرّ تقديم ﴿خَيْرٌ﴾ على ﴿وَأَحْسَنُ تَأْوِيلًا﴾؟","answer":"«خير» يثبت أصل المصلحة في الرد إلى الوحي، ثم «أحسن تأويلًا» يبين حسن العاقبة؛ فبدأ بالحكم ثم مآله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص320–321، تحت «دلالة تقديم الخيرية على الحسن، في قوله: ﴿ذلك خير وأحسن تأويلًا﴾».","url":""}]},{"id":"s4-146","number":146,"surah":4,"verses":[55],"references":[{"surah":4,"verses":[55]},{"surah":64,"verses":[2]}],"verseLabel":"النساء: 55؛ التغابن: 2","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿فَمِنْهُمْ مَنْ آمَنَ بِهِ وَمِنْهُمْ مَنْ صَدَّ عَنْهُ﴾ فقدم المؤمن، بينما قال في التغابن: ﴿فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾ فقدم الكافر؟","answer":"سياق النساء في ذرية إبراهيم وما آتاهم الله، فناسب البدء بمن آمن بذلك الكتاب والنبي؛ أما التغابن فمقام تعداد أحوال عموم البشر والتنبيه على جحود الخلق، فبدأ بالكافر الذي يعالجه السياق ثم ثنّى بالمؤمن.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص140؛ إسلام ويب، باب النساء: 55","url":""}]},{"id":"s4-147","number":147,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿يَزْعُمُونَ أَنَّهُمْ آمَنُوا﴾، دون أن يقال: يقولون؟","answer":"الزعم يطلق على دعوى لا تستند إلى علم محقق، ويغلب استعماله فيما يشك فيه أو يكذب؛ فوصف دعواهم الإيمان بهذا اللفظ يكشف ضعفها وكذبها، كما يفضحه طلب التحاكم إلى الطاغوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص324، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s4-148","number":148,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما دلالة تعقيب قوله تعالى: ﴿يريدون أن يتحاكموا إلى الطاغوت﴾ بقوله: ﴿وقد أمروا أن يكفروا به﴾؟","answer":"جاءت جملة ﴿وقد أمروا أن يكفروا به﴾ حالًا تقبح إرادتهم التحاكم إلى الطاغوت؛ فهم يريدون الرجوع إلى من أُمروا برفضه، فظهر تناقض دعواهم الإيمان مع قصدهم وعملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص330–331، تحت «نكتة التقييد بالجملة الحالية في قوله: ﴿وقد أمروا﴾».","url":""}]},{"id":"s4-149","number":149,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"لماذا أكد إضلال الشيطان بقوله: ﴿أَنْ يُضِلَّهُمْ ضَلَالًا بَعِيدًا﴾؟","answer":"المصدر يؤكد الإضلال، و«بعيدًا» يصور إمعانهم عن الحق وصعوبة رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص332، تحت «سر الاستعارة في وصف الضلال بالبعد في قوله تعالى: ﴿أن يضلهم ضلالًا بعيدًا﴾».","url":""}]},{"id":"s4-150","number":150,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿رَأَيْتَ الْمُنَافِقِينَ يَصُدُّونَ عَنْكَ صُدُودًا﴾، فأعاد المصدر وقال «عنك»؟","answer":"المصدر بعد الفعل يبالغ في وصف الإعراض ويثبته، فكأن الصد صار سمةً كاملة لا حركة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص340–341، تحت «دلالة التأكيد بالمصدر المنكر في قوله تعالى: ﴿يصدون عنك صدودًا﴾».","url":""}]},{"id":"s4-151","number":151,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقُلْ لَهُمْ فِي أَنْفُسِهِمْ قَوْلًا بَلِيغًا﴾؛ كيف يكون القول في أنفسهم؟","answer":"﴿فِي أَنْفُسِهِمْ﴾ أي قولًا يبلغ أعماقهم ويؤثر فيها، أو قل لهم خاليًا بهم ما يردعهم؛ و﴿بَلِيغًا﴾ هو الذي يصل إلى موضع التأثير ويوافق حال المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص352–354، تحت «أسرار حروف الجر الواردة في قوله تعالى: ﴿أولئك الذين يعلم الله ما في قلوبهم فأعرض عنهم وعظهم وقل لهم في أنفسهم قولًا بليغًا﴾».","url":""}]},{"id":"s4-152","number":152,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَرْسَلْنَا مِنْ رَسُولٍ إِلَّا لِيُطَاعَ بِإِذْنِ اللَّهِ﴾، فاختار الإذن دون الأمر؟","answer":"الإذن هنا بمعنى التمكين والإرادة الشرعية التي بها تجب طاعة الرسول؛ فطاعته ليست سلطة مستقلة عن الله، بل طاعة مأذون بها من مرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص358–359، تحت «سر اختيار لفظة الإذن ونكتة الالتفات في قوله تعالى: ﴿وما أرسلنا من رسول إلا ليطاع بإذن الله﴾».","url":""}]},{"id":"s4-153","number":153,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"لماذا جاء القسم على هذه الصورة: ﴿فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ﴾؟","answer":"قُدم النفي اهتمامًا به ثم أُكد بالقسم، وجيء بعد القسم بجوابه المنفي: ﴿لا يؤمنون﴾. وإضافة الرب إلى ضمير النبي ﷺ تشريف له وتأكيد وجوب التحاكم إليه والرضا بحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص365–366، تحت «سر تقديم النفي على القسم في قوله تعالى: ﴿فلا وربك﴾».","url":""}]},{"id":"s4-154","number":154,"surah":4,"verses":[60,61,62,63,64,65],"references":[{"surah":4,"verses":[60,61,62,63,64,65]}],"verseLabel":"النساء: 60–65","question":"لماذا جعل تمام الإيمان في ثلاث مراحل: أن يحكموك، وألا يجدوا حرجًا، وأن يسلموا تسليمًا؟","answer":"بدأ بالتحاكم الظاهر إلى الرسول، ثم نفى الحرج الباطن من حكمه، ثم أثبت التسليم العملي التام؛ فاستوعب قبول المرجع والقلب والتنفيذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص367–369، تحت «دلالة حرف العطف ﴿ثم﴾ في قوله تعالى: ﴿ثم لا يجدوا في أنفسهم حرجًا مما قضيت﴾».","url":""}]},{"id":"s4-155","number":155,"surah":4,"verses":[66,67,68,69,70],"references":[{"surah":4,"verses":[66,67,68,69,70]}],"verseLabel":"النساء: 66–70","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ لَدُنَّا أَجْرًا عَظِيمًا﴾، دون أن يقال: من عندنا؟","answer":"﴿مِنْ لَدُنَّا﴾ أخص من ﴿من عندنا﴾، وتوحي بقرب العطاء واختصاصه بالله؛ فناسبت الأجر العظيم الذي يتفضل به على المطيعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص384، تحت «نكتة لدنية الأجر».","url":""}]},{"id":"s4-156","number":156,"surah":4,"verses":[66,67,68,69,70],"references":[{"surah":4,"verses":[66,67,68,69,70]}],"verseLabel":"النساء: 66–70","question":"لماذا رتبت الأصناف هكذا: النبيون، ثم الصديقون، ثم الشهداء، ثم الصالحون؟","answer":"الترتيب من أعلى مراتب الاصطفاء والقدوة إلى من كمل تصديقه، ثم من شهد للحق بنفسه، ثم عموم الصالحين؛ وهو ترتيب منازل صحبة لا انتقاص لمن تأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص401، تحت «وجه ترتيب منازل الممدوحين».","url":""}]},{"id":"s4-157","number":157,"surah":4,"verses":[66,67,68,69,70],"references":[{"surah":4,"verses":[66,67,68,69,70]}],"verseLabel":"النساء: 66–70","question":"ما سرّ التعبير في قوله تعالى عن جماعة الأصناف: ﴿وَحَسُنَ أُولَئِكَ رَفِيقًا﴾ بالإفراد؟","answer":"﴿رَفِيقًا﴾ مفرد لأنه اسم جنس يشمل الرفقاء المذكورين، أو لأنه حال يلحظ كل واحد منهم رفيقًا؛ فالإفراد يجمع الأصناف في حسن الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص399–400، تحت «سر توحيد التمييز (الرفيق)».","url":""}]},{"id":"s4-158","number":158,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"ما سرّ التعبير في قوله تعالى: ﴿خُذُوا حِذْرَكُمْ﴾؛ وكيف يؤخذ الحذر؟","answer":"صوّر الحذر كأنه سلاح أو متاع يؤخذ ويُحمل؛ ليجعل الاستعداد أمرًا عمليًا ملازمًا، لا مجرد شعور بالخوف في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص410–411، تحت «بلاغة المجاز والاستعارة في التعبير بالأخذ».","url":""}]},{"id":"s4-159","number":159,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا قابل بين ﴿انْفِرُوا ثُبَاتٍ﴾ و﴿انْفِرُوا جَمِيعًا﴾، فذكر حالتي التفرق والاجتماع؟","answer":"﴿ثُبَاتٍ﴾ جماعات متفرقة تتتابع بحسب الحاجة، و﴿جَمِيعًا﴾ جيشًا مجتمعًا؛ فشمل الأمر خطتي الحركة العسكرية تبعًا للمصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص412، تحت «حكمة الأمر بالخروج للجهاد جماعات وجمعًا».","url":""}]},{"id":"s4-160","number":160,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا اعترض بقوله: ﴿كَأَنْ لَمْ تَكُنْ بَيْنَكُمْ وَبَيْنَهُ مَوَدَّةٌ﴾؟","answer":"الجملة المعترضة تكشف تناقض المنافق: يتمنى الغنيمة كأن لا رابطة مودة جمعته بالمؤمنين تلزمه بنصرتهم؛ فلا يرى العلاقة إلا من خلال نصيبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص426–427، تحت «براعة دلالات الاعتراض بجملة التشبيه».","url":""}]},{"id":"s4-161","number":161,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا سمى مبادلة الدنيا بالآخرة شراء: ﴿يَشْرُونَ الْحَيَاةَ الدُّنْيَا بِالْآخِرَةِ﴾؟","answer":"﴿يَشْرُونَ﴾ هنا بمعنى يبيعون؛ فصوّر بذل الحياة الدنيا في سبيل الآخرة صفقة واعية، ثمنها الفاني وعوضها الثواب الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص435، تحت «براعة التعبير بلفظ الشراء على طريق الأضداد».","url":""}]},{"id":"s4-162","number":162,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"ما سرّ تقديم القتل على الغلبة: ﴿فَيُقْتَلْ أَوْ يَغْلِبْ﴾؟","answer":"قدّم القتل، وهو ما تخشاه النفوس، ليقرر من أول الأمر أنه ليس خسارة في سبيل الله بل أحد طريقَي الأجر؛ ثم عطف الغلبة، فكلا المصيرين موعود بالأجر العظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص435، تحت «نكتة تقديم القتل على الغلبة».","url":""}]},{"id":"s4-163","number":163,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ هَذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا﴾، دون أن يقال: القرية الظالمة؟","answer":"وصف أهل القرية بالظلم لا القرية نفسها؛ لأن الظلم فعل السكان لا المكان، وفي التصريح بـ﴿أَهْلُهَا﴾ تعيين للمسؤول عن اضطهاد المستضعفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص441–442، تحت «الموصولية والوصف، وأثرهما في توضيح المعنى».","url":""}]},{"id":"s4-164","number":164,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا كرر دعاءهم: ﴿وَاجْعَلْ لَنَا مِنْ لَدُنْكَ وَلِيًّا وَاجْعَلْ لَنَا مِنْ لَدُنْكَ نَصِيرًا﴾؟","answer":"تكرير ﴿واجعل﴾ وما تعلق به مبالغة في التضرع والابتهال، وإظهار لشدة رغبتهم في أن يمنحهم الله الولاية والنصرة. فتكرر الدعاء لإلحاحهم في الطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص442–443، تحت عنوان «أثر التأخير والتكرير في جلاء المعنى وبيانه في هذه الآية»","url":""}]},{"id":"s4-165","number":165,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا قابل بين القتال ﴿فِي سَبِيلِ اللَّهِ﴾ والقتال ﴿فِي سَبِيلِ الطَّاغُوتِ﴾؟","answer":"إضافة السبيل إلى الله تجعل قتال المؤمنين خالصًا لنصرة الحق، وإضافته إلى الطاغوت تكشف أن قتال الكافرين في خدمة الباطل المتجاوز للحد؛ فتقابلت الغايتان قبل تقابل الجيوش.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص446، تحت «أثر العطف في إثراء المعنى، في قوله: ﴿والذين كفروا يقاتلون في سبيل الطاغوت﴾».","url":""}]},{"id":"s4-166","number":166,"surah":4,"verses":[71,72,73,74,75,76],"references":[{"surah":4,"verses":[71,72,73,74,75,76]}],"verseLabel":"النساء: 71–76","question":"لماذا ختم بقوله: ﴿إِنَّ كَيْدَ الشَّيْطَانِ كَانَ ضَعِيفًا﴾، مع ما يبدو من قوة أثره؟","answer":"ضعف كيد الشيطان هنا في مقابلة نصر الله وتأييده؛ فأولياء الشيطان لا يثبتون أمام أولياء الله المؤيدين به. وجاءت الجملة تعليلًا للأمر بقتالهم وتطمينًا للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص447، تحت «التفريع بالفاء وأثره في جلاء المعنى وترابط السياق».","url":""}]},{"id":"s4-167","number":167,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"لماذا كنى عن ترك القتال بقوله: ﴿كُفُّوا أَيْدِيَكُمْ﴾؟","answer":"اليد آلة البطش والقتال، فكنى بكفها عن منع القتال كله؛ والصورة تجعل الأيدي متهيئة للحركة ثم مأمورة بالانقباض حتى يأتي الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص452–453، تحت «الاستفهام التعجبي، وأثره في توضيح المعنى».","url":""}]},{"id":"s4-168","number":168,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما دلالة معاني (أو) العاطفة، وأثرها في دلالة هذه الآية في قوله تعالى: ﴿يَخْشَوْنَ النَّاسَ كَخَشْيَةِ اللَّهِ أَوْ أَشَدَّ خَشْيَةً﴾؟","answer":"شبه خشيتهم من الناس بخشية الله، ثم ترقى إلى ﴿أَوْ أَشَدَّ خَشْيَةً﴾؛ ليكشف اضطراب ميزانهم حين عظم في قلوبهم ضرر الناس حتى ساوى أو تجاوز ما يجب لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص454–455، تحت «معاني (أو) العاطفة، وأثرها في دلالة هذه الآية».","url":""}]},{"id":"s4-169","number":169,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"لماذا قُيّد خير الآخرة بقوله ﴿لمن اتقى﴾ في مقابل ﴿متاع الدنيا قليل﴾؟","answer":"لحث المخاطبين على اتقاء العصيان والوفاء بالتكليف؛ فالتعلق بتأخير القتال لاستبقاء الحياة لا يوازي حظ الآخرة، وإنما ينال خيرها من اتقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص456، تحت «أسلوب التوبيخ، والعطف، وأثرهما في توضيح المعنى».","url":""}]},{"id":"s4-170","number":170,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿أَيْنَمَا تَكُونُوا يُدْرِكْكُمُ الْمَوْتُ﴾، فصور الموت كطالب يدركهم؟","answer":"أُسند الإدراك إلى الموت فصُوّر طالبًا يلحق الهارب أينما كان؛ وفي ﴿أَيْنَمَا﴾ استغراق لكل مكان، فلا تنجي منه إقامة ولا فرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص463–464، تحت «أسلوب الشرط، وأهميته في قوله تعالى: ﴿أينما تكونوا يدرككم الموت﴾».","url":""}]},{"id":"s4-171","number":171,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما المعنى الإجمالي في قوله تعالى: ﴿وَلَوْ كُنْتُمْ فِي بُرُوجٍ مُشَيَّدَةٍ﴾؟","answer":"يصور التعبير بلوغ التحصن غايته في القصور المنيعة والمنازل الرفيعة، ثم يقرر أن ذلك كله لا يمنع وصول الموت إذا جاء الأجل؛ فلا تنفع معه قوة البناء وارتفاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص462، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s4-172","number":172,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما دلالة نسبتهم الحسنة إلى الله والسيئة إلى الرسول في قولهم: ﴿هَذِهِ مِنْ عِنْدِ اللَّهِ﴾ و﴿هَذِهِ مِنْ عِنْدِكَ﴾؟","answer":"هذه مقالة المنافقين: ينسبون النعمة إلى الله، فإذا أصابتهم شدة تشاءموا بالرسول ﷺ وحملوه تبعتها؛ فكشف النقل اضطرابهم في فهم القدر وتحاملهم على الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص464–466، تحت «دلالة الابتداء، وحكاية كلام الغائب عن المخاطب للمخاطب».","url":""}]},{"id":"s4-173","number":173,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"كيف يجمع القارئ بين ﴿قُلْ كُلٌّ مِنْ عِنْدِ اللَّهِ﴾ ثم ﴿مَا أَصَابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ﴾؟","answer":"﴿كُلٌّ مِنْ عِنْدِ اللَّهِ﴾ من جهة الخلق والتقدير ووقوع الأشياء بمشيئته، و﴿فَمِنْ نَفْسِكَ﴾ من جهة السبب والكسب؛ فالعبد يجلب السيئة بذنبه، والله خالق الأسباب والنتائج.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص469، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s4-174","number":174,"surah":4,"verses":[77,78,79,80],"references":[{"surah":4,"verses":[77,78,79,80]}],"verseLabel":"النساء: 77–80","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا﴾، واختار «حفيظًا» دون «حافظًا»؟","answer":"﴿حَفِيظًا﴾ صيغة تدل على المبالغة والدوام في الحفظ والمراقبة؛ فنفت عن الرسول ﷺ مسؤولية إجبارهم وإحصاء أعمالهم، إذ وظيفته البلاغ وهم محاسبون عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص480–481، تحت «دلالة التعبير بـ﴿حفيظًا﴾ دون حافظًا».","url":""}]},{"id":"s4-175","number":175,"surah":4,"verses":[80],"references":[{"surah":4,"verses":[80]}],"verseLabel":"النساء: 80","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا﴾، وقوله تعالى في الإسراء: ﴿وَمَا أَرْسَلْنَاكَ عَلَيْهِمْ وَكِيلًا﴾؟","answer":"الحفيظ يراقب الأعمال ويحصيها ليجبر الناس على الطاعة، وهذه ليست وظيفة الرسول؛ والوكيل يتولى أمورهم استقلالًا، فنُفي كل وصف في المقام الذي يناسبه.","sources":[{"label":"فاضل السامرائي، *لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 48657","url":""}]},{"id":"s4-176","number":176,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ اقتصار المنافقين على كلمة ﴿طَاعَةٌ﴾، دون أن يقولوا: أطعنا؟","answer":"الاسم المفرد ﴿طَاعَةٌ﴾ دعوى مقتضبة تحتمل معنى: أمرنا طاعة؛ فيظهرون بها موافقة ثابتة من غير أن يسندوا إلى أنفسهم فعلًا تحقق، بخلاف ﴿أطعنا﴾ الذي يلتزم وقوع الطاعة منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص485–486، تحت «دلالة التعبير بلفظ ﴿طاعة﴾ في قوله تعالى: ﴿ويقولون طاعة﴾».","url":""}]},{"id":"s4-177","number":177,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا اختير فعل ﴿بَيَّتَ﴾ لما دبروه ليلًا؟","answer":"التبييت تدبير الأمر ليلًا في خفاء، ثم استعمل لكل ما يضمر ويقرر بعيدًا عن الناس؛ فناسب انقلابهم بعد خروجهم من مجلس الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص487، تحت «سر التعبير بلفظ ﴿بيت﴾ دون غيره من الألفاظ».","url":""}]},{"id":"s4-178","number":178,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ يَكْتُبُ مَا يُبَيِّتُونَ﴾، دون أن يقال: يعلم؟","answer":"الكتابة تزيد على مجرد العلم معنى الإثبات والحفظ للمحاسبة؛ فما يدبرونه ليلًا لا يضيع، بل يسجل عليهم ويواجهون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص489، تحت «الكناية في جملة الحال: ﴿والله يكتب ما يبيتون﴾».","url":""}]},{"id":"s4-179","number":179,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا وصف الاختلاف المفترض في القرآن بأنه ﴿اخْتِلَافًا كَثِيرًا﴾، ولم يقل: اختلافًا فقط؟","answer":"قيد الاختلاف بـ﴿كَثِيرًا﴾ لأن كتابًا طويلًا متعدد الموضوعات لو كان من صنع البشر لظهر فيه تناقض واضطراب كثيران؛ وانتفاء ذلك شاهد على مصدره، ولا يعني إثبات تناقض قليل فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص497–498، تحت «معنى وصف الاختلاف بالكثير دون القليل».","url":""}]},{"id":"s4-180","number":180,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا جَاءَهُمْ أَمْرٌ مِنَ الْأَمْنِ أَوِ الْخَوْفِ أَذَاعُوا بِهِ﴾، واختار «جاءهم»؟","answer":"اختير «جاءهم» لإفادة تحقق ورود الخبر ووثوقه في هذا السياق، لا مجرد سماع أراجيف. والمذموم أنهم أذاعوا خبر الأمن أو الخوف دون مراعاة ما يترتب على إشاعته من أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص502، تحت «فائدة اختيار ﴿جاءهم﴾ دون مرادفاته في الاستعمال».","url":""}]},{"id":"s4-181","number":181,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا صرح بالرسول في قوله: ﴿وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ﴾، ولم يضمره؟","answer":"إظهار الرسول يعظم المرجعية ويجعل الرسالة علة الرد إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص503، تحت «نكتة إظهار لفظ الرسول دون إضماره».","url":""}]},{"id":"s4-182","number":182,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ﴾، واختار صورة الاستنباط؟","answer":"الاستنباط تصوير لاستخراج المعنى الخفي كما يستخرج الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص504–505، تحت «توجيه الاستعارة في قوله: ﴿يستنبطونه﴾».","url":""}]},{"id":"s4-183","number":183,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا استثنى ﴿إِلَّا قَلِيلًا﴾ في قوله: ﴿لَاتَّبَعْتُمُ الشَّيْطَانَ إِلَّا قَلِيلًا﴾؛ وإلى ماذا يعود الاستثناء؟","answer":"تذكر الموسوعة وجهين: أن يكون الاستثناء من عموم أحوال الاتباع، أي لاتبعتم الشيطان إلا اتباعًا قليلًا تُدرك وجوهه ببداهة العقول؛ أو من ضمير المخاطبين، أي إلا قليلًا منهم لا يبلغون تلك المرتبة من اتباع آراء المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص505–506، تحت «بلاغة الالتفات في الآية».","url":""}]},{"id":"s4-184","number":184,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا أفرد النبي ﷺ بالتكليف: ﴿فَقَاتِلْ فِي سَبِيلِ اللَّهِ لَا تُكَلَّفُ إِلَّا نَفْسَكَ﴾؟","answer":"إفراد النبي يقرر ثباته ومسؤوليته ولو تخلف الناس مع تحريضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص512، تحت «بلاغة جملة القصر في قوله تعالى: ﴿لا تكلف إلا نفسك﴾».","url":""}]},{"id":"s4-185","number":185,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى: ﴿عَسَى اللَّهُ أَنْ يَكُفَّ بَأْسَ الَّذِينَ كَفَرُوا﴾، دون أن يقال: أن ينصركم عليهم؟","answer":"كف البأس أعم من النصر وقد يقع بالرعب أو التفرق ونحوهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص514، تحت «سر التعبير بالكف دون النصر».","url":""}]},{"id":"s4-186","number":186,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ التعبير في قوله تعالى في الشفاعة الحسنة: ﴿نَصِيبٌ مِنْهَا﴾، وفي السيئة: ﴿كِفْلٌ مِنْهَا﴾؟","answer":"النصيب حصة من الخير تنمو لصاحب الشفاعة الحسنة، أما الكفل فهو مقدار يحمل تبعته كأنه ثقل على صاحبه؛ فناسب كل لفظ أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص518–520، تحت «سر التعبير عن جزاء الشفاعة الحسنة بالنصيب والسيئة بالكفل».","url":""}]},{"id":"s4-187","number":187,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما سرّ تقديم رد التحية بأحسن على رد مثلها: ﴿فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا﴾؟","answer":"زاد الإحسان في الرد ليصنع السلام مودةً متنامية، وأباح المماثلة حدًا أدنى للعدل؛ فجمع الفضل والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص525، تحت «فائدة تقديم ﴿فحيوا بأحسن منها﴾ على ﴿أو ردوها﴾».","url":""}]},{"id":"s4-188","number":188,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"لماذا انتقل من التحية إلى قوله: ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ لَيَجْمَعَنَّكُمْ إِلَى يَوْمِ الْقِيَامَةِ﴾؟","answer":"الانتقال يربط التحية والعمل برقابة التوحيد والجزاء يوم الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص527، تحت «مناسبة الآية لما قبلها».","url":""}]},{"id":"s4-189","number":189,"surah":4,"verses":[81,82,83,84,85,86,87],"references":[{"surah":4,"verses":[81,82,83,84,85,86,87]}],"verseLabel":"النساء: 81–87","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أصدق من الله حديثًا﴾؟","answer":"الاستفهام يفيد النفي: فلا أحد أصدق من الله، ولا مساويًا له في الصدق. ويشمل ذلك خبره عن جمع الخلق يوم القيامة وسائر أخباره.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص536، تحت عنوان «بلاغة الاستفهام في قوله تعالى: ﴿ومن أصدق من الله حديثًا﴾»","url":""}]},{"id":"s4-190","number":190,"surah":4,"verses":[87,122],"references":[{"surah":4,"verses":[87,122]}],"verseLabel":"النساء: 87؛ النساء: 122","question":"ما سرّ اختلاف التعبير بين قوله تعالى في آية الجمع: ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ حَدِيثًا﴾، وقوله تعالى في آية الوعد: ﴿وَمَنْ أَصْدَقُ مِنَ اللَّهِ قِيلًا﴾؟","answer":"جاءت ﴿حديثًا﴾ بعد الإخبار بوحدانية الله وجمع الخلق يوم القيامة للحساب، فناسب الحديث مقام الإخبار. وجاءت ﴿قيلًا﴾ بعد الوعد بإدخال المؤمنين الجنات؛ والقيل بمعنى القول يناسب الوعد السابق. فاختير لكل موضع اللفظ الملائم لسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص539، تحت عنوان «توجيه المتشابه اللفظي بين قوله تعالى: ﴿ومن أصدق من الله حديثًا﴾ وقوله سبحانه: ﴿ومن أصدق من الله قيلًا﴾»","url":""}]},{"id":"s4-191","number":191,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ أَرْكَسَهُمْ بِمَا كَسَبُوا﴾، واختار «أركسهم»؟","answer":"أركسهم: ردهم إلى الضلال بسبب كسبهم. وصُوّر رجوعهم من الإيمان إلى الكفر بالارتكاس والانقلاب، لإظهار قبح حالهم وشدّة انغماسهم فيما اختاروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص543–544، تحت «بلاغة الاستعارة في قوله تعالى: ﴿والله أركسهم بما كسبوا﴾».","url":""}]},{"id":"s4-192","number":192,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿أَتُرِيدُونَ أَنْ تَهْدُوا مَنْ أَضَلَّ اللَّهُ﴾، فنسب الإضلال إلى الله؟","answer":"الإضلال خذلان جزائي على الكسب والإعراض بعد الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص544–546، تحت «دلالة الباء في ﴿بما﴾ ونكتة التعبير بالكسب دون الاكتساب في قوله تعالى: ﴿بما كسبوا﴾».","url":""}]},{"id":"s4-193","number":193,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَدُّوا لَوْ تَكْفُرُونَ كَمَا كَفَرُوا فَتَكُونُونَ سَوَاءً﴾، وحذف جهة التساوي؟","answer":"حُذف متعلق ﴿سَوَاءً﴾ لأن السياق يبينه ويعممه: يريدون أن تتساووا معهم في الكفر وما يتبعه من الموقف والمصير، فلا يبقى بين الفريقين فرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص556، تحت «دلالة الإطلاق في قوله تعالى: ﴿فتكونون سواء﴾».","url":""}]},{"id":"s4-194","number":194,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"لماذا صور ضيقهم عن القتال بقوله: ﴿حَصِرَتْ صُدُورُهُمْ﴾؟","answer":"حصرت صدورهم تصور ضيق النفس عن قتال الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص566–567، تحت «نكتة التعبير بـ﴿حصرت﴾ في قوله تعالى: ﴿أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم﴾».","url":""}]},{"id":"s4-195","number":195,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَسَلَّطَهُمْ عَلَيْكُمْ فَلَقَاتَلُوكُمْ﴾، وحذف مفعول المشيئة؟","answer":"حذف مفعول ﴿شَاءَ﴾ لأن جواب الشرط يفسره: لو شاء الله تسليطهم عليكم لسلطهم فقاتلوكم؛ والحذف يوجز ويجعل المشيئة محيطة بكل تفاصيل ذلك التسليط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص567–568، تحت «بلاغة الحذف في قوله تعالى: ﴿ولو شاء الله لسلطهم عليكم فلقاتلوكم﴾».","url":""}]},{"id":"s4-196","number":196,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"لماذا كرر في وصف الفريق الآخر: ﴿يُرِيدُونَ أَنْ يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ﴾؟","answer":"كرر ﴿يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ﴾ لكشف طلبهم أمنين متعارضين: يظهرون لكل فريق ما يرضيه ليأمنوا جانبه، من غير ولاء صادق لأحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص576–577، تحت «نكتة تقديم أمنهم المؤمنين على أمنهم قومهم في قوله تعالى: ﴿ستجدون آخرين يريدون أن يأمنوكم ويأمنوا قومهم﴾».","url":""}]},{"id":"s4-197","number":197,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلَّمَا رُدُّوا إِلَى الْفِتْنَةِ أُرْكِسُوا فِيهَا﴾، واختار «أركسوا» مرة أخرى؟","answer":"أركسوا فيها تصور القلب والانغماس المتكرر في الفتنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص577–578، تحت «براعة الاستعارة في قوله تعالى: ﴿أركسوا فيها﴾».","url":""}]},{"id":"s4-198","number":198,"surah":4,"verses":[88,89,90,91],"references":[{"surah":4,"verses":[88,89,90,91]}],"verseLabel":"النساء: 88–91","question":"لماذا ختم الحكم بقوله: ﴿وَأُولَئِكُمْ جَعَلْنَا لَكُمْ عَلَيْهِمْ سُلْطَانًا مُبِينًا﴾؟","answer":"الخاتمة تمنح حجة ظاهرة على من رفض الاعتزال والسلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص580، 582، تحت «دلالة حرف الجر ﴿على﴾ في قوله تعالى: ﴿وأولئكم جعلنا لكم عليهم سلطانًا مبينًا﴾».","url":""}]},{"id":"s4-199","number":199,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا كَانَ لِمُؤْمِنٍ أَنْ يَقْتُلَ مُؤْمِنًا إِلَّا خَطَأً﴾؛ وكيف استثني الخطأ من القتل المنفي؟","answer":"توجه الموسوعة الاستثناء على الاتصال: فنُفي وقوع القتل من المؤمن في جميع الأحوال إلا حال الخطأ. وهذا استثناء لحالة غير مقصودة، لا ترخيص في قتل المؤمن عمدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص589، تحت «دلالة أسلوب الاستثناء في الكلام».","url":""}]},{"id":"s4-200","number":200,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا اختير وصف المؤمن في قوله تعالى: ﴿وما كان لمؤمن أن يقتل مؤمنًا﴾ بدل المسلم؟","answer":"اختير المؤمن لأن الحكم يتعلق بالإيمان الباطن، لا بمجرد المظهر؛ وفي وصف الإيمان ما ينفر صاحبه من قتل أخيه المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص589، تحت «إيثار اختيار (المؤمن) دون (المسلم)».","url":""}]},{"id":"s4-201","number":201,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا عبر عن الإنسان كله بـ﴿رَقَبَةٍ﴾؟","answer":"الرقبة مجاز مرسل عن الإنسان كله لأنها موضع الملك والقيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص591، تحت «بديع المجاز المرسل في تحرير الرقبة».","url":""}]},{"id":"s4-202","number":202,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"ما سرّ التعبير في قوله تعالى: ﴿وَدِيَةٌ مُسَلَّمَةٌ إِلَى أَهْلِهِ﴾ بصيغة اسم المفعول؟","answer":"«مسلّمة» تؤكد إتمام إيصال الدية إلى أهل القتيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص593، تحت «سبب إيثار صيغة اسم المفعول ﴿مسلمة﴾».","url":""}]},{"id":"s4-203","number":203,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا سمى عفو أهل القتيل صدقة: ﴿إِلَّا أَنْ يَصَّدَّقُوا﴾؟","answer":"إسقاط أهل القتيل حقهم سمي صدقة لتبرعهم وتقربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص593–594، تحت «بلاغة الاستعارة في قوله: ﴿إلا أن يصدقوا﴾».","url":""}]},{"id":"s4-204","number":204,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا سمى الكفارة ﴿تَوْبَةً مِنَ اللَّهِ﴾؟","answer":"الكفارة توبة مشرعة من الله للرجوع ومحو أثر الخطأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص597–598، تحت «تنوع المعنى بتنوع إعراب التوبة».","url":""}]},{"id":"s4-205","number":205,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا ذُكر قتل الخطأ قبل القتل العمد مع أن العمد أشد؟","answer":"بعد التنفير من قتل الخطأ، مع قيام العذر فيه، انتقل السياق إلى ما هو أغلظ ولا عذر فيه؛ فترقّى من الخطأ إلى العمد تمهيدًا لتشديد الوعيد على مرتكبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص601، تحت «مناسبة الآية لما قبلها».","url":""}]},{"id":"s4-206","number":206,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"لماذا توالت هذه الألوان الخمسة من الوعيد للقاتل عمدًا: جهنم، والخلود، والغضب، واللعن، وإعداد العذاب العظيم؟","answer":"في تتابع هذا الوعيد تهويل لشأن قتل المؤمن عمدًا، وبيان لبشاعة الجناية: يجمع العقاب الشديد والطرد من رحمة الله، فيبلغ التحذير من سفك الدم بغير حق غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص601–602، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s4-207","number":207,"surah":4,"verses":[93],"references":[{"surah":4,"verses":[93]}],"verseLabel":"النساء: 93","question":"لماذا ختم وعيد قاتل المؤمن بـ﴿وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا﴾، بينما قال في المنافقين والمشركين في الفتح: ﴿وَأَعَدَّ لَهُمْ جَهَنَّمَ﴾؟","answer":"في النساء سُردت عقوبات قاتل المؤمن ثم خُتمت بجنس العذاب العظيم ليضم ما ذُكر وغيره؛ وفي الفتح عُيّنت جهنم للمنافقين والمشركين بعد ذكر ظنهم بالله، فناسب التصريح بالدار المعدة لهم.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 43384","url":""}]},{"id":"s4-208","number":208,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا عبر عن السفر للجهاد بقوله: ﴿إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ﴾؟","answer":"الضرب في سبيل الله كناية عن السير في الأرض بقصد الجهاد؛ إذ قرينة «في سبيل الله» تعين الغاية من السفر، فلا يراد مجرد الانتقال في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص610، تحت «بلاغة الكناية في قوله: ﴿ضربتم في سبيل الله﴾».","url":""}]},{"id":"s4-209","number":209,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَبَيَّنُوا﴾، دون أن يقال: فتثبتوا؟","answer":"التبين طلب ظهور الحقيقة بعد الفحص، أخص من مجرد التثبت والتأني.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص611–612، تحت «توجيه القراءات القرآنية في لفظ ﴿فتبينوا﴾».","url":""}]},{"id":"s4-210","number":210,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿لِمَنْ أَلْقَى إِلَيْكُمُ السَّلَامَ﴾، فصور السلام شيئًا يلقى؟","answer":"إلقاء السلام يصوره علامة ظاهرة مقدمة إليهم توجب الكف والتحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص613–614، تحت «بلاغة التعبير عن السلام بالإلقاء».","url":""}]},{"id":"s4-211","number":211,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿لَسْتَ مُؤْمِنًا﴾، دون أن يقال: لست مسلمًا؟","answer":"نهاهم أن ينفوا عنه الإيمان الذي أظهر علامته، لأن السرائر إلى الله، ولأن الحكم الدنيوي يتعلق بالظاهر؛ فاختيار ﴿مُؤْمِنًا﴾ يغلظ إنكار التسرع في إسقاط حرمة المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص615، تحت «وجه التعبير عن الإيمان باسم الفاعل».","url":""}]},{"id":"s4-212","number":212,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا سمى متاع الدنيا ﴿عَرَضَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"العرض متاع عارض زائل غير ثابت، فناسب غنيمة الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص616، تحت «نكتة التعبير بـ﴿عرض﴾».","url":""}]},{"id":"s4-213","number":213,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا قابل عرض الدنيا بقوله: ﴿فَعِنْدَ اللَّهِ مَغَانِمُ كَثِيرَةٌ﴾؟","answer":"قابل الزائل القليل بمغانم كثيرة ثابتة عند الله لرد باعث الطمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص617–618، تحت «دلالة الفاء في قوله: ﴿فعند الله مغانم كثيرة﴾».","url":""}]},{"id":"s4-214","number":214,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَلِكَ كُنْتُمْ مِنْ قَبْلُ فَمَنَّ اللَّهُ عَلَيْكُمْ﴾، واختار «منَّ» بدل «أنعم»؟","answer":"«منّ» تستحضر نعمة عظيمة بلا استحقاق حين أظهر الله إيمانهم بعد خفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص619، تحت «نكتة إيثار (من) دون (أنعم)».","url":""}]},{"id":"s4-215","number":215,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا كرر الأمر: ﴿فَتَبَيَّنُوا﴾ في أول الآية وآخرها؟","answer":"التكرار يؤطر التعليل: أمر قبل التذكير بحالهم وأعيد نتيجة له لتشديد الاحتياط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص619–620، تحت «تكرار ﴿فتبينوا﴾ بين التأكيد والتأسيس».","url":""}]},{"id":"s4-216","number":216,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا ختمت الآية بـ﴿إِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا﴾، ولم يقل: عليمًا؟","answer":"الخبير يعلم بواطن العمل ودوافع طلب الغنيمة، وهو الأنسب لمقام الاشتباه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص621–622، تحت «سر اقتران وصف الخبير بأعمال المؤمنين».","url":""}]},{"id":"s4-217","number":217,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا بدأ بالمجاهدين بأموالهم قبل أنفسهم في قوله: ﴿الْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ﴾؟","answer":"قُدمت الأموال هنا لأن المقام مقام جهاد، والجهاد بالمال أيسر من الجهاد بالنفس؛ فجاء الترتيب من الأدنى إلى الأعلى. أما موضع شراء الله من المؤمنين فناسبه تقديم الأنفس لأنها الأعز والأغلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص633، تحت «توجيه التشابه اللفظي في تقديم الأموال على الأنفس والعكس».","url":""}]},{"id":"s4-218","number":218,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير أولًا بـ﴿دَرَجَةً﴾ ثم بـ﴿دَرَجَاتٍ مِنْهُ﴾ في تفضيل المجاهدين؟","answer":"من توجيهات المصدر أن التفضيل الأول بدرجة ناظر إلى ما في الدنيا من المنزلة، والثاني بدرجات إلى ما في الآخرة. ويذكر وجهًا آخر: أن الأول على القاعدين لعذر، والثاني على القاعدين بلا عذر؛ وجمع الدرجات يفيد سعة الفضل وعظمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص636–638، تحت «نكتة تكرار التفضيل بلفظ ﴿فضل الله﴾ في هذه الآية الكريمة».","url":""}]},{"id":"s4-219","number":219,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى﴾ مع تفضيل المجاهدين؟","answer":"مع تفضيل المجاهدين لم تسلب الآية القاعدين المؤمنين أصل الخير، فقالت ﴿وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى﴾؛ فجمعت بين إنصاف الفريقين وإظهار مزية الجهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص635، تحت «فائدة الاعتراض بقوله: ﴿وكلًّا وعد الله الحسنى﴾».","url":""}]},{"id":"s4-220","number":220,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ﴾، فأظهر الملائكة وأسند إليهم التوفي؟","answer":"أسند التوفي للملائكة لأنهم المباشرون بأمر الله، وإظهارهم يهوّل مشهد المحاسبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص645–646، تحت «نكتة التعبير بـ﴿توفاهم﴾ دون (يموتون) أو (يتوفون)».","url":""}]},{"id":"s4-221","number":221,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"لماذا نُكرت ﴿حيلة﴾ و﴿سبيلًا﴾ في وصف المستضعفين؟","answer":"وقوعهما نكرتين في سياق النفي يفيد العموم؛ فلا يجدون أي حيلة ولا يهتدون إلى أي سبيل للخلاص. بذلك يتبين العجز الحقيقي الذي يُعذر به صاحبه، حين تنسد سبل الهجرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص651، تحت «نكتة التنكير في قوله: ﴿لا يستطيعون حيلة ولا يهتدون سبيلًا﴾».","url":""}]},{"id":"s4-222","number":222,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى في عفو الله عنهم: ﴿فَأُولَئِكَ عَسَى اللَّهُ أَنْ يَعْفُوَ عَنْهُمْ﴾ مع تحقق رحمة الله؟","answer":"«عسى» من الله وعد مع إبقاء العبد بين الرجاء والأدب وعدم الاتكال.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص652، تحت «سر إيراد (عسى) في حق المعذورين حقيقة».","url":""}]},{"id":"s4-223","number":223,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ تقديم ﴿مُرَاغَمًا كَثِيرًا﴾ على ﴿وَسَعَةً﴾ في ثمرات الهجرة؟","answer":"قدم المراغم لأنه أول ثمرة تزيل قهر العدو، ثم أتبعها بسعة الرزق والمقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص660، تحت «نكتة تقديم المراغمة على السعة، في قوله: ﴿مراغمًا كثيرًا وسعة﴾».","url":""}]},{"id":"s4-224","number":224,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَخْرُجْ مِنْ بَيْتِهِ مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ﴾، فنسب الهجرة إلى الله والرسول؟","answer":"نُسبت الهجرة إلى الله ورسوله لبيان أن المقصود بها طاعة الله ورضوانه؛ فالمهاجر يترك وطنه وأهله ابتغاء مرضاته، لا لمجرد غرض من أغراض الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص662، تحت عنوان «سر اختيار لفظ البيت في قوله: ﴿من بيته﴾»","url":""}]},{"id":"s4-225","number":225,"surah":4,"verses":[94,95,96,97,98,99,100],"references":[{"surah":4,"verses":[94,95,96,97,98,99,100]}],"verseLabel":"النساء: 94–100","question":"ما دلالة قوله تعالى فيمن أدركه الموت في طريق الهجرة: ﴿فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ﴾؟","answer":"شُبّه الأجر بشيء يقع ويثبت على الاستعارة، للدلالة على تحقق ثوابه ووجوبه بوعد الله وفضله؛ فليس المراد سقوطًا حسيًا، بل تأكيد حصول الأجر.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص663–664، تحت «بلاغة الاستعارة في قول الله سبحانه: ﴿فقد وقع أجره على الله﴾».","url":""}]},{"id":"s4-226","number":226,"surah":4,"verses":[101],"references":[{"surah":4,"verses":[101]}],"verseLabel":"النساء: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تقصروا من الصلاة﴾، دون أن يقال: أن تقصروا الصلاة؟","answer":"«من الصلاة» للتبعيض؛ القصر واقع في بعض هيئتها أو عددها لا إعدام الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص669–670، تحت «دلالة حرف الجر (من) في قوله تعالى: ﴿من الصلاة﴾».","url":""}]},{"id":"s4-227","number":227,"surah":4,"verses":[101],"references":[{"surah":4,"verses":[101]}],"verseLabel":"النساء: 101","question":"لماذا قيل ﴿وإذا ضربتم في الأرض﴾ بـ«إذا»، ثم ﴿إن خفتم أن يفتنكم الذين كفروا﴾ بـ«إن»؟","answer":"السفر أمر متكرر لا يكاد يخلو منه المسلمون، فناسبته «إذا» الدالة على تحقق الوقوع؛ أما خوف فتنة العدو فليس متحققًا في كل سفر، فناسبته «إن» التي لا تجزم بوقوع الشرط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص671، تحت «الفرق بين تعليق الشرط بـ(إذا) وتعليقه بـ(إن)».","url":""}]},{"id":"s4-228","number":228,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا كنت فيهم﴾، دون أن يقال: وإذا أقمت فيهم الصلاة؟","answer":"«كنت فيهم» يستحضر حضور النبي وإمامته وتعليمه هيئة الصلاة، وهو أعم من مجرد إقامتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص680، تحت «سر التعبير: ﴿كنت فيهم﴾».","url":""}]},{"id":"s4-229","number":229,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿فلتقم طائفة منهم معك﴾ مع أن النبي ﷺ قائم بينهم أصلًا؟","answer":"القيام معه قيام في الصلاة؛ وتبقى الطائفة الأخرى تجاه العدو للحراسة. وقد حذف ذكر هذه الطائفة أولًا لدلالة تفصيل الطائفة الأخرى بعد ذلك، فلا يجمع الجواب الوظيفتين للطائفة نفسها في الوقت نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص681–683، تحت «بلاغة الاحتباك أو الاكتفاء في قوله: ﴿فلتقم طائفة منهم معك﴾».","url":""}]},{"id":"s4-230","number":230,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"كيف يُؤخذ الحذر في قوله: ﴿وليأخذوا حذرهم وأسلحتهم﴾، ولمَ عطف السلاح عليه؟","answer":"أخذ الحذر مجاز عن أسبابه، وعطف الأسلحة يخص أهم وسيلة مادية بعد الاستعداد المعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص684–685، تحت «بلاغة المجاز والكناية في الأمر بأخذ الحذر».","url":""}]},{"id":"s4-231","number":231,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"لماذا انتقل الكلام من ﴿وليأخذوا حذرهم وأسلحتهم﴾ إلى الخطاب المباشر في ﴿لو تغفلون عن أسلحتكم وأمتعتكم﴾؟","answer":"الانتقال إلى الخطاب إقبالٌ مباشر على المصلين، يزيد تنبيههم وترغيبهم في أخذ الحذر والسلاح؛ فالخطاب أقرب إلى النفوس وأنسب بمقام التحذير من غفلة يترصدها العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص686–687، تحت «سر الالتفات في قوله: ﴿لو تغفلون عن أسلحتكم﴾».","url":""}]},{"id":"s4-232","number":232,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿فيميلون عليكم ميلة واحدة﴾ بالإفراد؟","answer":"«ميلة واحدة» تصور هجمة مجتمعة حاسمة يستغلون بها وضع السلاح، لا جنس الأفراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص687–688، تحت «سر التعبير باسم المرة ﴿ميلة﴾».","url":""}]},{"id":"s4-233","number":233,"surah":4,"verses":[102],"references":[{"surah":4,"verses":[102]}],"verseLabel":"النساء: 102","question":"ما سرّ تقديم أذى المطر على المرض في قوله: ﴿إن كان بكم أذى من مطر أو كنتم مرضى﴾؟","answer":"قدم أذى المطر لأنه يعم الطائفتين جميعًا، بخلاف المرض الذي يختص بمن أصابه؛ فمراعاة المصلحة العامة أولى، ثم ذُكر عذر المرض الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص689، تحت «بلاغة أسلوب التدلي في تقديم المطر على المرض».","url":""}]},{"id":"s4-234","number":234,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"لماذا جاء الأمر بذكر الله بعد الفراغ من صلاة الخوف مباشرة؟","answer":"أُمروا بالذكر في القيام والقعود وعلى الجنوب ليستغرق جميع أحوالهم، فيدوم ارتباطهم بالله في حال الخوف ومواجهة العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص698–699، تحت «دلالة أسلوب التقسيم على استيعاب أحوال العبد».","url":""}]},{"id":"s4-235","number":235,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"لماذا رُتبت أحوال الذكر: ﴿قيامًا وقعودًا وعلى جنوبكم﴾ بهذا الترتيب؟","answer":"الترتيب من أكمل الهيئات وأقواها إلى ما دونها بحسب القدرة: قيام فقعود فاضطجاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص699–700، تحت «بلاغة الترقي في ذكر أحوال العبد».","url":""}]},{"id":"s4-236","number":236,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا اطمأننتم فأقيموا الصلاة﴾، دون أن يقال: فإذا أمنتم فصلّوا؟","answer":"الاطمئنان أوسع من الأمن، وإقامة الصلاة ردها إلى تمام حدودها وهيئتها لا مجرد أدائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص701–702، تحت «أثر تعدد دلالات الإقامة في وفرة المعاني».","url":""}]},{"id":"s4-237","number":237,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"ما دلالة التعبير عن فرضية الصلاة بلفظ ﴿كتابًا﴾؟","answer":"وُصفت الصلاة بالمصدر «كتابًا» تأكيدًا لفرضيتها؛ فالوصف بالمصدر يزيد المعنى توكيدًا، وينبه إلى عظم شأن الصلاة ووجوب المحافظة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص703، تحت عنوان «نكتة تأكيد جملة: ﴿إن الصلاة كانت على المؤمنين كتابًا موقوتًا﴾»","url":""}]},{"id":"s4-474","number":474,"surah":4,"verses":[103],"references":[{"surah":4,"verses":[103]}],"verseLabel":"النساء: 103","question":"ما دلالة وصف الصلاة بأنها ﴿موقوتًا﴾؟","answer":"يدل على أن الصلاة فريضة محددة الأوقات، تؤدَّى في أوقاتها المقررة؛ فالتوقيت يضبط زمن أدائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص696، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s4-238","number":238,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"كيف نُهي المؤمنون عن الوهن في قوله: ﴿ولا تهنوا في ابتغاء القوم﴾ مع أن الوهن شعور قد يطرأ على الإنسان؟","answer":"النهي يتوجه إلى وهن القلب وانهيار العزيمة والفتور عن الطلب. وإذا أريد الوهن البدني الناشئ عن التعب، فالمقصود الحث على مقاومته والجد في الطلب، لا نفي ما يعرض للجسد من تعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص708، تحت عنوان «سر نهيهم عن الوهن وليس بأيديهم دفعه»","url":""}]},{"id":"s4-239","number":239,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"لماذا كرر فعل الألم: ﴿إن تكونوا تألمون فإنهم يألمون كما تألمون﴾؟","answer":"تكرار «تألمون/يألمون» يصرح باشتراك الفريقين في جنس الألم ويمنع توهم اختصاص المؤمنين به","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص710، تحت «بلاغة ذكر المسند ﴿يألمون﴾».","url":""}]},{"id":"s4-240","number":240,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿وترجون من الله ما لا يرجون﴾ ولم يذكر الشيء المرجو؟","answer":"أبهم المرجو بـ﴿مَا﴾ ليشمل النصر والأجر والشهادة والرضوان وكل ما عند الله؛ بينما لا يتجاوز رجاء عدوهم غاية الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص710–711، تحت «سر حذف متعلق الفعل ﴿وترجون﴾».","url":""}]},{"id":"s4-241","number":241,"surah":4,"verses":[104],"references":[{"surah":4,"verses":[104]}],"verseLabel":"النساء: 104","question":"لماذا خُتمت الآية بـ﴿وكان الله عليمًا حكيمًا﴾ بعد الحديث عن المطاردة والألم والرجاء؟","answer":"﴿عَلِيمًا﴾ يناسب علم الله بآلامهم ونياتهم ورجائهم، و﴿حَكِيمًا﴾ يناسب ما شرعه من المطاردة والجهاد وما رتبه عليه من مصالح وجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص711، تحت «بلاغة الإطناب بالتذييل في قوله: ﴿وكان الله عليمًا حكيمًا﴾».","url":""}]},{"id":"s4-242","number":242,"surah":4,"verses":[105],"references":[{"surah":4,"verses":[105]}],"verseLabel":"النساء: 105","question":"ما سرّ تقديم ﴿إليك﴾ في قوله: ﴿إنا أنزلنا إليك الكتاب بالحق﴾؟","answer":"قدم ﴿إِلَيْكَ﴾ للعناية بمن أنزل عليه الكتاب وإبراز مسؤوليته في الحكم، ثم ذكر الكتاب وملابسته بالحق الذي يجب أن يقضي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص715، تحت «سر تقديم الجار والمجرور في قوله: ﴿أنزلنا إليك﴾».","url":""}]},{"id":"s4-243","number":243,"surah":4,"verses":[105],"references":[{"surah":4,"verses":[105]}],"verseLabel":"النساء: 105","question":"كيف وُجّه النهي ﴿ولا تكن للخائنين خصيمًا﴾ إلى النبي ﷺ مع عصمته؟","answer":"في توجيه الخطاب إليه تعليمٌ للأمة، وحثٌّ وتثبيت على اجتناب نصرة الخائن. فالأمر والنهي قد يوجهان إلى من لا يُتصور منه الفعل المذموم لزيادة الحث على لزوم الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص718–719، تحت «دلالة الخطاب والنهي في قوله: ﴿ولا تكن﴾».","url":""}]},{"id":"s4-244","number":244,"surah":4,"verses":[107],"references":[{"surah":4,"verses":[107]}],"verseLabel":"النساء: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين يختانون أنفسهم﴾، وكيف يخون الإنسان نفسه؟","answer":"يخونون أنفسهم لأن وبال الخيانة وعقوبتها راجع إليهم، ولأن المؤمنين كالنفس الواحدة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص729–730، تحت «بلاغة التعبير في قوله: ﴿يختانون أنفسهم﴾».","url":""}]},{"id":"s4-245","number":245,"surah":4,"verses":[107],"references":[{"surah":4,"verses":[107]}],"verseLabel":"النساء: 107","question":"لماذا عُدّي الجدال بـ﴿عن﴾ في قوله: ﴿ولا تجادل عن الذين يختانون أنفسهم﴾؟","answer":"تعدية «تجادل» بـ«عن» تجعل المجادلة دفاعًا وذبًّا عن الخائنين","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص728، تحت «نكتة تعدية الفعل ﴿ولا تجادل﴾ بحرف الجر ﴿عن﴾».","url":""}]},{"id":"s4-246","number":246,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿يستخفون من الناس﴾، دون أن يقال: من القوم؟","answer":"«الناس» يعم كل من يخشى انكشاف الخيانة لديه، بخلاف «القوم» الأضيق دلالة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص735، تحت «مناسبة التعبير بالناس دون القوم».","url":""}]},{"id":"s4-247","number":247,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"لماذا قابل بين استخفائهم من الناس وعدم استخفائهم من الله؟","answer":"المقابلة تفضح تقديم مراقبة الخلق مع أن الله الأحق بالخشية ولا يخفى عليه تبييتهم","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص735–737، تحت «بلاغة الجمع بين الطباق والمشاكلة في قوله: ﴿يستخفون من الناس ولا يستخفون من الله﴾».","url":""}]},{"id":"s4-248","number":248,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"لماذا عبّر عن تدبيرهم ليلًا بقوله: ﴿إذ يبيّتون ما لا يرضى من القول﴾؟","answer":"«يبيّتون» يدل على تدبير القول ليلًا في خفاء وإحكام، لا مجرد الاستمرار أو التكرار","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص734، 738، تحت «سر التعبير بالفعل ﴿يبيتون﴾».","url":""}]},{"id":"s4-249","number":249,"surah":4,"verses":[108],"references":[{"surah":4,"verses":[108]}],"verseLabel":"النساء: 108","question":"لماذا خُتمت الآية بـ﴿وكان الله بما يعملون محيطًا﴾؟","answer":"«محيطًا» يصور العلم الشامل الذي لا يفوته ظاهر العمل ولا باطن التبييت، ويلائم الاستخفاء","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص738–739، تحت «حسن التذييل في قوله: ﴿وكان الله بما يعملون محيطًا﴾».","url":""}]},{"id":"s4-250","number":250,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سر التعبير بقوله: ﴿ها أنتم هؤلاء﴾، ولم لم يقل: أنتم جادلتم عنهم؟","answer":"«ها أنتم هؤلاء» تنبيه واستحضار للمخاطبين قبل تقريعهم على المجادلة، مع التفات يوجب المشافهة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص742–743، تحت «مناسبة تصدير الكلام بـ(ها) التنبيه في قوله: ﴿هأنتم هؤلاء﴾».","url":""}]},{"id":"s4-251","number":251,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿جادلتم عنهم﴾، دون أن يقال: خاصمتم عنهم؟","answer":"الجدال مراجعة الحجة ومحاولة فتل الخصم عنها، فناسب من سخر قدرته على المحاجة للدفاع عن الخائن؛ أما الخصومة فأعم من هذه الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص728، 744، تحت «نكتة إيثار المجادلة على المخاصمة».","url":""}]},{"id":"s4-252","number":252,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن يجادل الله عنهم يوم القيامة﴾، مع أن المجادلة إنما تكون بين يدي الله؟","answer":"المعنى: من يقف مدافعًا عنهم في مواجهة حكم الله وحسابه؟ فعديت المجادلة إلى اسم الله لأن حجتهم الباطلة تصادم قضاءه، لا لأن أحدًا يساويه في مجلس خصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص745–746، تحت «مجاز الاستفهام في قوله تعالى: ﴿فمن يجادل الله عنهم يوم القيامة﴾».","url":""}]},{"id":"s4-253","number":253,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿يوم القيامة﴾، دون أن يقال: في الآخرة، في مقابلة ﴿الحياة الدنيا﴾؟","answer":"«يوم القيامة» يحدد يوم قيام الناس للحساب والحكومة بين يدي الله، ويقابل جدالهم في الحياة الدنيا","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص745–746، تحت «نكتة العدول عن المقابل إلى قوله: ﴿يوم القيامة﴾».","url":""}]},{"id":"s4-254","number":254,"surah":4,"verses":[109],"references":[{"surah":4,"verses":[109]}],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى في مقام التوبيخ: ﴿هَا أَنْتُمْ هَؤُلَاءِ جَادَلْتُمْ﴾، بينما يأتي في مقام التوجيه والمدح: ﴿هَا أَنْتُمْ أُولَاءِ﴾؟","answer":"﴿هؤلاء﴾ أكمل في التنبيه وأشد حضورًا، فناسب مقام التوبيخ على الجدال عن الخائنين؛ أما ﴿أولاء﴾ الأخف فترد حيث لا يحتاج المقام إلى هذا التشديد في التنبيه.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44101","url":""}]},{"id":"s4-255","number":255,"surah":4,"verses":[110],"references":[{"surah":4,"verses":[110]}],"verseLabel":"النساء: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يعمل سوءًا أو يظلم نفسه﴾؛ أليس عمل السوء ظلمًا للنفس؟","answer":"عمل السوء يتناول فعلًا قبيحًا قد يتعدى ضرره إلى غير صاحبه، وظلم النفس يبرز ما يجنيه المرء على نفسه بكل معصية؛ فـ﴿أَوْ﴾ تنوع صور الذنب مع فتح باب الاستغفار للجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص751–752، تحت «نكتة العطف في قوله: ﴿ومن يعمل سوءًا أو يظلم نفسه ثم يستغفر الله يجد الله غفورًا رحيمًا﴾».","url":""}]},{"id":"s4-256","number":256,"surah":4,"verses":[110],"references":[{"surah":4,"verses":[110]}],"verseLabel":"النساء: 110","question":"ما سرّ تقديم عمل السوء على ظلم النفس؟","answer":"قدم عمل السوء لأنه المتعدي إلى الغير والأسبق في السياق، ثم أتبع بظلم النفس ليعم القاصر","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص752، تحت «مناسبة تقديم ﴿يعمل سوءًا﴾ على ﴿يظلم نفسه﴾».","url":""}]},{"id":"s4-257","number":257,"surah":4,"verses":[110],"references":[{"surah":4,"verses":[110]}],"verseLabel":"النساء: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿يجد الله غفورًا رحيمًا﴾، دون أن يقال: يجد مغفرة الله ورحمته؟","answer":"«يجد الله غفورًا رحيمًا» يصور تحقق أثر الصفات في معاملة التائب وقربه، لا مجرد العثور على المغفرة","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص753، تحت «بلاغة الاستعارة في قوله تعالى: ﴿يجد الله غفورًا رحيمًا﴾».","url":""}]},{"id":"s4-258","number":258,"surah":4,"verses":[111],"references":[{"surah":4,"verses":[111]}],"verseLabel":"النساء: 111","question":"لماذا جاء القصر بـ﴿فإنما يكسبه على نفسه﴾؟","answer":"القصر بـ«إنما» يحصر وبال الإثم وكسبه في صاحبه فلا يضر الله ولا يحمل تبعته غيره","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص758–759، تحت «براعة القصر بـ(إنما) في قوله تعالى: ﴿فإنما يكسبه على نفسه﴾».","url":""}]},{"id":"s4-259","number":259,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"لماذا جمع بين ﴿خطيئة﴾ و﴿إثمًا﴾، وعطف بينهما بـ﴿أو﴾؟","answer":"من وجوه التفريق أن الخطيئة ما وقع من غير عمد والإثم ما وقع عمدًا؛ وقيل: الخطيئة ما اقتصر ضرره على صاحبه والإثم ما تعداه. وجاءت «أو» لاستيعاب وقوع أي واحد من المذكورين في سياق الشرط.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص764، تحت «مناسبة العطف بـ(أو) في قوله: ﴿خطيئة أو إثمًا﴾».","url":""}]},{"id":"s4-260","number":260,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"لماذا عاد الضمير مفردًا في ﴿ثم يرمِ به بريئًا﴾ بعد ذكر خطيئة وإثم؟","answer":"لأن المذكورين عُطف أحدهما على الآخر بـ«أو» التي تقتضي أحدهما، صح إفراد الضمير. ويجوز عوده إلى الإثم لقربه، أو إلى المصدر المفهوم من «يكسب»، فيشمل ما اكتسبه من الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص765، تحت «نكتة التعبير بالضمير المفرد في قوله: ﴿ثم يرم به﴾».","url":""}]},{"id":"s4-261","number":261,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"لماذا صُوّر إلصاق الذنب بالبريء بالرمي: ﴿يرم به بريئًا﴾؟","answer":"استعير الرمي لنسبة الذنب إلى البريء؛ فشبّه إيذاءه بهذه التهمة بإصابته بحجر أو سهم، مبالغة في تصوير ما يلحقه من أذى وبيانًا لجسامة فعل المتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص766، تحت «بلاغة الاستعارة في قوله: ﴿ثم يرم به بريئًا﴾».","url":""}]},{"id":"s4-262","number":262,"surah":4,"verses":[112],"references":[{"surah":4,"verses":[112]}],"verseLabel":"النساء: 112","question":"ما سرّ تقديم ﴿بهتانًا﴾ على ﴿إثمًا مبينًا﴾؟","answer":"قُدم البهتان لأنه الجناية المقابلة لرمي البريء، وهي أشد من مجرد اكتساب الخطيئة أو الإثم الذي سبقها؛ فناسب تقديم الأخطر في تفصيل العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص768، تحت «مناسبة تقديم البهتان على الإثم».","url":""}]},{"id":"s4-263","number":263,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"ما سرّ تقديم فضل الله على رحمته في ﴿ولولا فضل الله عليك ورحمته﴾؟","answer":"الفضل أثر الرحمة؛ فلولا رحمة الله ما تفضل على أحد، ولذلك قدم الفضل الظاهر وذكر أصله الرحمة بعده","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص772، تحت «نكتة تقديم الفضل على الرحمة».","url":""}]},{"id":"s4-264","number":264,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"ما سرّ التعبير بقوله تعالى: ﴿همت طائفة منهم أن يضلوك﴾ ثم قُصر ضررهم على أنفسهم: ﴿وما يضلون إلا أنفسهم﴾؟","answer":"همّهم متجه إلى تضليل الرسول، لكن الله عصمه؛ فلم يقع ضرر سعيهم إلا عليهم بما اكتسبوا من إثم وافتضاح، فالقصر يقلب مكرهم إلى أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص773–775، تحت «بلاغة القصر في قوله: ﴿وما يضلون إلا أنفسهم﴾».","url":""}]},{"id":"s4-265","number":265,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"لماذا رُتب الامتنان: ﴿أنزل الله عليك الكتاب والحكمة وعلمك ما لم تكن تعلم﴾ بهذا النسق؟","answer":"رتب الامتنان من إنزال أصل الوحي «الكتاب»، إلى بيانه العملي «الحكمة»، ثم التعليم الأوسع لما لم يكن يعلمه","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص777–778، تحت «مناسبة الترتيب في الامتنان».","url":""}]},{"id":"s4-266","number":266,"surah":4,"verses":[113],"references":[{"surah":4,"verses":[113]}],"verseLabel":"النساء: 113","question":"لماذا خُتم السياق بقوله: ﴿وكان فضل الله عليك عظيمًا﴾ بعد نفي إضرارهم بالنبي ﷺ؟","answer":"الخاتمة تجمع عصمته وإنزال الكتاب والحكمة وتعليمه، فتقرر أن هذا الفضل الخاص المتعدد عظيم","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص778–779، تحت «حسن التذييل في قوله: ﴿وكان فضل الله عليك عظيمًا﴾».","url":""}]},{"id":"s4-267","number":267,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿لا خير في كثير من نجواهم﴾، دون أن يقال: في نجواهم شر؟","answer":"عدل عن التصريح بالشر إلى نفي الخير تلطّفًا في العبارة وكناية عن عدم الاعتداد بكثير من نجواهم. ونفي الخير أوسع من إثبات الشر؛ فقد يتناول كلامًا لا خير فيه ولا شر، ويستوعب غير النافع من أحاديثهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص783–784، تحت «دلالة الكناية في قوله: ﴿لا خير﴾».","url":""}]},{"id":"s4-268","number":268,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿في كثير من نجواهم﴾ ولم ينف الخير عن النجوى كلها؟","answer":"قيد النفي بـ«كثير» لأن بعض النجوى خير، وهو ما فُصل في الاستثناء من الصدقة والمعروف والإصلاح","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص783–785، تحت «سر اختيار لفظ ﴿كثير﴾ دون غيره».","url":""}]},{"id":"s4-269","number":269,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"لماذا خُصت النجوى بالذكر دون سائر كلامهم؟","answer":"لأن الأصل في المحادثة الصراحة والجهر، أما إخفاؤها من غير حاجة فيجعلها مظنة حديث يُستحيا من إظهاره؛ فجاءت الآية لتقويم هذا السلوك، مع استثناء النجوى النافعة بالصدقة والمعروف والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص785، تحت «دلالة إضافة الضمير إلى النجوى في قوله: ﴿نجواهم﴾».","url":""}]},{"id":"s4-270","number":270,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"لماذا رُتبت المستثنيات: ﴿بصدقة أو معروف أو إصلاح بين الناس﴾ بهذا الترتيب؟","answer":"الترتيب ينتقل من خاص مالي «صدقة»، إلى عام يشمل وجوه الخير «معروف»، ثم إلى خاص عظيم الأثر «إصلاح بين الناس»","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص789–790، تحت «التناوب في اقتراح أفعال الخير كبيرها وصغيرها، من الدعوة إلى إصلاح العقول والقلوب».","url":""}]},{"id":"s4-271","number":271,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما دلالة الانتقال من قوله تعالى: ﴿إِلَّا مَنْ أَمَرَ﴾ إلى قوله: ﴿وَمَنْ يَفْعَلْ ذَلِكَ﴾؟","answer":"﴿أَمَرَ﴾ يدخل فيه الدال على الخير والداعي إليه وإن لم يباشره، ثم جاء ﴿يَفْعَلْ﴾ عند الوعد ليشمل تنفيذ هذه الخيرات وتحقيقها؛ فانتقل من التوجيه إلى الأثر العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص794–795، تحت «وجه الالتفات الفعلي بين ﴿أمر﴾ و﴿يفعل﴾».","url":""}]},{"id":"s4-272","number":272,"surah":4,"verses":[114],"references":[{"surah":4,"verses":[114]}],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿ابتغاء مرضات الله﴾، ثم عبّر عن الجزاء بـ﴿فسوف نؤتيه﴾؟","answer":"قيد العمل بابتغاء مرضاة الله لأن النية روح استحقاق الأجر، ثم جاء «نؤتيه» بنون العظمة لتعظيم العطاء واستحضار المعطي","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص795–797، تحت «بلاغة الالتفات في القراءات».","url":""}]},{"id":"s4-273","number":273,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يشاقق الرسول﴾ بصيغة المضارع؟","answer":"المضارع في ﴿ومن يشاقق الرسول﴾ يستحضر الفعل متجددًا أو متكررًا، فيجعل صورته حاضرة ويبين استمرار حكمه أو أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص15، تحت «دلالة التعبير بالفعل المضارع في قوله: ﴿ومن يشاقق﴾».","url":""}]},{"id":"s4-274","number":274,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما تبين له الهدى﴾، دون أن يقال: من بعد ما عرف الحق؟","answer":"«تبيّن» يصور شدة وضوح الحق بعد قيام حجته، و«الهدى» طريق الرشاد الذي ظهر له","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص15–16، تحت «فائدة الإتيان بالفعل ﴿تبين﴾ على وزن تفعل».","url":""}]},{"id":"s4-275","number":275,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"لماذا جُمع بين مشاقّة الرسول واتباع غير سبيل المؤمنين؟","answer":"مشاقة الرسول رفض مرجعية الوحي، واتباع غير سبيل المؤمنين خروج عن جماعة الحق؛ جمعهما يثبت تلازم المرجع والطريق بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص17–18، تحت «وجه الجمع بين قوله: ﴿ويتبع غير سبيل المؤمنين﴾ مع مشاقة الرسول».","url":""}]},{"id":"s4-276","number":276,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿غير سبيل المؤمنين﴾، دون أن يقال: غير سبيل الرسول؟","answer":"«سبيل المؤمنين» احتراس يحفظ الجماعة بعد وفاة الرسول ويبين أن مخالفة سبيلهم امتداد لمشاقته، لا معنى لفظيًا عامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص21–22، تحت «احتراس ثان في قوله: ﴿ويتبع غير سبيل المؤمنين﴾».","url":""}]},{"id":"s4-277","number":277,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"ما الصورة في قوله: ﴿نوله ما تولى﴾؟","answer":"التعبير كناية عن خذلانه وتركه لما اختاره وإيكاله إلى نفسه بعد إعراضه، لا مجرد تحويل معنى مجرد إلى صورة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص22، تحت «دلالة الكناية في قوله: ﴿نوله ما تولى﴾».","url":""}]},{"id":"s4-278","number":278,"surah":4,"verses":[115],"references":[{"surah":4,"verses":[115]}],"verseLabel":"النساء: 115","question":"لماذا خُتمت الآية بـ﴿وساءت مصيرًا﴾؟","answer":"الخاتمة تحكم على جهنم بأنها أسوأ منتهى وآخر مراحل الانحدار بعد المشاقة والخذلان، فتتم صورة العاقبة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص23، تحت «فائدة الإطناب في قوله: ﴿وساءت مصيرًا﴾».","url":""}]},{"id":"s4-279","number":279,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"لماذا تكررت آية ﴿إن الله لا يغفر أن يشرك به﴾ بعد ورودها في الآية 48؟","answer":"آية 48 خاطبت أهل الكتاب فناسب افتراء الإثم، وهنا التحذير للمؤمنين بعد مشاقة الرسول وسبيل المؤمنين فناسب الضلال البعيد","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص28–30، تحت «التشابه بين الآيتين».","url":""}]},{"id":"s4-280","number":280,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿ويغفر ما دون ذلك﴾، دون أن يقال: ما سوى ذلك؟","answer":"«دون» تفيد ما هو أدنى من الشرك مرتبة، وفيها مع التبشير بالمغفرة تبشيع للمعاصي وتنزيل للعاصي عن رتبة الطائع","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص30–31، تحت «دلالة اختيار ﴿دون﴾ في قوله: ﴿ويغفر ما دون ذلك﴾».","url":""}]},{"id":"s4-281","number":281,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"لماذا عبّر عن الشرك بقوله: ﴿أن يشرك به﴾ بالبناء للمجهول؟","answer":"البناء للمجهول يصرف النظر عن شخص المشرك إلى فظاعة وقوع الشرك بالله أيًّا كان فاعله، ويجعل المحور حق الله الذي اتخذ له شريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص31–32، تحت «دلالة الالتفات من المبني لما لم يسم فاعله إلى المبني للمعلوم».","url":""}]},{"id":"s4-282","number":282,"surah":4,"verses":[116],"references":[{"surah":4,"verses":[116]}],"verseLabel":"النساء: 116","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فقد ضل ضلالًا بعيدًا﴾، وفي الآية 48: ﴿افترى إثمًا عظيمًا﴾؟","answer":"في الآية 48 جاء السياق في الافتراء والتزكية الباطلة، فناسب ﴿افْتَرَى إِثْمًا عَظِيمًا﴾؛ وفي الآية 116 جاء بعد مفارقة طريق الهدى، فناسب ﴿ضَلَّ ضَلَالًا بَعِيدًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص28–29، تحت «التشابه بين الآيتين».","url":""}]},{"id":"s4-283","number":283,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا عبّر عن العبادة بالدعاء في ﴿إن يدعون من دونه﴾؟","answer":"الدعاء أعم من العبادة، وعبادتهم الأصنام غايتها دعاؤها عند الحاجة؛ فذكر العام مستوعبًا الخاص ومبكتًا عجز المعبود","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص36–37، تحت «سر التعبير عن العبادة بالدعاء في قوله: ﴿يدعون﴾».","url":""}]},{"id":"s4-284","number":284,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا سمّى المعبودات الباطلة ﴿إناثًا﴾؟","answer":"سميت الأصنام إناثًا لتأنيث أسمائها ودعواهم أنها بنات الله، ولتصوير نقصها وعجزها وانفعالها واحتياجها للحماية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص37–38، تحت «الكناية ومعنى التبكيت في قوله: ﴿إلا إناثًا﴾».","url":""}]},{"id":"s4-285","number":285,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا كرر ﴿إن يدعون﴾ في الآية نفسها؟","answer":"الدعاء الأول عبادة الأصنام، والثاني طاعة الشيطان الذي أغرى بها؛ فالحصران يكشفان الظاهر وأصله الحقيقي، لا مجرد تكرار للتنبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص39–40، تحت «وجه تكرار أسلوب الحصر مرتين في ﴿إن يدعون﴾».","url":""}]},{"id":"s4-286","number":286,"surah":4,"verses":[117],"references":[{"surah":4,"verses":[117]}],"verseLabel":"النساء: 117","question":"لماذا أُخر ذكر الشيطان بعد ذكر الإناث: ﴿وإن يدعون إلا شيطانًا مريدًا﴾؟","answer":"أُخر الشيطان لأن عبادته وطاعته هي الأصل الذي أغراهم بعبادة الأصنام، فانتقل من المظهر إلى المحرك الحقيقي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص39، تحت «علة تأخر ذكر الشيطان وعبادته عن عبادة الأصنام».","url":""}]},{"id":"s4-287","number":287,"surah":4,"verses":[118],"references":[{"surah":4,"verses":[118]}],"verseLabel":"النساء: 118","question":"ما دلالة قول إبليس: ﴿لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَفْرُوضًا﴾؟","answer":"النصيب حصة من العباد يسعى الشيطان إلى إغوائها، ووصفه بالمفروض أي المقطوع المعين؛ ففي كلامه إظهار عزمه على اتخاذ هذا النصيب وإضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص47–48، تحت «وجه وصف النصيب بقوله: ﴿مفروضًا﴾».","url":""}]},{"id":"s4-288","number":288,"surah":4,"verses":[118],"references":[{"surah":4,"verses":[118]}],"verseLabel":"النساء: 118","question":"لماذا اختار فعل ﴿لأتخذن﴾ بدل لأضلّن عددًا من عبادك؟","answer":"«لأتخذن» يصور استيلاء الشيطان عليهم وجعلهم حصة خاصة وأتباعًا له، وهو أبلغ من مجرد وقوع الإضلال في عدد منهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص47، تحت «دلالة التعبير بالفعل ﴿لأتخذن﴾».","url":""}]},{"id":"s4-289","number":289,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"لماذا كرر إبليس ﴿ولآمرنهم﴾ في تعداد خطوات الإضلال؟","answer":"تكرر «ولآمرنهم» للفصل والتوكيد بين أمرين لهما أثران: تبتيك الآذان وتغيير خلق الله، وإبراز تسلط الأمر الشيطاني","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص56، تحت «دلالة تكرار قوله: ﴿ولآمرنهم﴾».","url":""}]},{"id":"s4-290","number":290,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"لماذا خُصّ تبتيك آذان الأنعام بالذكر قبل تغيير خلق الله؟","answer":"قدم تبتيك الآذان مثالًا خاصًا مشهورًا من فعل الجاهلية ثم رقّي إلى عموم تغيير خلق الله، مع التنبيه على شناعة الخاص","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص54–55، تحت «دلالة ذكر العام بعد الخاص».","url":""}]},{"id":"s4-291","number":291,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿فليغيرن خلق الله﴾، دون أن يقال: فطرة الله؟","answer":"«خلق الله» أوسع من الفطرة، فيشمل تغيير الدين والهيئة التي خلقها الله والتصرفات الداخلة فيهما","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص57، تحت «دلالة اختيار التعبير ﴿خلق الله﴾ دون فطرة الله».","url":""}]},{"id":"s4-292","number":292,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"ما دلالة الحذف في قوله تعالى: ﴿ولآمرنهم فليبتكن آذان الأنعام﴾؟","answer":"حُذف متعلق الأمر لدلالة ما بعده عليه؛ فالتقدير: لآمرنهم بالتبتيك فليبتكن. وفي تعقيب الأمر بفعله تصوير لسرعة استجابتهم لإغواء الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص56، تحت «دلالة حذف مفعول الفعل ﴿ولآمرنهم﴾».","url":""}]},{"id":"s4-293","number":293,"surah":4,"verses":[119],"references":[{"surah":4,"verses":[119]}],"verseLabel":"النساء: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يتخذ الشيطان وليًا من دون الله فقد خسر خسرانًا مبينًا﴾، دون أن يقال: ضل ضلالًا مبينًا؟","answer":"اتخاذ الشيطان وليًا مبادلة لولاية الله تفوّت خير الدنيا والآخرة، فناسب الخسران الذي يعني فقدان رأس المال والنجاة، لا مجرد ضلال الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص59–60، تحت «دلالة التعبير بالخسران دون غيره».","url":""}]},{"id":"s4-294","number":294,"surah":4,"verses":[120],"references":[{"surah":4,"verses":[120]}],"verseLabel":"النساء: 120","question":"لماذا جمع بين ﴿يعدهم﴾ و﴿يمنيهم﴾؟","answer":"لا يكتفي الشيطان بالوعد، بل يفتح لهم باب الأماني، فيثير الحرص ويطيل الأمل ويشغل النفس بما تتخيله من محبوب؛ فالتمنية تقوي تعلقهم بما يعدهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص63، تحت «دلالة التعبير بالأماني بعد الوعد في قوله: ﴿يعدهم ويمنيهم﴾».","url":""}]},{"id":"s4-295","number":295,"surah":4,"verses":[120],"references":[{"surah":4,"verses":[120]}],"verseLabel":"النساء: 120","question":"لماذا قصر وعد الشيطان على الغرور: ﴿وما يعدهم الشيطان إلا غرورًا﴾؟","answer":"القصر يبطل حقيقة وعود الشيطان كلها ويحصرها في الزخرف المخادع الذي لا ينجز، فلا يبقى منها وعد صادق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص64، تحت «بلاغة الاستثناء والحصر في قوله: ﴿وما يعدهم الشيطان إلا غرورًا﴾».","url":""}]},{"id":"s4-296","number":296,"surah":4,"verses":[121],"references":[{"surah":4,"verses":[121]}],"verseLabel":"النساء: 121","question":"ما سرّ التعبير في قوله تعالى عن جهنم: ﴿مأواهم﴾، دون أن يقال: مستقرهم؟","answer":"المأوى موضع يلجأ إليه للسكينة والراحة، وفي وصف جهنم به تهكم ومفارقة؛ كلما طلبوا مأوى وجدوا فيه أشد العذاب، بخلاف «مستقر».","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص67، تحت «التعبير بقوله: ﴿مأواهم﴾ دون (مستقرهم أو مقامهم)».","url":""}]},{"id":"s4-297","number":297,"surah":4,"verses":[122],"references":[{"surah":4,"verses":[122]}],"verseLabel":"النساء: 122","question":"لماذا قُرن الإيمان بالعمل الصالح مرة أخرى قبل وعد الجنة؟","answer":"الإيمان أصل باطن يحدد الوجهة، والعمل الصالح برهانه وثمرته؛ فاقترانهما يمنع الاتكال على الدعوى المجردة أو العمل المنفصل عن الإيمان قبل وعد الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص71–72، تحت «إيجاز الحذف في قوله: ﴿والذين آمنوا وعملوا الصالحات﴾».","url":""}]},{"id":"s4-298","number":298,"surah":4,"verses":[122],"references":[{"surah":4,"verses":[122]}],"verseLabel":"النساء: 122","question":"لماذا جُمعت الجنات في ﴿سندخلهم جنات﴾ ونُكّرت؟","answer":"جمع «جنات» لتعددها وتنوع مراتبها ونعيمها، ونُكرت للتعظيم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص74، تحت «سر التنكير والجمع لقوله: ﴿جنات﴾».","url":""}]},{"id":"s4-299","number":299,"surah":4,"verses":[122],"references":[{"surah":4,"verses":[122]}],"verseLabel":"النساء: 122","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿وَعْدَ اللَّهِ حَقًّا﴾، بينما تنوع التعبير في مواضع أخرى إلى ﴿وَعْدَهُ مَأْتِيًّا﴾ و﴿وَعْدَ الصِّدْقِ﴾ و﴿لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾؟","answer":"«حقًا» مصدر مؤكد يثبت الوعد وينفي عنه الوهم بعد ذكر أماني الشيطان وأماني أهل الكتاب","sources":[{"label":"فاضل السامرائي، *قبسات من البيان القرآني*، ص268–271؛ منقول في Quranpedia، ملاحظة 49250","url":""}]},{"id":"s4-300","number":300,"surah":4,"verses":[123],"references":[{"surah":4,"verses":[123]}],"verseLabel":"النساء: 123","question":"ما سرّ افتتاح الحكم بقوله تعالى: ﴿ليس بأمانيكم ولا أماني أهل الكتاب﴾؟","answer":"افتتح بنفي الأماني لأن النجاة والثواب لا ينالان بمجرد الدعوى والتمني، بل بالإيمان والعمل، فجاء الحكم قاطعًا لوهم الفريقين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص80، 82–84، تحت «بلاغة الاستئناف الابتدائي».","url":""}]},{"id":"s4-301","number":301,"surah":4,"verses":[123],"references":[{"surah":4,"verses":[123]}],"verseLabel":"النساء: 123","question":"لماذا لم يُذكر الجزاء صراحة في ﴿ليس بأمانيكم ولا أماني أهل الكتاب﴾، ثم قيل ﴿من يعمل سوءًا يُجز به﴾؟","answer":"على تفسير الضمير بالجزاء، أُضمر أولًا ثم بيّنته الجملة التالية؛ فيتوجه الاهتمام إلى نفي تعلقه بالأماني، ثم يأتي بيانه مرتبطًا بالعمل. وهذا إبهام يتلوه بيان يقوّي المعنى في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص82–83، تحت عنوان «بلاغة الاستئناف الابتدائي»","url":""}]},{"id":"s4-302","number":302,"surah":4,"verses":[123],"references":[{"surah":4,"verses":[123]}],"verseLabel":"النساء: 123","question":"ما دلالة الجمع بين الولي والنصير في قوله تعالى: ﴿ولا يجد له من دون الله وليًا ولا نصيرًا﴾؟","answer":"الولي يتولى أمره ويدفع عنه بالنصرة، والنصير يعينه عند وقوع الضر؛ جمعهما ينفي أصل الحماية والمعونة من دون الله، لا مجرد الترادف العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص87–88، تحت «التناسب في قوله: ﴿وليًا ولا نصيرًا﴾».","url":""}]},{"id":"s4-303","number":303,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن يعمل من الصالحات﴾، دون: ومن يعمل الصالحات؟","answer":"«من» تبعيضية: لا يطيق الإنسان استيعاب الصالحات كلها، فعلق الجزاء بما يعمل منها، وفي ذلك تيسير وحث","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص93، تحت «دلالة (من) في موضعيها في الآية الكريمة».","url":""}]},{"id":"s4-304","number":304,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما دلالة التصريح بقوله تعالى: ﴿من ذكر أو أنثى﴾ مع أن اسم الشرط ﴿من﴾ يشملهما؟","answer":"صُرّح بالذكر والأنثى لرفع توهم اختصاص الوعد بأحدهما وتقرير تساويهما في أصل الجزاء، مع أن «من» تشمل الجنسين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص95–96، تحت «دلالة الطباق في قوله: ﴿من ذكر أو أنثى﴾».","url":""}]},{"id":"s4-305","number":305,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما دلالة القيد ﴿وهو مؤمن﴾ بعد العمل الصالح؟","answer":"الإيمان شرط قبول العمل واستحقاق ثوابه، فقيد العمل الصالح به حتى لا يوهم أن صورته وحدها كافية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص95–96، تحت «الحمل على اللفظ في قوله: ﴿وهو مؤمن﴾».","url":""}]},{"id":"s4-306","number":306,"surah":4,"verses":[124],"references":[{"surah":4,"verses":[124]}],"verseLabel":"النساء: 124","question":"ما سرّ ضرب المثل بالنقير في قوله تعالى: ﴿ولا يظلمون نقيرًا﴾؟","answer":"«النقير» نقرة صغيرة في نواة التمر تضرب مثلًا لأدنى شيء","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص98، 100، تحت «بلاغة الاستعارة في قوله: ﴿نقيرًا﴾».","url":""}]},{"id":"s4-308","number":308,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أحسن دينًا ممن أسلم وجهه لله﴾؟","answer":"الاستفهام إنكاري يفيد نفي أن يكون أحد أحسن دينًا ممن جمع إخلاص الوجه لله والإحسان واتباع ملة إبراهيم؛ فيحمل السامع على الإقرار بهذه الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص106، تحت «الاستفهام الإنكاري في قوله: ﴿ومن أحسن دينًا﴾».","url":""}]},{"id":"s4-309","number":309,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما الصورة في قوله تعالى: ﴿أسلم وجهه لله﴾، وما دلالة تخصيص الوجه؟","answer":"«أسلم وجهه لله» كناية عن تسليم الذات والقصد كله لله؛ وخص الوجه لأنه أشرف الأعضاء وأظهرها ودال على التوجه، لا لمجرد صنع صورة حسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص106–107، تحت «الكناية في قوله: ﴿أسلم وجهه﴾».","url":""}]},{"id":"s4-310","number":310,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما دلالة الجمع بين ﴿أسلم وجهه لله﴾ و﴿وهو محسن﴾؟","answer":"جمع بين إخلاص التوجه لله في «أسلم وجهه» وإحسان العمل وموافقته في «وهو محسن»، فاجتمع إخلاص القصد وصواب الفعل","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص105، 108، تحت «الإيجاز بالقصر في الآية الكريمة».","url":""}]},{"id":"s4-311","number":311,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما سرّ وصف اتباع ملة إبراهيم بقوله تعالى: ﴿حنيفًا﴾؟","answer":"«حنيفًا» لا يقتصر على الاستقامة؛ بل يدل على الميل المتعمد عن الشرك والباطل إلى التوحيد والحق، وفيه معنى المفارقة الذي لا تؤديه «مستقيمًا» وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص103، 108–109، تحت «العدول عن (مستقيمًا) إلى ﴿حنيفًا﴾».","url":""}]},{"id":"s4-312","number":312,"surah":4,"verses":[125],"references":[{"surah":4,"verses":[125]}],"verseLabel":"النساء: 125","question":"ما مناسبة ختم الثناء بقوله تعالى: ﴿واتخذ الله إبراهيم خليلًا﴾؟","answer":"الخلة أخص المحبة التي تتخلل النفس، وفي ذكرها غاية تشريف إبراهيم بعد بيان اتباع ملته، مع بقاء معنى عبوديته لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص104، 110–111، تحت «مناسبة التذييل في الآية الكريمة».","url":""}]},{"id":"s4-313","number":313,"surah":4,"verses":[126],"references":[{"surah":4,"verses":[126]}],"verseLabel":"النساء: 126","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾؟","answer":"«ما» تستوعب ما في السماوات والأرض من الموجودات، وغلب استعمالها في غير العقلاء، فجاء اللفظ شاملًا للملك كله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص113–114، تحت «سر التعبير بـ(ما) في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾».","url":""}]},{"id":"s4-314","number":314,"surah":4,"verses":[126],"references":[{"surah":4,"verses":[126]}],"verseLabel":"النساء: 126","question":"ما مناسبة قوله تعالى: ﴿وكان الله بكل شيء محيطًا﴾ بعد تقرير ملكه للسماوات والأرض؟","answer":"بعد إثبات الملك العام ختم بالإحاطة لإثبات شمول علم الله وقدرته وتدبيره، وأن شيئًا من ملكه لا يخرج عنه","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص115، تحت «التذييل في قوله: ﴿وكان الله بكل شيء محيطًا﴾».","url":""}]},{"id":"s4-315","number":315,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما سرّ تكرار مادة الفتوى والتصريح باسم الله في قوله تعالى: ﴿ويستفتونك في النساء قل الله يفتيكم فيهن﴾؟","answer":"إعادة مادة الفتوى في الجواب تطابق طلبهم وتبين أن المبين هو الحكم المطلوب، والتصريح باسم الله يعظم مصدره ويقطع تبعيته للعرف","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص120–121، تحت «تقديم المسند إليه في قوله: ﴿قل الله يفتيكم فيهن﴾».","url":""}]},{"id":"s4-316","number":316,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما موقع قوله تعالى: ﴿وما يتلى عليكم في الكتاب﴾ من جواب الاستفتاء؟","answer":"«وما يتلى عليكم» معطوف على اسم الله في «الله يفتيكم»، أي يفتيكم الله ويفتيكم أيضًا ما يتلى في الكتاب من الأحكام السابقة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص121–122، تحت «دلالات إعراب (وما) في قوله تعالى: ﴿وما يتلى عليكم في الكتاب﴾».","url":""}]},{"id":"s4-317","number":317,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما سرّ حذف حرف الجر في قوله تعالى: ﴿وترغبون أن تنكحوهن﴾؛ أهو رغبة فيهن أم رغبة عنهن؟","answer":"حذف حرف الجر يحتمل الرغبة في نكاح اليتيمة لجمالها ومالها، والرغبة عن نكاحها لقلة مالها أو جمالها؛ فجمعت العبارة الحالين، وفي الإبهام ستر على اليتيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص124–125، تحت «بلاغة إيجاز الحذف في قوله: ﴿وترغبون أن تنكحوهن﴾».","url":""}]},{"id":"s4-318","number":318,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما سرّ التعبير بقوله تعالى: ﴿وأن تقوموا لليتامى بالقسط﴾، دون: وأن تقسطوا في اليتامى؟","answer":"«تقوموا لليتامى بالقسط» يصور ملازمة رعاية حقوقهم وإظهار العدل لهم حتى يعرفوا استيفاءها، ويربط القسط بالقيام المستمر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص125–126، 129، تحت «الاستعارة في قوله: ﴿وأن تقوموا﴾».","url":""}]},{"id":"s4-319","number":319,"surah":4,"verses":[127],"references":[{"surah":4,"verses":[127]}],"verseLabel":"النساء: 127","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فإن الله كان به عليمًا﴾؟","answer":"عمّم قوله ﴿مِنْ خَيْرٍ﴾ كل إحسان إلى الضعفاء، ثم أكد أن الله يعلمه؛ ترغيبًا في الخير الخفي والظاهر وضمانًا لعدم ضياع جزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص126–127، تحت «دلالة الاقتصار على فعل الخير في قوله: ﴿وما تفعلوا من خير فإن الله كان به عليمًا﴾».","url":""}]},{"id":"s4-320","number":320,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما سرّ التعبير بقوله تعالى: ﴿من بعلها﴾، دون: من زوجها؟","answer":"«البعل» يلحظ قوة الرجل وقيامه على المرأة وتهيؤه للمعاشرة، فيناسب نشوزه الذي يعطل رابطة الزوجية، بخلاف «الزوج» الأعم في مطلق الاقتران","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص133، 140–141، تحت «سر التعبير بـ(البعل) بدل الزوج».","url":""}]},{"id":"s4-321","number":321,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما دلالة ترتيب ﴿نشوزًا أو إعراضًا﴾؟","answer":"النشوز ترفع واستعلاء تظهر آثاره في المعاملة، والإعراض انصراف عنها وترك لمؤانستها؛ فجمع التعبير الصورتين اللتين تخشى المرأة وقوعهما من زوجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص130–131، 134، تحت «مناسبة العطف بين النشوز والإعراض في قوله: ﴿وإن امرأة خافت من بعلها نشوزًا أو إعراضًا﴾».","url":""}]},{"id":"s4-322","number":322,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما سرّ نفي الجناح في قوله تعالى: ﴿فلا جناح عليهما أن يصلحا بينهما صلحًا﴾ مع أن الصلح مطلوب؟","answer":"نفي الجناح يرفع توهم الإثم في تنازل أحد الزوجين عن بعض حقه طلبًا لبقاء العشرة، ويقرر أن هذا ليس رشوة ولا ظلمًا","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص135، 141، تحت «نكتة النفي بلا النافية للجنس في قوله: ﴿فلا جناح﴾».","url":""}]},{"id":"s4-323","number":323,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما دلالة مجيء قوله تعالى: ﴿والصلح خير﴾ جملة اعتراضية مطلقة؟","answer":"أكد الاعتراض الترغيب في المصالحة، وجاءت الجملة اسمية لتثبيت خيريتها. وإطلاقها يجعلها كالمثل العام: كل صلح مشروع يزيل الخصومة خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص136–137، تحت «براعة الإطناب بالاعتراض في قوله: ﴿والصلح خير﴾».","url":""}]},{"id":"s4-324","number":324,"surah":4,"verses":[128],"references":[{"surah":4,"verses":[128]}],"verseLabel":"النساء: 128","question":"ما الصورة في قوله تعالى: ﴿وأحضرت الأنفس الشح﴾؟","answer":"صوّر الشح كأنه شيء أُحضر عند النفس ولزمها، للدلالة على تمكنه منها واستعداده للحضور عند قسمة الحقوق؛ وفي ذلك تنبيه للزوجين إلى مجاهدة هذا الطبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص138، تحت «براعة الإطناب بالاعتراض في قوله: ﴿وأحضرت الأنفس الشح﴾».","url":""}]},{"id":"s4-325","number":325,"surah":4,"verses":[128,129],"references":[{"surah":4,"verses":[128,129]}],"verseLabel":"النساء: 128؛ 129","question":"ما سرّ اختلاف الخاتمة بين قوله تعالى: ﴿وَإِنْ تُحْسِنُوا وَتَتَّقُوا... خَبِيرًا﴾، وقوله: ﴿وَإِنْ تُصْلِحُوا وَتَتَّقُوا... غَفُورًا رَحِيمًا﴾؟","answer":"الأولى تحث على إحسان العشرة، وخفايا الإحسان يعلمها الخبير. والثانية تعالج تقصيرًا في العدل يحتاج إلى إصلاح، فناسبها الوعد بالمغفرة والرحمة لمن أصلح واتقى.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص141؛ إسلام ويب، باب النساء: 128–129","url":""}]},{"id":"s4-326","number":326,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"كيف يُفهم قوله تعالى: ﴿ولن تستطيعوا أن تعدلوا بين النساء﴾ مع الأمر بالعدل؟","answer":"المنفي هو تمام التسوية في ميل القلب والمحبة، وهو غير مقدور، أما العدل الواجب في القسم والنفقة والمعاملة فمقدور ومأمور به","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص144–146، تحت «نكتة التعبير بنفي الاستطاعة في قوله تعالى: ﴿ولن تستطيعوا أن تعدلوا﴾».","url":""}]},{"id":"s4-327","number":327,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"ما دلالة زيادة قوله تعالى: ﴿ولو حرصتم﴾ بعد نفي استطاعة العدل التام؟","answer":"يدخل قوله ﴿ولو حرصتم﴾ أشد أحوال السعي والاجتهاد في نفي استطاعة العدل التام؛ فالتسوية في ميل القلب لا تتحقق ولو بلغ الحرص غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص145–146، تحت «براعة التعبير بـ﴿ولو حرصتم﴾».","url":""}]},{"id":"s4-328","number":328,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"ما سرّ النهي عن ﴿كل الميل﴾ دون النهي عن أصل الميل؟","answer":"لم ينه عن أصل الميل لأنه قلبي غير مقدور، وإنما نهى عن استرساله حتى يصير ميلًا كليًا يظهر في الحقوق والمعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص146، تحت عنوان «دلالة النهي الوارد بعد النفي»","url":""}]},{"id":"s4-329","number":329,"surah":4,"verses":[129],"references":[{"surah":4,"verses":[129]}],"verseLabel":"النساء: 129","question":"ما الصورة في قوله تعالى: ﴿فتذروها كالمعلقة﴾؟","answer":"شبه المرأة التي لا تنال حقوق الزوجة ولا تُطلق فتستقل بالمعلقة التي لا تستقر في جهة؛ فالتشبيه يجسم ألم إبقائها بين حالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص148، تحت «بلاغة التشبيه في قوله تعالى: ﴿فتذروها كالمعلقة﴾».","url":""}]},{"id":"s4-330","number":330,"surah":4,"verses":[130],"references":[{"surah":4,"verses":[130]}],"verseLabel":"النساء: 130","question":"ما سرّ التعبير بقوله تعالى: ﴿وإن يتفرقا﴾، دون: وإن يتطلقا؟","answer":"«يتفرقا» أعم من خصوص لفظ الطلاق، ويصور انفصال كل واحد عن صاحبه بعد تعذر الصلح، فيقابل اجتماعهما السابق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص153–154، تحت «دلالة التعبير بلفظ ﴿يتفرقا﴾ بدل (يتطلقا)».","url":""}]},{"id":"s4-331","number":331,"surah":4,"verses":[130],"references":[{"surah":4,"verses":[130]}],"verseLabel":"النساء: 130","question":"ما دلالة قوله تعالى: ﴿يغن الله كلًا من سعته﴾ بعد ذكر افتراق الزوجين؟","answer":"الوعد يبدد خوف الحاجة بعد الفراق: يغني الله كل واحد على حدة من فضل واسع، بعوض أو رزق أو زوج أصلح","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص153، تحت «دلالة الحذف والتنكير في قوله: ﴿يغن الله كلًّا﴾».","url":""}]},{"id":"s4-332","number":332,"surah":4,"verses":[131],"references":[{"surah":4,"verses":[131]}],"verseLabel":"النساء: 131","question":"ما سرّ تكرار قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾ في هذا السياق؟","answer":"تكرر إثبات الملك لأن كل موضع يبني عليه غرضًا: سعة إغناء الزوجين، والغنى عن طاعة الخلق، والقدرة على الاستبدال","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص155، 160، 162–166، تحت «نكتة تكرار جملة: ﴿ولله ما في السماوات وما في الأرض﴾».","url":""}]},{"id":"s4-333","number":333,"surah":4,"verses":[131],"references":[{"surah":4,"verses":[131]}],"verseLabel":"النساء: 131","question":"ما سرّ التعبير عن الأمر بالتقوى بقوله تعالى: ﴿ولقد وصينا﴾؟","answer":"«وصينا» تدل على شدة العناية بالتقوى وتأكيد حفظها والعمل بها، ثم قوِّيت باللام و«قد» وعموم الوصية للأمم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص157–158، تحت «سر التعبير بالوصية بدل الأمر بالتقوى».","url":""}]},{"id":"s4-334","number":334,"surah":4,"verses":[131],"references":[{"surah":4,"verses":[131]}],"verseLabel":"النساء: 131","question":"ما دلالة تقديم الذين أوتوا الكتاب على المخاطبين في الوصية بالتقوى؟","answer":"قدم أهل الكتاب لإلهاب همة المسلمين إلى التقوى بالتأسي بالأمم السابقة وألا يفضلهم من قبلهم في الامتثال","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص158، تحت «دلالة تقديم ذكر أهل الكتاب السابقين بالوصية».","url":""}]},{"id":"s4-335","number":335,"surah":4,"verses":[131,132],"references":[{"surah":4,"verses":[131,132]}],"verseLabel":"النساء: 131؛ 132","question":"ما سرّ اختلاف خاتمة تكرار قوله تعالى: ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ بين ﴿غَنِيًّا حَمِيدًا﴾ و﴿وَكَفَى بِاللَّهِ وَكِيلًا﴾؟","answer":"الأولى جاءت بعد الوعد بأن يغني الله الزوجين من سعته، فناسبها غناه المحمود. والثانية جاءت مع بيان قدرته على الاستبدال، فناسبها أنه الكافي في حفظ الأمر وتدبيره.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص142؛ إسلام ويب، باب النساء: 131–132","url":""}]},{"id":"s4-336","number":336,"surah":4,"verses":[133],"references":[{"surah":4,"verses":[133]}],"verseLabel":"النساء: 133","question":"على من يدل لفظ ﴿آخرين﴾ في قوله تعالى: ﴿إن يشأ يذهبكم أيها الناس ويأت بآخرين﴾، وما قرينة ذلك؟","answer":"لفظ «آخر» يقتضي مماثلة المذكور في جنسه. ولما تقدم خطاب ﴿أيها الناس﴾، دل «آخرين» على أناس غير المخاطبين، من جنسهم، يأتي الله بهم بدلًا منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص169–170، تحت «نكتة التعبير بقوله: ﴿آخرين﴾».","url":""}]},{"id":"s4-337","number":337,"surah":4,"verses":[134],"references":[{"surah":4,"verses":[134]}],"verseLabel":"النساء: 134","question":"ما مناسبة تقديم ثواب الدنيا في قوله تعالى: ﴿فعند الله ثواب الدنيا والآخرة﴾؟","answer":"قدم ثواب الدنيا لأنها مطلوب من قصر إرادته عليها في صدر الشرط، ثم ضم إليها الآخرة لتوبيخه على طلب الأدنى وحده ودعوته إلى الجمع بين الخيرين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص171–172، تحت «بلاغة قوله تعالى: ﴿فعند الله ثواب الدنيا والآخرة﴾».","url":""}]},{"id":"s4-338","number":338,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة صيغة المبالغة في قوله تعالى: ﴿كونوا قوامين بالقسط﴾؟","answer":"تفيد صيغة «قوامين» المبالغة في ملازمة العدل والقيام به في الأحوال المختلفة، حتى في الشهادة على النفس والوالدين والأقربين؛ فهو خلق ثابت يتكرر العمل به، لا موقف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص179، تحت «سر التعبير بصيغة المبالغة ﴿قوامين﴾».","url":""}]},{"id":"s4-339","number":339,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما سرّ تقديم القيام بالقسط على الشهادة لله في آية النساء؟","answer":"قُدم القيام بالقسط لأنه الأصل الجامع للعدل قولًا وفعلًا، ثم خُصت الشهادة بوصفها مظهرًا قوليًا لا يكمل إلا بالإخلاص لله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص180، تحت «سر تقديم الأمر بالقسط على جعل الشهادة لله تعالى في قوله تعالى: ﴿كونوا قوامين بالقسط شهداء لله﴾».","url":""}]},{"id":"s4-340","number":340,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة قوله تعالى: ﴿شهداء لله﴾، دون: شاهدين بالحق؟","answer":"«شهداء لله» يجعل الشهادة خالصة لوجه الله وتحت رقابته، فيعظم شأنها ويمنع محاباة النفس والقرابة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص180، تحت «نكتة تقييد الشهادة بكونها لله سبحانه في قوله تعالى: ﴿شهداء لله﴾».","url":""}]},{"id":"s4-341","number":341,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة البدء بالنفس في قوله تعالى: ﴿ولو على أنفسكم أو الوالدين والأقربين﴾؟","answer":"بدأ بالنفس لأنها أشد مواضع المحاباة وأصعبها، فمن أقام الحق عليها كان على إقامته على الوالدين والأقربين أقدر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص182، 184، تحت «نكتة التدلي في ترتيب المشهود عليهم في قوله تعالى: ﴿ولو على أنفسكم أو الوالدين والأقربين﴾».","url":""}]},{"id":"s4-342","number":342,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما دلالة الجمع بين الغني والفقير في قوله تعالى: ﴿إن يكن غنيًا أو فقيرًا فالله أولى بهما﴾؟","answer":"جمع الغني والفقير لاستيعاب ما قد يدعو إلى الجور في الشهادة: خوف الغني أو رجاء نفعه، والشفقة على الفقير. فلا يُترك الحق لأحدهما؛ فالله أعلم بمصلحتهما وأولى برعايتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص186–188، تحت «دلالة الطباق في قوله تعالى: ﴿غنيًا أو فقيرًا﴾».","url":""}]},{"id":"s4-343","number":343,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما مناسبة النهي عن اتباع الهوى قبل ذكر لَيّ الشهادة والإعراض عنها؟","answer":"قُدم النهي عن الهوى لأنه الدافع الباطن الذي ينشأ عنه ليّ الشهادة أو الإعراض عنها، فبدأ بالسبب ثم ذكر صورتي أثره","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص188–190، تحت «دلالة النهي عن اتباع الهوى بعد الأمر بالعدل».","url":""}]},{"id":"s4-344","number":344,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]},{"surah":5,"verses":[8]}],"verseLabel":"النساء: 135؛ المائدة: 8","question":"ما سرّ اختلاف الترتيب بين قوله تعالى في النساء: ﴿قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ﴾، وفي المائدة: ﴿قَوَّامِينَ لِلَّهِ شُهَدَاءَ بِالْقِسْطِ﴾؟","answer":"في النساء: 135: في النساء مقام الشهادة على النفس والأقربين، فقدم القسط مقصدًا ولو خالف الهوى، ثم جعل الشهادة لله. وفي المائدة مقام الوفاء بعهد الله، فقدم القيام لله ثم بين أن الشهادة تكون بالقسط.\n\nفي المائدة: 8: في المائدة المقام وفاء بعهد الله وعدل مع قوم مبغضين، فقدم القيام لله وجعل القسط وصف الشهادة. وفي النساء المقام شهادة على النفس والأقربين، فقدم القسط لمقاومة المحاباة.","sources":[{"label":"[النساء: 135] ابن جماعة، *كشف المعاني*؛ منقول في Quranpedia، ملاحظة 40886","url":""},{"label":"[المائدة: 8] موسوعة التفسير البلاغي، ج8، ص634، تحت «السر في تقدم القوامة بالقسط على الشهادة في النساء، وتأخرها في المائدة».","url":""}]},{"id":"s4-345","number":345,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"ما سرّ توجيه الخطاب إلى المؤمنين بقوله تعالى: ﴿يا أيها الذين آمنوا آمنوا﴾؟","answer":"من توجيهات الأمر أن يُطلب من المؤمنين الثبات والدوام على الإيمان، أو تكميله والإخلاص فيه والتصديق التفصيلي بما يجب الإيمان به؛ فليس المراد مجرد تحصيل إيمان حاصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص197–198، تحت «دلالة الأمر في قوله تعالى: ﴿آمنوا بالله ورسوله﴾».","url":""}]},{"id":"s4-346","number":346,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"لماذا قُدّم الرسول على الكتاب في الأمر بالإيمان، ثم قُدمت الكتب على الرسل في الوعيد بالكفر في الآية نفسها؟","answer":"اختلف الترتيب باختلاف الاعتبار: ففي تلقي الناس الإيمان يتقدم الرسول الذي يبلّغهم الكتاب، وفي نزول الوحي من الله يتقدم الكتاب على الرسول المبلِّغ؛ فناسب كل ترتيب جهة النظر إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص200، تحت «نكتة تغاير الترتيب بين الرسول والكتاب في قوله تعالى: ﴿آمنوا بالله ورسوله والكتاب﴾، وقوله سبحانه: ﴿وكتبه ورسله﴾».","url":""}]},{"id":"s4-347","number":347,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"ما سرّ التعبير عن القرآن بقوله تعالى: ﴿الْكِتَابِ الَّذِي نَزَّلَ عَلَى رَسُولِهِ﴾، وعن الكتب السابقة بقوله: ﴿وَالْكِتَابِ الَّذِي أَنْزَلَ مِنْ قَبْلُ﴾؟","answer":"التنزيل بالتشديد يلحظ نزول القرآن مفرقًا متتابعًا، والإنزال في الكتب السابقة يلحظ أصل إيتائها؛ فاختلاف الصيغة يطابق جهة العرض في كل موضع.","sources":[{"label":"فاضل السامرائي، *لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44579","url":""}]},{"id":"s4-348","number":348,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"ما سرّ تأخير ﴿اليوم الآخر﴾ في النساء بعد الملائكة والكتب والرسل؟","answer":"سياق النساء في وجوب الإيمان بالوحي ورسله، فجمع وسائط الوحي أولًا ثم ختم باليوم الآخر الذي يظهر فيه جزاء التكذيب؛ فجاء الترتيب تابعًا لغرض السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص757، تحت «توجيه متشابه اللفظ»","url":""}]},{"id":"s4-349","number":349,"surah":4,"verses":[137],"references":[{"surah":4,"verses":[137]}],"verseLabel":"النساء: 137","question":"ما دلالة تكرار ﴿ثم﴾ في قوله تعالى: ﴿آمنوا ثم كفروا ثم آمنوا ثم كفروا﴾؟","answer":"تكرار «ثم» يرسم انتقالات متراخية متعاقبة بين الإيمان والكفر، ويكشف تكرر النقض بعد تجدد الحجة لا مجرد إعادة لفظية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص203–204، تحت «سر عطف الجمل بـ﴿ثم﴾ في قوله تعالى: ﴿إن الذين آمنوا ثم كفروا ثم آمنوا ثم كفروا ثم ازدادوا كفرًا﴾».","url":""}]},{"id":"s4-350","number":350,"surah":4,"verses":[137],"references":[{"surah":4,"verses":[137]}],"verseLabel":"النساء: 137","question":"ما دلالة قوله تعالى: ﴿ثم ازدادوا كفرًا﴾، دون الاكتفاء باستمرارهم عليه؟","answer":"«ازدادوا كفرًا» يدل على نمو الكفر وترسخه بإضافة كفر إلى كفر بعد التقلب، وهو أبلغ من مجرد البقاء على درجة واحدة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص204–205، تحت «نكتة إيثار التعبير بالفعل ﴿ازدادوا﴾ دون (زادوا)».","url":""}]},{"id":"s4-351","number":351,"surah":4,"verses":[138],"references":[{"surah":4,"verses":[138]}],"verseLabel":"النساء: 138","question":"ما سرّ التعبير بالبشارة في قوله تعالى: ﴿بشر المنافقين بأن لهم عذابًا أليمًا﴾؟","answer":"استعير لفظ البشارة، الذي يستعمل في الخبر السار، للإخبار بالعذاب الأليم تهكمًا بالمنافقين؛ فالمفارقة بين البشارة والعذاب تزيد التقريع والوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص208–209، تحت «بلاغة الاستعارة التهكمية في قوله تعالى: ﴿بشر المنافقين﴾».","url":""}]},{"id":"s4-352","number":352,"surah":4,"verses":[139],"references":[{"surah":4,"verses":[139]}],"verseLabel":"النساء: 139","question":"ما سرّ اختيار ﴿العزة﴾ في قوله تعالى: ﴿أيبتغون عندهم العزة﴾؟","answer":"العزة هي المنعة والرفعة التي تمنع الذل، وهي الغاية التي توهم المنافقون طلبها بموالاة الكافرين؛ فرد السياق بأن العزة كلها لله، وهو أدق من القوة أو النصرة وحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص211، 213–214، تحت «بلاغة الاستفهام التوبيخي في قوله تعالى: ﴿أيبتغون عندهم العزة﴾».","url":""}]},{"id":"s4-353","number":353,"surah":4,"verses":[140],"references":[{"surah":4,"verses":[140]}],"verseLabel":"النساء: 140","question":"لماذا جاء النهي عن القعود مع المستهزئين بآيات الله، ولم يُكتفَ بالنهي عن الرضا بقولهم؟","answer":"لأن الرضا أمر باطن، أما ترك القعود فيُظهر إنكار صنيعهم والغضب لله؛ فالنهي عن المجلس أبلغ في قطع المشاركة وإعلان رفض الاستهزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص220–221، تحت «بلاغة الكناية في قوله تعالى: ﴿فلا تقعدوا معهم﴾».","url":""}]},{"id":"s4-354","number":354,"surah":4,"verses":[140],"references":[{"surah":4,"verses":[140]}],"verseLabel":"النساء: 140","question":"ما دلالة قوله تعالى: ﴿إنكم إذًا مثلهم﴾، دون: فإنكم منهم؟","answer":"«مثلهم» يقرر المساواة في إثم الرضا والاستهزاء مع بقاء تمييز الأشخاص، بخلاف «منهم» التي قد تفيد اندراجًا مطلقًا في جماعتهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص222–223، تحت «بلاغة التشبيه في قوله تعالى: ﴿إنكم إذًا مثلهم﴾».","url":""}]},{"id":"s4-355","number":355,"surah":4,"verses":[140],"references":[{"surah":4,"verses":[140]}],"verseLabel":"النساء: 140","question":"ما مناسبة جمع المنافقين والكافرين في جهنم جميعًا بعد النهي عن مجالس الاستهزاء؟","answer":"جمع المنافقين والكافرين في جهنم لأن المنافقين جالسوهم ورضوا بخوضهم ووالوهم فصاروا مثلهم في الجرم، فناسب اتحاد المصير اتحاد السلوك","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص223–225، تحت «علة فصل قوله تعالى: ﴿إن الله جامع المنافقين والكافرين في جهنم جميعًا﴾ عما قبله».","url":""}]},{"id":"s4-356","number":356,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما سرّ وصف المنافقين بقوله تعالى: ﴿الذين يتربصون بكم﴾؟","answer":"التربص انتظار مترقب مع مراقبة تحول الأحوال؛ وهو يصور المنافقين واقفين على النتائج ليظهروا لكل فريق أنهم معه طلبًا للغنيمة والنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص226، 229–230، تحت «سر العدول عن الفعل (ينتظرون) إلى ﴿يتربصون﴾».","url":""}]},{"id":"s4-357","number":357,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما دلالة اختلاف خطاب المنافقين عند فتح المؤمنين: ﴿ألم نكن معكم﴾، وعند نصيب الكافرين: ﴿ألم نستحوذ عليكم ونمنعكم من المؤمنين﴾؟","answer":"مع المؤمنين ادعوا المعية الظاهرة لأنهم عاشوا بينهم وحضروا القتال طلبًا للغنيمة، ومع الكافرين ادعوا الاستحواذ والمنع سرًا؛ أي التمكن منهم وحمايتهم بتخذيل المؤمنين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص234، 236–238، تحت «دلالة الإخبار بالمعية مع المؤمنين دون الكافرين».","url":""}]},{"id":"s4-358","number":358,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما سرّ التعبير عن نصر المؤمنين بقوله تعالى: ﴿فتح من الله﴾؟","answer":"«الفتح» أوسع أثرًا من مجرد النصر؛ فهو إزالة للإغلاق وفتح للبلاد وما يتبعه من غنائم وفيء، وذلك أدعى لطمع المنافقين في سهم منها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص233، تحت «دلالة التعبير بالفتح دون النصر».","url":""}]},{"id":"s4-359","number":359,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"ما سرّ التعبير عما يناله الكافرون بقوله تعالى: ﴿نصيب﴾، دون: فتح أو نصر؟","answer":"سمى ما يقع للكافرين ﴿نَصِيبٌ﴾، أي حظًا عارضًا، ولم يشرفه باسم الفتح المسند إلى الله كما فعل مع المؤمنين؛ ففي اختلاف اللفظ اختلاف في تقويم النتيجتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص232–233، 236، تحت «علة تسمية ظفر المسلمين فتحًا وظفر الكافرين نصيبًا».","url":""}]},{"id":"s4-360","number":360,"surah":4,"verses":[141],"references":[{"surah":4,"verses":[141]}],"verseLabel":"النساء: 141","question":"كيف يُفهم قوله تعالى: ﴿ولن يجعل الله للكافرين على المؤمنين سبيلًا﴾ مع وقوع غلبة للكافرين أحيانًا؟","answer":"ذكرت الموسوعة وجوهًا: نفي حجة الكافرين على المؤمنين يوم القيامة، أو نفي أن تكون حجتهم أقوى من حجة المسلمين. وذكرت أن ما يقع من ظهور عارض لا ينقض أصل الوعد بنصرة المؤمنين؛ فلا يُفهم النفي على أنه امتناع كل غلبة مؤقتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص242–244، تحت «توجيه نفي ظهور الكافرين على المؤمنين».","url":""}]},{"id":"s4-361","number":361,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما سرّ التعبير بقوله تعالى: ﴿إن المنافقين يخادعون الله﴾ بصيغة المفاعلة؟","answer":"صيغة المفاعلة في «يخادعون» تصور محاولة المغالبة وتكرار إظهار الإيمان وإبطان الكفر، مع توهمهم أن خداعهم ينجح؛ وهي أبلغ من فعل الخداع المجرد","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص249–250، تحت «دلالة اختيار صيغة يخادعون دون يخدعون».","url":""}]},{"id":"s4-362","number":362,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما دلالة مجيء فعل المنافقين مضارعًا في ﴿يخادعون﴾، وجواب الله جملة اسمية في ﴿وهو خادعهم﴾؟","answer":"المضارع في «يخادعون» لتجدد محاولتهم وحدوثها، والاسم في «خادعهم» لثبوت تدبير الله المحيط ودوامه وغلبته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص252، تحت «دلالة التعبير بصيغة الفعل مع المنافقين، وبالاسم مع الله تعالى».","url":""}]},{"id":"s4-363","number":363,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما سرّ التعبير بقوله تعالى: ﴿قاموا إلى الصلاة﴾، دون: أقاموا الصلاة؟","answer":"«قاموا إلى الصلاة» يصور مجرد النهوض إليها متثاقلين لأجل الناس، لا إقامتها بحدودها وخشوعها كما يفعل المؤمن","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص253–254، تحت «سر العدول عن (أقاموا الصلاة) إلى ﴿قاموا إلى الصلاة﴾».","url":""}]},{"id":"s4-364","number":364,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما دلالة وصف المنافقين بـ﴿كسالى﴾ بصيغة الاسم؟","answer":"جاء «كسالى» اسمًا وحالًا لازمة لإفادة ثبوت الكسل وتمكنه منهم عند الصلاة، بخلاف «يتكاسلون» الذي قد يوحي بتجدد عارض","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص255، تحت «إيثار التعبير بالاسم ﴿كسالى﴾ دون يتكاسلون في قوله: ﴿قاموا كسالى﴾».","url":""}]},{"id":"s4-365","number":365,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"ما مناسبة ذكر الرياء بعد الكسل في الصلاة؟","answer":"الكسل يكشف فقد الدافع الباطن إلى الصلاة، ثم جاء الرياء ليبين الدافع البديل الظاهر: رؤية الناس؛ فالثاني يعلل الأول ويفضح المقصد","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص255–256، تحت «فائدة الفصل والاستئناف في جملة: ﴿يراءون الناس﴾».","url":""}]},{"id":"s4-366","number":366,"surah":4,"verses":[142],"references":[{"surah":4,"verses":[142]}],"verseLabel":"النساء: 142","question":"كيف يجتمع إظهار المنافقين الصلاة مع قوله تعالى: ﴿ولا يذكرون الله إلا قليلًا﴾؟","answer":"صلاتهم للناس لا لله، فلا يذكرونه إلا ذكرًا قليلًا عند حضور المؤمنين، أما الخلوة فتفضح خلو القلب من الذكر؛ إظهار صورة الصلاة لا يساوي ذكر الله الحقيقي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص258–259، تحت «سر وصف ذكرهم لله تعالى بالقلة».","url":""}]},{"id":"s4-367","number":367,"surah":4,"verses":[143],"references":[{"surah":4,"verses":[143]}],"verseLabel":"النساء: 143","question":"ما الصورة في قوله تعالى: ﴿مذبذبين بين ذلك﴾، دون: مترددين؟","answer":"«مذبذبين» تصور حركة متكررة قلقة تدفعهم بين الفريقين من غير استقرار، وكأن قوة خارجية تذبذبهم؛ وهي أبلغ من تردد ذهني اختياري","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص263–265، تحت «إيثار هذه المادة ﴿مذبذبين﴾ دون مترددين».","url":""}]},{"id":"s4-368","number":368,"surah":4,"verses":[143],"references":[{"surah":4,"verses":[143]}],"verseLabel":"النساء: 143","question":"ما دلالة إفراد اسم الإشارة في قوله تعالى: ﴿مذبذبين بين ذلك﴾ مع ذكر فريقين؟","answer":"أُفرد اسم الإشارة باعتبار مجموع ما تقدم كأنه مذكور واحد، أو لأن «ذا» يصلح في أصل وضعه للإشارة إلى الواحد والاثنين والجمع؛ فالمراد تذبذبهم بين الإيمان والكفر، وليس الإفراد نفيًا لوجود طرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص265–266، تحت «السر في توحيد اسم الإشارة، مع أن المشار إليه أمران».","url":""}]},{"id":"s4-369","number":369,"surah":4,"verses":[143],"references":[{"surah":4,"verses":[143]}],"verseLabel":"النساء: 143","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿لا إلى هؤلاء ولا إلى هؤلاء﴾؟","answer":"تكرار «لا» ينفي انتماءهم إلى كل فريق استقلالًا ويؤكد استغراق النفي من الجهتين، فيرسخ صورة الضياع الكامل بينهما","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص267، تحت «السر في تكرار النفي في قوله سبحانه: ﴿لا إلى هؤلاء ولا إلى هؤلاء﴾».","url":""}]},{"id":"s4-370","number":370,"surah":4,"verses":[144],"references":[{"surah":4,"verses":[144]}],"verseLabel":"النساء: 144","question":"ما سرّ اختيار الأولياء في قوله تعالى: ﴿لا تتخذوا الكافرين أولياء﴾، دون: أنصارًا؟","answer":"الولاية أوسع من النصرة؛ تشمل القرب والمودة والطاعة والتدبير والتحالف، فنهى عن أصل الرابطة التي تفضي إلى النصرة لا عن صورة واحدة منها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص273، تحت «سر التعبير بالأولياء دون نصراء».","url":""}]},{"id":"s4-371","number":371,"surah":4,"verses":[144],"references":[{"surah":4,"verses":[144]}],"verseLabel":"النساء: 144","question":"ما دلالة قوله تعالى: ﴿من دون المؤمنين﴾، ثم قوله: ﴿أتريدون أن تجعلوا لله عليكم سلطانًا مبينًا﴾؟","answer":"«من دون المؤمنين» يكشف استبدال رابطة الإيمان بموالاة الكافرين، والاستفهام يوبخهم لأن هذا الاختيار يصنع لله عليهم حجة ظاهرة تستوجب إلحاقهم بالمنافقين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص272–275، تحت «سر ذكر السلطان في سياق النهي عن الموالاة».","url":""}]},{"id":"s4-372","number":372,"surah":4,"verses":[144],"references":[{"surah":4,"verses":[144]}],"verseLabel":"النساء: 144","question":"ما سرّ مجيء النهي في النساء خطابًا مباشرًا: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا…﴾، وفي آل عمران بصيغة الغائب: ﴿لَا يَتَّخِذِ الْمُؤْمِنُونَ…﴾؟","answer":"آية النساء تواجه المؤمنين في سياق كشف المنافقين والتحذير من مسلكهم، فناسب النداء والنهي المباشر. وآل عمران تقرر أصلًا عامًا في سياق محاجة أهل الكتاب، فناسبها أسلوب الغائب.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44131","url":""}]},{"id":"s4-373","number":373,"surah":4,"verses":[145],"references":[{"surah":4,"verses":[145]}],"verseLabel":"النساء: 145","question":"ما سرّ إظهار اسم المنافقين في قوله تعالى: ﴿إن المنافقين في الدرك الأسفل﴾، دون: إنهم؟","answer":"أظهر اسم «المنافقين» بدل الضمير لتسجيل الوصف سببًا للحكم، وللدلالة الاسمية على ثبوت النفاق فيمن مات عليه، مع تحذير المؤمنين من صفته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص278–279، تحت «نكتة العدول عن تعريف المنافقين بالموصولية إلى الاسم الصريح».","url":""}]},{"id":"s4-374","number":374,"surah":4,"verses":[145],"references":[{"surah":4,"verses":[145]}],"verseLabel":"النساء: 145","question":"ما سرّ التعبير بقوله تعالى: ﴿الدرك الأسفل﴾، دون: الطبقة السفلى؟","answer":"الدرك يقال للمراتب الهابطة، في مقابل الدرجات الصاعدة، وجعل المنافقين في أسفله يصور تناهي هبوطهم بسبب جمعهم الكفر والخداع والإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص277، 280–281، تحت «السر في اختيار الدرك الأسفل في عقاب المنافقين».","url":""}]},{"id":"s4-375","number":375,"surah":4,"verses":[145],"references":[{"surah":4,"verses":[145]}],"verseLabel":"النساء: 145","question":"ما مناسبة الاقتصار على النصير في قوله تعالى: ﴿ولن تجد لهم نصيرًا﴾؟","answer":"المقام مقام إنقاذ من العذاب، فناسب «النصير» الأعم في دفع الضرر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص284–285، تحت «دلالة اختيار (نصير) بدلًا من (الولي)».","url":""}]},{"id":"s4-376","number":376,"surah":4,"verses":[146],"references":[{"surah":4,"verses":[146]}],"verseLabel":"النساء: 146","question":"ما دلالة جمع التوبة والإصلاح والاعتصام والإخلاص في شروط رجوع المنافقين؟","answer":"قوبلت أوصاف النفاق بما يرفعها: التوبة من الكفر، وإصلاح ما أفسدوه، والاعتصام بالله بدل التذبذب بين المؤمنين والكافرين، وإخلاص الدين بدل الرياء. فتجمع الآية تصحيح الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص287–289، تحت «وجه اشتراط التوبة والإصلاح والاعتصام والإخلاص على المنافقين».","url":""}]},{"id":"s4-377","number":377,"surah":4,"verses":[146],"references":[{"surah":4,"verses":[146]}],"verseLabel":"النساء: 146","question":"ما مناسبة ذكر الاعتصام بالله بعد الإصلاح؟","answer":"بعد إصلاح الفساد جاء الاعتصام بالله ليعالج تذبذب المنافقين بين المؤمنين والكافرين؛ فهو تمسك بالله وثبات على الإيمان، ويكمل إصلاح الأعمال بإصلاح جهة الاعتماد والولاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص288–289، تحت «وجه اشتراط التوبة والإصلاح والاعتصام والإخلاص على المنافقين».","url":""}]},{"id":"s4-378","number":378,"surah":4,"verses":[146],"references":[{"surah":4,"verses":[146]}],"verseLabel":"النساء: 146","question":"ما سرّ التعبير بقوله تعالى: ﴿فأولئك مع المؤمنين﴾، دون: من المؤمنين؟","answer":"ناسبت المعية حال من كان منفصلًا عن جماعة المؤمنين بنفاقه ثم عاد بالتوبة والإصلاح؛ فهي تبشر بإلحاقه بصحبتهم وحكمهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص291، تحت «سر التعبير بمعيتهم للمؤمنين دون وصفهم بالمؤمنين».","url":""}]},{"id":"s4-379","number":379,"surah":4,"verses":[147],"references":[{"surah":4,"verses":[147]}],"verseLabel":"النساء: 147","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ما يفعل الله بعذابكم إن شكرتم وآمنتم﴾؟","answer":"الاستفهام للتقرير والنفي الإنكاري، وهو أبلغ من الخبر في نفي كل غرض أو نفع لله في تعذيب من شكر وآمن","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص295، تحت «دلالة الاستفهام».","url":""}]},{"id":"s4-380","number":380,"surah":4,"verses":[147],"references":[{"surah":4,"verses":[147]}],"verseLabel":"النساء: 147","question":"ما دلالة الجمع بين الشكر والإيمان في قوله تعالى: ﴿إن شكرتم وآمنتم﴾؟","answer":"قُدم الشكر لأن النظر في النعم ومعرفتها يقود إلى معرفة المنعم والإيمان به، فهو سبب متقدم على مسببه، ثم عطف الإيمان عليه عطف الخاص على العام أو المسبب على السبب","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص296–297، تحت «دلالة تقديم الشكر على الإيمان».","url":""}]},{"id":"s4-381","number":381,"surah":4,"verses":[147],"references":[{"surah":4,"verses":[147]}],"verseLabel":"النساء: 147","question":"ما دلالة وصف الله تعالى بقوله: ﴿شاكرًا عليمًا﴾؟","answer":"وصفه تعالى بالشكر يفيد قبول القليل من الطاعة والمجازاة عليه بالأجر الكثير، ووصفه بالعلم يطمئن إلى أنه يعلم إيمانهم وشكرهم ونياتهم فلا يضيع جزاؤهم؛ فالخاتمة وعد مناسب لما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص297–299، تحت «السر في وصف الله تعالى بالشكر، والشكر من صفات العباد».","url":""}]},{"id":"s4-382","number":382,"surah":4,"verses":[148],"references":[{"surah":4,"verses":[148]}],"verseLabel":"النساء: 148","question":"ما دلالة تقييد النهي بالجهر في قوله تعالى: ﴿لا يحب الله الجهر بالسوء من القول﴾؟","answer":"خُص الجهر لأنه يذيع الإساءة بين السامعين فيشتد ضررها، والتقييد بالسوء لا يقتضي منع كل جهر. وذكر القول، وهو أخف من الفعل، ينبه إلى قبح ما فوقه من الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص304، تحت «التقييد بالجهر بالسوء وبالقول».","url":""}]},{"id":"s4-383","number":383,"surah":4,"verses":[148],"references":[{"surah":4,"verses":[148]}],"verseLabel":"النساء: 148","question":"ما دلالة استثناء ﴿إلا من ظلم﴾ من النهي عن الجهر بالسوء؟","answer":"الاستثناء يرخص للمظلوم أن يجهر بشكايته ويذكر ظلامته أو يدعو على ظالمه في حدود حقه، ولا يبيح له العدوان أو مطلق السباب","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص304–305، تحت «دلالة الاستثناء في الآية».","url":""}]},{"id":"s4-384","number":384,"surah":4,"verses":[148],"references":[{"surah":4,"verses":[148]}],"verseLabel":"النساء: 148","question":"ما مناسبة ترتيب ﴿سميعًا عليمًا﴾ في ختام آية الجهر بالسوء؟","answer":"قُدم «سميعًا» لمناسبة الجهر والقول المسموع في صدر الآية، ثم «عليمًا» لإحاطة العلم بالنيات وحقيقة الظلم وما خفي من الحال","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص305–306، تحت «فاصلة الآية ومفاد ما أوحت به».","url":""}]},{"id":"s4-385","number":385,"surah":4,"verses":[149],"references":[{"surah":4,"verses":[149]}],"verseLabel":"النساء: 149","question":"ما دلالة مقابلة إبداء الخير بإخفائه، ثم إفراد العفو عن السوء؟","answer":"الخير صالح للإبداء والإخفاء، ثم خُص العفو لأنه الخلق الأعلى المقابل لرخصة الجهر للمظلوم في السياق السابق، وفيه حث على ترك المؤاخذة مع القدرة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص310–311، تحت «بلاغة الترقي في الخطاب».","url":""}]},{"id":"s4-386","number":386,"surah":4,"verses":[149],"references":[{"surah":4,"verses":[149]}],"verseLabel":"النساء: 149","question":"ما مناسبة الجمع بين العفو والقدرة في قوله تعالى: ﴿فإن الله كان عفوًا قديرًا﴾؟","answer":"العفو مع القدرة هو الكمال؛ لأن العاجز قد يترك الانتقام لعجزه، أما الله فيعفو وهو قادر، وفي ذلك حث للمؤمن على العفو حين يقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص311–312، تحت «سر الختام بصفتي العفو والقدرة».","url":""}]},{"id":"s4-387","number":387,"surah":4,"verses":[149],"references":[{"surah":4,"verses":[149]}],"verseLabel":"النساء: 149","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿إِنْ تُبْدُوا خَيْرًا أَوْ تُخْفُوهُ﴾، وفي الأحزاب: ﴿إِنْ تُبْدُوا شَيْئًا أَوْ تُخْفُوهُ﴾؟","answer":"في النساء قُيد الإبداء والإخفاء بالخير لأن المقام في العفو وحسن المعاملة، وفي الأحزاب عُمم بـ﴿شيئًا﴾ لأن علم الله هناك متعلق بكل ما يظهر أو يخفى، خيرًا كان أو غيره.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44146","url":""}]},{"id":"s4-388","number":388,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة تكرار ذكر الرسل في قوله تعالى: ﴿يكفرون بالله ورسله ويريدون أن يفرقوا بين الله ورسله﴾؟","answer":"لو جيء بالضمير بعد ذكر الله ورسله، لأمكن أن يوهم أن المراد التفريق بين بعض الرسل فحسب؛ فأعيد ذكر الله والرسل للتصريح بالتفريق بين الإيمان بالله والإيمان برسله، ودفع إبهام مرجع الضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص320–321، تحت «نكتة إعادة لفظ الرسل».","url":""}]},{"id":"s4-389","number":389,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة تقديم قولهم ﴿نؤمن ببعض﴾ على ﴿ونكفر ببعض﴾؟","answer":"قدموا دعوى الإيمان ببعض لتزيين موقفهم وستر أصل الكفر، ثم صرح السياق بما يهدمها؛ فليست الأولوية ترتيبًا زمنيًا ولا مجرد عناية","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص319–322","url":""}]},{"id":"s4-390","number":390,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة قوله تعالى: ﴿ويريدون أن يتخذوا بين ذلك سبيلًا﴾ مع أنه لا منزلة بين الإيمان والكفر؟","answer":"«بين ذلك سبيلًا» يحكي إرادتهم اتخاذ طريق موهوم بين الإيمان والكفر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص321، تحت «نكتة التعبير بالتركيب ﴿بين ذلك﴾».","url":""}]},{"id":"s4-391","number":391,"surah":4,"verses":[150,151],"references":[{"surah":4,"verses":[150,151]}],"verseLabel":"النساء: 150–151","question":"ما دلالة القصر في قوله تعالى: ﴿أولئك هم الكافرون حقًا﴾؟","answer":"ضمير الفصل و﴿حقًا﴾ يقطعان توهم منزلة وسطى بين الإيمان والكفر؛ فرفض رسول واحد نقض لأصل الإيمان بالرسل كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص322–323، تحت «بلاغة حشد المؤكدات على حكم الكفر».","url":""}]},{"id":"s4-392","number":392,"surah":4,"verses":[152],"references":[{"surah":4,"verses":[152]}],"verseLabel":"النساء: 152","question":"ما دلالة ﴿أحد﴾ في قوله تعالى: ﴿ولم يفرقوا بين أحد منهم﴾؟","answer":"«أحد» في سياق النفي يعم كل فرد من الرسل، فيفيد انتفاء أي تفريق بينهم مع وجوب الإيمان بالجميع","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص328، تحت «علة دخول ﴿بين﴾ على ﴿أحد﴾».","url":""}]},{"id":"s4-393","number":393,"surah":4,"verses":[152],"references":[{"surah":4,"verses":[152]}],"verseLabel":"النساء: 152","question":"ما دلالة قوله تعالى: ﴿أولئك سوف يؤتيهم أجورهم﴾ بعد وصف المؤمنين بالرسل جميعًا؟","answer":"يؤكد الوعد استحقاق المؤمنين بالله وجميع رسله للأجر، ويفيد التعبير بـ«سوف» تحقق الجزاء في الاستقبال. و«أجورهم» تدل على توفية ما استحقوه من الأجر، والله هو المتكفل بإيتائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص328–330، تحت «نكتة التعبير بـ(سوف)».","url":""}]},{"id":"s4-394","number":394,"surah":4,"verses":[153],"references":[{"surah":4,"verses":[153]}],"verseLabel":"النساء: 153","question":"لماذا عُبّر بالمضارع ﴿يسألك﴾ في حكاية طلب أهل الكتاب إنزال كتاب من السماء؟","answer":"يستحضر المضارع مشهد سؤالهم العجيب كأنه يقع أمام السامع، ويحتمل أيضًا الدلالة على تجدد الطلب وإلحاحهم فيه؛ وكلا الوجهين يُبرز التعجب من تعنت السائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص334–335، تحت «نكتة التعبير عن السؤال بالمضارع».","url":""}]},{"id":"s4-395","number":395,"surah":4,"verses":[153],"references":[{"surah":4,"verses":[153]}],"verseLabel":"النساء: 153","question":"ما مناسبة الانتقال من طلب إنزال كتاب إلى التذكير بقولهم لموسى: ﴿أرنا الله جهرة﴾؟","answer":"ذُكر طلب رؤية الله عقب طلب تنزيل الكتاب لبيان أن تعنتهم مع النبي امتداد لتعنت أسلافهم مع موسى، وأنهم سبق أن طلبوا ما هو أعظم وأشد، فلا يدل الطلب الحالي على طلب هداية صادق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص334–335، تحت «دلالة الفاء في الجواب».","url":""}]},{"id":"s4-396","number":396,"surah":4,"verses":[153],"references":[{"surah":4,"verses":[153]}],"verseLabel":"النساء: 153","question":"ما دلالة قوله تعالى في الصاعقة: ﴿بظلمهم﴾، ثم في اتخاذ العجل: ﴿من بعد ما جاءتهم البينات﴾؟","answer":"«بظلمهم» يصرح بسبب أخذ الصاعقة في طلب الرؤية، ثم «من بعد ما جاءتهم البينات» يغلظ جريمة اتخاذ العجل بوقوعها بعد وضوح الآيات","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص334، 336، تحت «نكتة العطف بـ﴿ثم﴾».","url":""}]},{"id":"s4-397","number":397,"surah":4,"verses":[153],"references":[{"surah":2,"verses":[51,92]},{"surah":4,"verses":[153]},{"surah":7,"verses":[148,152]}],"verseLabel":"النساء: 153؛ البقرة: 51، 92؛ الأعراف: 148؛ الأعراف: 152","question":"ما سرّ حذف المفعول الثاني في قوله تعالى: ﴿ثم اتخذوا العجل﴾، وما تقديره؟","answer":"في النساء: 153؛ البقرة: 51، 92؛ الأعراف: 148: ﴿اتَّخَذَ﴾ هنا بمعنى صيّر، ولذلك يتعدى إلى مفعولين؛ والمفعول الثاني محذوف تقديره: اتخذوا العجل إلهًا أو معبودًا. دل على المحذوف تصريحهم في موضع آخر: ﴿هذا إلهكم وإله موسى﴾، فحذفه إيجاز للعلم به من القصة.\n\nفي الأعراف: 152: حذف المفعول الثاني، أي «إلهًا»، للعلم به من السياق، وللاستهجان حتى كأن ذكره مما ينزه عنه اللسان.","sources":[{"label":"[النساء: 153؛ البقرة: 51، 92؛ الأعراف: 148] الواحدي، *التفسير البسيط*، تحت الأعراف: 152؛ نقلًا عن الطبري 9/70، والزجاج 2/379، والنحاس 3/84، النص المحقق","url":"https://tafsir.app/albaseet/7/152"},{"label":"[الأعراف: 152] موسوعة التفسير البلاغي، ج14، ص598–606","url":""}]},{"id":"s4-398","number":398,"surah":4,"verses":[154],"references":[{"surah":4,"verses":[154]}],"verseLabel":"النساء: 154","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء والبقرة: ﴿رَفَعْنَا فَوْقَهُمُ الطُّورَ﴾، وفي الأعراف: ﴿نَتَقْنَا الْجَبَلَ فَوْقَهُمْ﴾؟","answer":"«نتقنا» يدل على اقتلاع الجبل ورفعه مع تقديم الفعل وإبراز عظم الحدث، فناسب تفصيل الأعراف المكي، أما «رفعنا فوقهم الطور» فجرى في السورتين المدنيتين وناسب فعل الرفع اسم «الطور» الدال على الارتفاع","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص550، تحت «سر ذكر ﴿الطور﴾ هنا و﴿الجبل﴾ في الأعراف»، في المقارنة بالبقرة والنساء والأعراف.","url":""}]},{"id":"s4-399","number":399,"surah":4,"verses":[155,156],"references":[{"surah":4,"verses":[155,156]}],"verseLabel":"النساء: 155–156","question":"ما دلالة تراكم الجرائم في نسق واحد: نقض الميثاق، والكفر بالآيات، وقتل الأنبياء، وقولهم: قلوبنا غلف؟","answer":"عطف الجرائم بالواو يجعل كل واحدة منها وصفًا مستقلًا مستوجبًا للعقاب؛ فإذا اجتمعت اشتد استحقاق الوعيد، فظهر عظم الجناية من أفرادها ومن اجتماعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص346–347، تحت «دلالة العطف بالواو في قوله: ﴿وكفرهم﴾».","url":""}]},{"id":"s4-400","number":400,"surah":4,"verses":[155],"references":[{"surah":4,"verses":[155]}],"verseLabel":"النساء: 155","question":"ما دلالة قوله تعالى: ﴿وقتلهم الأنبياء بغير حق﴾ مع أن قتل الأنبياء لا يكون بحق؟","answer":"«بغير حق» ليست قيدًا يوهم إمكان قتل الأنبياء بحق، بل زيادة في تشنيع فعلهم وبلوغهم غاية الظلم؛ والتنـكير ينفي أي وجه من وجوه الحق كبيرًا أو صغيرًا","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص348–349، تحت «فائدة قوله: ﴿بغير حق﴾، ونفي مفهوم المخالفة».","url":""}]},{"id":"s4-401","number":401,"surah":4,"verses":[155],"references":[{"surah":4,"verses":[155]}],"verseLabel":"النساء: 155","question":"ما دلالة الإضراب بقوله تعالى: ﴿بل طبع الله عليها بكفرهم﴾ بعد قولهم: ﴿قلوبنا غلف﴾؟","answer":"«بل» ترد اعتذارهم بأن قلوبهم خُلقت مغلقة أو مستغنية بالعلم، وتثبت أن الطبع جزاء اختيارهم الكفر بعد أن خلق الله القلوب قابلة للحق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص349–351، تحت «دلالة الإضراب، وبلاغة الرد».","url":""}]},{"id":"s4-402","number":402,"surah":4,"verses":[156],"references":[{"surah":4,"verses":[156]}],"verseLabel":"النساء: 156","question":"ما سرّ وصف قولهم على مريم بأنه ﴿بهتانًا عظيمًا﴾؟","answer":"البهتان كذب يحيّر من شدة افترائه، ووصفه بالعظيم يوافق فظاعة الطعن في مريم الطاهرة مع ما ظهر من آيات براءتها؛ فالجريمة عظيمة في موضوعها ودليل بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص353، تحت «سر تسمية الرمي بالزنى بهتانًا».","url":""}]},{"id":"s4-403","number":403,"surah":4,"verses":[157],"references":[{"surah":4,"verses":[157]}],"verseLabel":"النساء: 157","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿وما قتلوه وما صلبوه﴾؟","answer":"كرر النفي لإبطال كل دعوى على استقلال: لا تحقق قتل عيسى عليه السلام، ولا تحقق صلبه؛ ثم كشف أن منشأ خبرهم هو الشبه لا العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص355–356، تحت «بلاغة الرد على مزاعم اليهود في قتل عيسى ﷺ وصلبه».","url":""}]},{"id":"s4-404","number":404,"surah":4,"verses":[157],"references":[{"surah":4,"verses":[157]}],"verseLabel":"النساء: 157","question":"ما سرّ بناء قوله تعالى: ﴿ولكن شبه لهم﴾ للمجهول؟","answer":"البناء للمفعول في «شُبّه» يثبت وقوع الاشتباه دون تعيين الفاعل، وتذكر الصفحة احتمال إسناده إلى الجار والمجرور أو إلى ضمير المشبَّه","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص356، تحت «تعيين المسند إلى المبني للمفعول ودلالته».","url":""}]},{"id":"s4-405","number":405,"surah":4,"verses":[157],"references":[{"surah":4,"verses":[157]}],"verseLabel":"النساء: 157","question":"ما سرّ جعل ﴿اتباع الظن﴾ استثناءً في قوله تعالى: ﴿ما لهم به من علم إلا اتباع الظن﴾؟","answer":"على توجيه الاستثناء المنقطع، نُفي عنهم العلم، ثم بيّن أنهم يتبعون الظن؛ لأن الظن غير العلم. وتذكر الموسوعة أيضًا توجيه الاتصال بالنظر إلى شمول الاسم لهما على سبيل التجوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص357–358، تحت «دلالة النفي والاستثناء في قوله: ﴿ما لهم به من علم إلا اتباع الظن﴾».","url":""}]},{"id":"s4-406","number":406,"surah":4,"verses":[158],"references":[{"surah":4,"verses":[158]}],"verseLabel":"النساء: 158","question":"ما دلالة الإضراب في قوله تعالى: ﴿بل رفعه الله إليه﴾ بعد نفي القتل والصلب؟","answer":"انتقل الإضراب من إبطال روايتهم إلى إثبات الحقيقة المقابلة المشرفة: لم يظفروا به، بل رفعه الله إليه؛ وإظهار اسم الله يقرر أن النجاة والرفع بقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص359–360، تحت «بلاغة الإضراب في رفع عيسى».","url":""}]},{"id":"s4-407","number":407,"surah":4,"verses":[159],"references":[{"surah":4,"verses":[159]}],"verseLabel":"النساء: 159","question":"ما دلالة بناء التوكيد في قوله تعالى: ﴿وإن من أهل الكتاب إلا ليؤمنن به قبل موته﴾؟","answer":"البناء يجمع النفي والاستثناء والقسم ولامه ونون التوكيد، فيحصر ويؤكد أن كل واحد من أهل الكتاب سيؤمن بعيسى قبل الموت، مع تحريضهم على الإيمان النافع قبل الاضطرار إليه","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص360–361، تحت «بلاغة القصر بالنفي والاستثناء».","url":""}]},{"id":"s4-408","number":408,"surah":4,"verses":[159],"references":[{"surah":4,"verses":[159]}],"verseLabel":"النساء: 159","question":"ما دلالة عدم ذكر المشهود به في قوله تعالى: ﴿ويوم القيامة يكون عليهم شهيدًا﴾؟","answer":"حذف معمول «شهيدًا» يعمم شهادته عليهم في صغير أعمالهم وكبيرها، مع تقديم «يوم القيامة» و«عليهم» للتخصيص","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص362، تحت «بلاغة التقديم في قوله: ﴿ويوم القيامة يكون عليهم شهيدًا﴾».","url":""}]},{"id":"s4-409","number":409,"surah":4,"verses":[160],"references":[{"surah":4,"verses":[160]}],"verseLabel":"النساء: 160","question":"ما سرّ تقديم سبب التحريم في قوله تعالى: ﴿فبظلم من الذين هادوا حرمنا عليهم طيبات﴾؟","answer":"قدم سبب العقوبة «فبظلم» على مسببها «حرمنا» للتنبيه إلى فحش الظلم وتقبيحه والتحذير منه، ويفيد التركيب حصر سبب التحريم في ظلمهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص366، تحت «نكتة تقديم الجار والمجرور في قوله: ﴿فبظلم﴾».","url":""}]},{"id":"s4-410","number":410,"surah":4,"verses":[160],"references":[{"surah":4,"verses":[160]}],"verseLabel":"النساء: 160","question":"ما دلالة وصف المحرمات بأنها ﴿طيبات أحلت لهم﴾؟","answer":"وصفها بأنها «طيبات أُحلت لهم» يقرر أنها كانت حلالًا طيبة في أصلها ثم حُرمت عليهم عقوبةً لظلمهم، لا لخبث ذاتي فيها؛ وفي ذلك تغليظ للحرمان وكشف لافترائهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص365، 367–368، تحت «سر ذكر الطيبات هنا مجملة وفي سورة الأنعام مفصلة».","url":""}]},{"id":"s4-411","number":411,"surah":4,"verses":[161],"references":[{"surah":4,"verses":[161]}],"verseLabel":"النساء: 161","question":"ما دلالة الجمع بين أخذ الربا وأكل أموال الناس بالباطل؟","answer":"أخذ الربا صورة مخصوصة من المال المحرم مع سبق النهي عنها، ثم «أكل أموال الناس بالباطل» يعم الرشوة والنصب والاحتيال والغش؛ والجمع ينتقل من بعض المال إلى أبلغ الاعتداء المالي، لا مجرد استيعاب مترادفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص365، 369، تحت «سر الترتيب في أنواع الظلم المذكور».","url":""}]},{"id":"s4-412","number":412,"surah":4,"verses":[162],"references":[{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الراسخون في العلم منهم﴾ بعد ذم أهل الكتاب؟","answer":"الاستدراك يرفع توهم شمول الذم والعذاب كل أهل الكتاب، فيستثني الراسخين المؤمنين منهم، ويقابل بين الكفر وعذابه والإيمان وأجره","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص371، تحت «حسن الاستدراك في قوله: ﴿لكن الراسخون في العلم﴾».","url":""}]},{"id":"s4-413","number":413,"surah":4,"verses":[162],"references":[{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162","question":"لماذا خُصت إقامة الصلاة وإيتاء الزكاة بالذكر بين أوصاف المؤمنين في هذه الآية؟","answer":"لأن الصلاة أشرف الطاعات البدنية، والزكاة أشرف الطاعات المالية؛ فجمعهما يبرز الإخلاص لله والإحسان إلى عباده، ويصل الإيمان بأثره في العبادة والبذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص372، تحت «علة تخصيص عبادتي الصلاة والزكاة بالذكر».","url":""}]},{"id":"s4-414","number":414,"surah":4,"verses":[162],"references":[{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162","question":"ما سرّ نصب ﴿والمقيمين الصلاة﴾ في قراءة المصحف مع عطف الصفات قبلها وبعدها؟","answer":"النصب على المدح والاختصاص يقطع النسق ليلفت إلى منزلة الصلاة؛ كأن المعنى: وأخص بالمدح المقيمين الصلاة، وليس في التركيب خطأ نحوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص372، تحت «نكتة تخصيص المقيمين الصلاة بالذكر».","url":""}]},{"id":"s4-415","number":415,"surah":4,"verses":[162],"references":[{"surah":3,"verses":[7]},{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162؛ آل عمران: 7","question":"ما الفرق السياقي بين ﴿الرَّاسِخُونَ فِي الْعِلْمِ﴾ في النساء، و﴿الرَّاسِخُونَ فِي الْعِلْمِ﴾ في آل عمران؟","answer":"ذكرت آل عمران الراسخين في العلم إجمالًا بوصف إيمانهم بالكتاب محكمه ومتشابهه: ﴿آمنا به كل من عند ربنا﴾. ثم فصلت النساء صفاتهم، فذكرت إيمانهم بما أُنزل إلى النبي وما أُنزل من قبله، وإقامة الصلاة وإيتاء الزكاة والإيمان بالله واليوم الآخر. فبين الموضعين إجمال ثم تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص554–555، تحت عنوان «المناسبات بين سورة النساء والسور المجاورة والمشابهة لها»","url":""}]},{"id":"s4-416","number":416,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما سرّ التعبير بقوله تعالى: ﴿إنا أوحينا إليك﴾، دون: أرسلناك؟","answer":"اختير «أوحينا» لأن الوحي إعلام إلهي خفي سريع وهو أعم من الإرسال، ولأن المقام يرد على مطالبتهم بكتاب من السماء بإثبات أن محمدًا تلقى الوحي كسائر النبيين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص374، 376–377، تحت «إيثار استعمال الفعل ﴿أوحينا﴾ عوضًا عن الفعل (أرسلنا)».","url":""}]},{"id":"s4-417","number":417,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما دلالة تشبيه الوحي إلى محمد ﷺ بالوحي إلى نوح والنبيين من بعده؟","answer":"التشبيه يثبت أن وحي محمد ﷺ من جنس الوحي إلى نوح والنبيين، مع اختلاف صوره والمُوحى به، فيرد إنكار أهل الكتاب ويقيم الدليل على نبوته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–379، تحت «بلاغة التشبيه للوحي إليه، بالوحي للنبيين مع اختلاف أزمانهم».","url":""}]},{"id":"s4-418","number":418,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما مناسبة البدء بنوح عليه السلام في سلسلة الأنبياء هنا؟","answer":"تذكر الموسوعة في تقديم نوح أنه أول أنبياء الشريعة وأول أولي العزم، وأنه أبو البشرية الثاني؛ كما تذكّر بطول صبره على أذى قومه وما انتهى إليه أمر المكذبين، تسلية للنبي ﷺ وتهديدًا للمعاندين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–379، تحت «سر البدء بنوح ﷺ قبل سائر الأنبياء العظام».","url":""}]},{"id":"s4-419","number":419,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما دلالة التعبير بقوله تعالى: ﴿كما أوحينا﴾؟","answer":"شبّه الوحي إلى النبي ﷺ بالوحي إلى الأنبياء قبله لإثبات اشتراكه معهم في أصل الوحي والرسالة ورد إنكار المنكرين. ولا تقتضي الكاف اتحاد صور الوحي وكيفياته في جميع الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–379، تحت «دلالة اختيار حرف (الكاف) في قوله: ﴿كما أوحينا﴾ دون لفظ (مثل)».","url":""}]},{"id":"s4-420","number":420,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما دلالة إجمال ﴿النبيين من بعده﴾ ثم تفصيل أسماء عدد منهم؟","answer":"أجمل النبيين أولًا لاستيعاب الجنس، ثم خص بعض المشهورين العالي المقام عند أهل الكتاب بأسمائهم تسليةً للنبي وعطفًا للخاص على العام، مع تقرير شرف وحيهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص381، تحت «سر ذكر بعض الأنبياء بأسمائهم بعد ذكرهم إجمالًا».","url":""}]},{"id":"s4-421","number":421,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما سرّ تقديم عيسى على أيوب عليهما السلام مع تقدم أيوب زمنًا؟","answer":"قدم عيسى ردًا على اليهود الذين كفروا به وتحقيقًا لنبوته، ولأنه محور جدل واسع وأشهر وأعظم أتباعًا من أيوب ومن بعده، لا لمجرد العناية العامة أو ترتيب زمني","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص382، تحت «دلالة تقديم (عيسى) على (أيوب)، مع تقدمه في الزمان عليه».","url":""}]},{"id":"s4-422","number":422,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]}],"verseLabel":"النساء: 163","question":"ما سرّ العدول من ﴿أوحينا﴾ إلى ﴿وآتينا داود زبورًا﴾؟","answer":"«آتينا داود زبورًا» تخصص بعد عموم الإيحاء بإيتاء الكتاب، وتجعل إيتاء الزبور نظير إيتاء القرآن مع دخولها في حكم الوحي السابق","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص383، تحت «دلالة التعبير بقوله: ﴿وآتينا﴾ دون قوله: (أوحينا)».","url":""}]},{"id":"s4-423","number":423,"surah":4,"verses":[163],"references":[{"surah":4,"verses":[163]},{"surah":6,"verses":[84,85,86]}],"verseLabel":"النساء: 163؛ الأنعام: 84–86","question":"ما سرّ اختلاف ترتيب أسماء الأنبياء في النساء: 163 عن ترتيبهم في الأنعام: 84–86؟","answer":"في النساء رتب الأنبياء بحسب تنوع الوحي والكتب والصحف ووجوه التكريم ردًا على طالبي كتاب من السماء، وفي الأنعام جاءوا في سياق نعم الله على إبراهيم وجُمعت أزواجهم بحسب صفات مشتركة","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص144؛ إسلام ويب، باب النساء: 163","url":""}]},{"id":"s4-424","number":424,"surah":4,"verses":[164],"references":[{"surah":4,"verses":[164]}],"verseLabel":"النساء: 164","question":"ما دلالة تكرار ﴿رسلًا﴾ في قوله تعالى: ﴿ورسلًا قد قصصناهم عليك من قبل ورسلًا لم نقصصهم عليك﴾؟","answer":"تكرار «رسلًا» يقابل فريقين مستقلين: من قصهم الله ومن لم يقصصهم، ويؤكد أن المذكورين سابقًا ليسوا العدد الكلي؛ كما يصنع طباق السلب بين الإثبات والنفي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص386، 391، تحت «سر الجمع بين الإثبات والنفي فيما قص وما لم يقصص».","url":""}]},{"id":"s4-425","number":425,"surah":4,"verses":[164],"references":[{"surah":4,"verses":[164]}],"verseLabel":"النساء: 164","question":"ما دلالة ﴿لم﴾ في قوله تعالى: ﴿ورسلاً لم نقصصهم عليك﴾؟","answer":"«لم» تنفي القص في الزمن الماضي ولا تستلزم نفيه مطلقًا أو مؤبدًا، فيمكن أن يقصهم بعد ذلك أو يعلّم عددهم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص391–392، تحت «دلالة التعبير بـ(لم) دون (لن) في قوله: ﴿لم نقصصهم عليك﴾».","url":""}]},{"id":"s4-426","number":426,"surah":4,"verses":[164],"references":[{"surah":4,"verses":[164]}],"verseLabel":"النساء: 164","question":"ما سرّ الجمع بين الفعل والمصدر في قوله تعالى: ﴿وكلم الله موسى تكليمًا﴾؟","answer":"المصدر المؤكد يثبت حقيقة التكليم وينفي حمل الفعل على مجرد الإلهام أو المجاز، فخص موسى بهذه المنقبة في سياق تنوع صور الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص392–393، تحت «دلالة الإتيان بالمصدر في قوله تعالى: ﴿وكلم الله موسى تكليمًا﴾».","url":""}]},{"id":"s4-427","number":427,"surah":4,"verses":[165],"references":[{"surah":4,"verses":[165]}],"verseLabel":"النساء: 165","question":"ما مناسبة تقديم التبشير على الإنذار في قوله تعالى: ﴿رسلًا مبشرين ومنذرين﴾؟","answer":"قُدمت البشارة لأنها أقرب إلى فتح القلب ودعوته إلى القبول، ثم جاء الإنذار لمن أعرض؛ فجمع إرسالهم الترغيب والترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص395، تحت «دلالة تقديم مبشرين على منذرين في قوله: ﴿رسلًا مبشرين ومنذرين﴾».","url":""}]},{"id":"s4-429","number":429,"surah":4,"verses":[165],"references":[{"surah":4,"verses":[165]}],"verseLabel":"النساء: 165","question":"ما سرّ التعبير بقوله تعالى: ﴿لئلا يكون للناس على الله حجة﴾، دون: احتجاج؟","answer":"الحجة هي الدليل الذي يثبت المقصود، أما الاحتجاج فقد يكون بحجة أو بمغالطة؛ فإرسال الرسل يقطع الحجة والعذر عن الناس، وإن ظل المبطل يجادل ويحتج بما لا يصح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص396–397، تحت «دلالة التعبير بلفظ ﴿حجة﴾ دون لفظ (احتجاج)».","url":""}]},{"id":"s4-430","number":430,"surah":4,"verses":[165],"references":[{"surah":4,"verses":[165]}],"verseLabel":"النساء: 165","question":"ما دلالة قوله تعالى: ﴿بعد الرسل﴾ من غير ﴿من﴾؟","answer":"حذف «من» واختيار الظرف «بعد الرسل» يستغرق نفي الحجة في جميع الزمن اللاحق لإرسال الرسل وتبليغهم، لا مجرد ابتداء زمن بعدها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص398، تحت «سر التعبير بالظرف (بعد)، دون الجار في (من بعد)».","url":""}]},{"id":"s4-431","number":431,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الله يشهد بما أنزل إليك﴾؟","answer":"«لكن» تستدرك على إنكار أهل الكتاب نزول القرآن ورفض شهادتهم للنبي: إن كذبوا فالله يشهد بإنزاله، وإظهار اسم الجلالة يزجر المعاندين ويثبت المؤمنين","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص401–402، تحت «دلالة الابتداء بالاستدراك في قوله: ﴿لكن الله يشهد بما أنزل إليك﴾».","url":""}]},{"id":"s4-432","number":432,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما سرّ التعبير بقوله تعالى: ﴿بما أنزل إليك﴾، دون: بما أوحى إليك؟","answer":"اختير الإنزال لأن المقام مقام الرد على من طلبوا كتابًا من السماء؛ فناسب التصريح بأن القرآن كتاب أنزله الله إلى رسوله، أما الوحي فأعم من إنزال الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص404، تحت «دلالة العدول من الإيحاء إلى الإنزال في قوله: ﴿بما أنزل إليك﴾».","url":""}]},{"id":"s4-433","number":433,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما دلالة اقتران إنزال القرآن بالعلم، في قوله: ﴿أنزله بعلمه﴾؟","answer":"«أنزله بعلمه» أي أنزله بعلم تام وحكمة بالغة، عالمًا بأهلية الرسول وبحاجة البشر، وجعل كمال علمه آلة لإحكام القرآن وبلوغه غاية الإعجاز مع حفظه من الخلل والزيادة والنقص","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص404–406، تحت «دلالة اقتران إنزال القرآن بالعلم، في قوله: ﴿أنزله بعلمه﴾».","url":""}]},{"id":"s4-434","number":434,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما دلالة إفراد شهادة الله ثم عطف قوله تعالى: ﴿والملائكة يشهدون﴾؟","answer":"أفرد شهادة الله لأنها الأصل الكافي، ثم عطف شهادة الملائكة لزيادة التقرير بتعدد الشهود وبيان عظم المشهود عليه؛ وشهادتهم تبع لشهادته لا تزكية لها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص406–407، 409، تحت «دلالة عطف شهادة الملائكة على شهادة الله في قوله: ﴿والملائكة يشهدون﴾».","url":""}]},{"id":"s4-435","number":435,"surah":4,"verses":[166],"references":[{"surah":4,"verses":[166]}],"verseLabel":"النساء: 166","question":"ما سرّ التعبير بقوله تعالى: ﴿وكفى بالله شهيدًا﴾، دون: شاهدًا؟","answer":"﴿شهيد﴾ صيغة مبالغة تدل على كمال العلم والحضور وإقامة الحجة، والباء في هذا الأسلوب تؤكد كفاية شهادة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص400، 408–409، تحت «سر التعبير بـ﴿شهيدًا﴾ دون شاهد في قوله: ﴿وكفى بالله شهيدًا﴾».","url":""}]},{"id":"s4-436","number":436,"surah":4,"verses":[167],"references":[{"surah":4,"verses":[167]}],"verseLabel":"النساء: 167","question":"ما دلالة الجمع بين الكفر والصد عن سبيل الله؟","answer":"لم يقتصروا على الكفر في أنفسهم، بل ضموا إليه منع غيرهم من الإيمان وصرفه عن سبيل الله؛ فجمع الوصفين يبين اجتماع الضلال والإضلال فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص413–414، تحت «دلالة الجمع بين الكفر والصد في الآية الكريمة».","url":""}]},{"id":"s4-437","number":437,"surah":4,"verses":[167],"references":[{"surah":4,"verses":[167]}],"verseLabel":"النساء: 167","question":"ما سرّ التعبير بقوله تعالى: ﴿وصدوا عن سبيل الله﴾، دون: ومنعوا الناس؟","answer":"الصد يجمع إعراضهم بأنفسهم وصرفهم غيرهم، و﴿سبيل الله﴾ تصور الدين طريقًا موصلًا إليه؛ فجريمتهم ليست منع أشخاص فحسب، بل إقامة العوائق في طريق الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص411، 413، 415، تحت «دلالة التعبير بالصد دون المنع في قوله: ﴿وصدوا عن سبيل الله﴾».","url":""}]},{"id":"s4-438","number":438,"surah":4,"verses":[167],"references":[{"surah":4,"verses":[167]}],"verseLabel":"النساء: 167","question":"ما دلالة قوله تعالى: ﴿قد ضلوا ضلالًا بعيدًا﴾ بعد الكفر والصد؟","answer":"حققت ﴿قد﴾ وقوع الضلال، وأكده المصدر، ووصفه بالبعد لأنهم لم يكتفوا بالانحراف بل صدوا غيرهم؛ فصار الرجوع أبعد مع تراكم الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص414–416، تحت «دلالة الضلال البعيد في قوله: ﴿قد ضلوا ضلالًا بعيدًا﴾».","url":""}]},{"id":"s4-439","number":439,"surah":4,"verses":[168,169],"references":[{"surah":4,"verses":[168,169]}],"verseLabel":"النساء: 168–169","question":"ما دلالة الجمع بين ﴿كفروا وظلموا﴾ مع أن الكفر أعظم الظلم؟","answer":"الكفر يحدد فساد الاعتقاد، والظلم يشمل ما انضم إليه من تعد على الرسل والناس وصد عن الحق؛ فذكر الظلم لإظهار الجرائم العملية المترتبة على كفرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص418–419، تحت «دلالة الجمع بين الكفر والظلم في قوله تعالى: ﴿إن الذين كفروا وظلموا﴾».","url":""}]},{"id":"s4-440","number":440,"surah":4,"verses":[168],"references":[{"surah":4,"verses":[168]}],"verseLabel":"النساء: 168","question":"ما سرّ التعبير بقوله تعالى: ﴿لم يكن الله ليغفر لهم﴾، دون: لن يغفر لهم؟","answer":"لام الجحود بعد ﴿لم يكن﴾ تنفي ملاءمة المغفرة لحال من استقر على الكفر والظلم، فهي أبلغ من خبر مستقبل مجرد؛ والتوبة تخرجه من هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص419–420، تحت «دلالة صيغة الجحود في قوله: ﴿لم يكن الله ليغفر لهم﴾».","url":""}]},{"id":"s4-441","number":441,"surah":4,"verses":[168,169],"references":[{"surah":4,"verses":[168,169]}],"verseLabel":"النساء: 168–169","question":"كيف تُفهم الهداية في قوله تعالى: ﴿ولا ليهديهم طريقًا إلا طريق جهنم﴾؟","answer":"استُعملت الهداية مع طريق جهنم على المشاكلة والتهكم؛ فهي ليست هداية إلى الخير، بل تعبير عن إفضاء سوء اختيارهم إلى طريق جهنم","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص423، تحت «دلالة اختيار الفعل المنفي ﴿ولا ليهديهم طريقًا﴾».","url":""}]},{"id":"s4-442","number":442,"surah":4,"verses":[169],"references":[{"surah":4,"verses":[169]},{"surah":5,"verses":[119]},{"surah":9,"verses":[22]}],"verseLabel":"النساء: 169؛ المائدة: 119؛ التوبة: 22","question":"ما دلالة الجمع بين ﴿خالدين فيها﴾ و﴿أبدًا﴾؟","answer":"في النساء: 169: الخلود يدل على طول المكث أو دوامه بحسب السياق، وجاءت ﴿أبدًا﴾ لتقطع احتمال النهاية وتؤكد أن بقاءهم في جهنم لا ينقضي.\n\nفي المائدة: 119: ﴿خالدين فيها﴾ تثبت دوام إقامتهم في الجنات، و﴿أبدًا﴾ تؤكد امتداد هذا الخلود بلا نهاية ولا انقطاع؛ فدفعت كل توهم لمفارقة المكان أو انتهاء الزمن.\n\nفي التوبة: 22: ﴿خالدين﴾ تثبت طول الإقامة، و﴿أبدًا﴾ تنفي أن يكون لها نهاية مهما امتد الزمن؛ فالثاني يقطع كل احتمال للانقطاع.","sources":[{"label":"[النساء: 169] موسوعة التفسير البلاغي، ج8، ص423، تحت «دلالة ذكر لفظ ﴿أبدًا﴾ في قوله: ﴿خالدين فيها أبدًا﴾».","url":""},{"label":"[المائدة: 119] موسوعة التفسير البلاغي، ج10، ص160–175","url":""},{"label":"[التوبة: 22] موسوعة التفسير البلاغي، ج16، ص792–795","url":""}]},{"id":"s4-443","number":443,"surah":4,"verses":[169],"references":[{"surah":4,"verses":[169]}],"verseLabel":"النساء: 169","question":"ما دلالة تنكير ﴿طريقًا﴾ ثم استثناء ﴿طريق جهنم﴾ في قوله تعالى: ﴿ولا ليهديهم طريقًا إلا طريق جهنم﴾؟","answer":"نُكّر الطريق أولًا لنفي هدايتهم إلى طريق خير، ثم عُيّن طريق جهنم في الاستثناء فقُصر مصيرهم عليه؛ وانتقل اللفظ من العموم في النفي إلى تعيين الطريق المستثنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص422، تحت «بلاغة القصر في الآية في قوله تعالى: ﴿إلا طريق جهنم﴾».","url":""}]},{"id":"s4-444","number":444,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما سرّ افتتاح الدعوة بقوله تعالى: ﴿يا أيها الناس﴾، دون تخصيص أهل الكتاب أو المؤمنين؟","answer":"النداء بالناس يعمم الدعوة إلى الإيمان بالرسول بعد قيام الحجة؛ فلا تختص بأهل الكتاب، بل تشملهم وتشمل غيرهم، بما يناسب عموم الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص427–428، تحت «دلالة التعبير بلفظ ﴿الناس﴾ في قوله: ﴿يا أيها الناس﴾».","url":""}]},{"id":"s4-445","number":445,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما دلالة تعريف الرسول في قوله تعالى: ﴿قد جاءكم الرسول بالحق﴾؟","answer":"التعريف للعهد والعلم بالرسول؛ فقد بُشر به أهل الكتاب وكانوا ينتظرون بعثته. وفي اختياره بهذا الوصف تأكيد وجوب طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص428، تحت «دلالة التعريف في لفظ ﴿الرسول﴾ في قوله: ﴿قد جاءكم الرسول﴾».","url":""}]},{"id":"s4-446","number":446,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما دلالة تقييد الحق بقوله تعالى: ﴿من ربكم﴾؟","answer":"وصف الحق بأنه «من ربكم» يستحضر الربوبية والتربية، ويرغب المخاطبين في التصديق بما جاء به الرسول","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص429، تحت «دلالة التعبير بلفظ الربوبية في قوله ﴿من ربكم﴾»","url":""}]},{"id":"s4-447","number":447,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما سرّ نصب ﴿خيرًا﴾ في قوله تعالى: ﴿فآمنوا خيرًا لكم﴾ من غير فعل ظاهر؟","answer":"أوجز الحذف وكثّر المعنى؛ فمن توجيهاته: فآمنوا يكن الإيمان خيرًا لكم، أو ائتوا إيمانًا خيرًا لكم. وفي كل وجه حث على الإيمان وبيان عاقبته النافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص430، تحت «ثمرة تنوع الأوجه الإعرابية في السياق الواحد».","url":""}]},{"id":"s4-448","number":448,"surah":4,"verses":[170],"references":[{"surah":4,"verses":[170]}],"verseLabel":"النساء: 170","question":"ما دلالة حذف جواب الشرط في قوله تعالى: ﴿وإن تكفروا فإن لله ما في السماوات والأرض﴾؟","answer":"دل تقرير الملك على الجواب المحذوف: فإن تكفروا فالله غني عنكم وعن إيمانكم وقادر على جزائكم؛ فتركه ليستنبط السامع من عموم الملك تهديدًا أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص430، تحت «دلالة حذف جواب الشرط في قوله تعالى: ﴿وإن تكفروا﴾».","url":""}]},{"id":"s4-449","number":449,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما مناسبة الانتقال من خطاب الناس جميعًا إلى قوله تعالى: ﴿يا أهل الكتاب﴾؟","answer":"انتقل السياق إلى معالجة غلو النصارى في عيسى، بعد عرض انحراف اليهود في شأنه؛ والمراد بأهل الكتاب هنا النصارى بقرينة النهي عن قول ثلاثة. ففي الخطاب رد على هذه المقالة وتذكير لهم بكتابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص433، 435، تحت «إطلاق العام وإرادة الخاص في الآية».","url":""}]},{"id":"s4-450","number":450,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما الصورة في النهي بقوله تعالى: ﴿لا تغلوا في دينكم﴾؟","answer":"استعير الغلو، وهو مجاوزة الحد والارتفاع، للزيادة في الدين على ما شرعه الله؛ فصور الإفراط خروجًا عن الحد المرسوم، كما يرتفع الماء في غليانه أو يتجاوز السهم غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص433، 435، تحت «دلالة الاستعارة في قوله: ﴿لا تغلوا في دينكم﴾».","url":""}]},{"id":"s4-451","number":451,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما دلالة الجمع بين النهي عن الغلو والنهي عن القول على الله بغير الحق؟","answer":"الغلو أصل عام لكثير من الضلال، ثم خُص القول على الله بالباطل لعظم جريمة الافتراء التي نتج عنها تأليه المسيح؛ فهو عطف خاص على عام للاهتمام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص435، تحت «دلالة الاستعارة في قوله: ﴿لا تغلوا في دينكم﴾».","url":""}]},{"id":"s4-452","number":452,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما دلالة وصف عيسى عليه السلام بأنه ﴿كلمته ألقاها إلى مريم وروح منه﴾؟","answer":"هو كلمة الله بمعنى أنه خُلق بكلمة ﴿كن﴾ من غير أب، وروح مخلوقة صادرة من عنده تشريفًا، لا جزءًا من ذاته؛ فالعبارتان تثبتان معجزة خلقه ولا تدلان على ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص438–440، تحت «الدلالة البلاغية لتعدد الصفات لعيسى بن مريم هنا».","url":""}]},{"id":"s4-453","number":453,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما معنى إلقاء الكلمة إلى مريم في قوله تعالى: ﴿وكلمته ألقاها إلى مريم﴾؟","answer":"فسرت الموسوعة إلقاء الكلمة إلى مريم بإعلامها بها وإخبارها أو إنزالها إليها؛ فالمعنى تبليغها أمر الله الذي خُلق به عيسى، لا إلقاء شيء حسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص438، تحت «إضافة (الكلمة) إلى الله، وتأخرها عن وصف الرسالة، في قوله: ﴿رسول الله وكلمته﴾».","url":""}]},{"id":"s4-454","number":454,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما سرّ الإيجاز في قوله تعالى: ﴿ولا تقولوا ثلاثة﴾، دون تفصيل صورة التثليث؟","answer":"في «ثلاثة» إيجاز بحذف المبتدأ؛ فالنهي يتناول مقالتهم في التثليث مع اختلافهم في تفسيرها. وعدم تعيين المبتدأ يتيح حمل الكلام على تقديرات تناسب صور زعمهم المختلفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص440–441، تحت «الفاء الفصيحة وأسلوب الاحتراس يجليان الأمر بالإيمان النقي من كل زعم فاسد».","url":""}]},{"id":"s4-455","number":455,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما سرّ نصب ﴿خيرًا﴾ في قوله تعالى: ﴿انتهوا خيرًا لكم﴾؟","answer":"التقدير: انتهوا يكن الانتهاء خيرًا لكم، أو ائتوا أمرًا خيرًا لكم؛ فحذف العامل للإيجاز، وجعل النهي عن التثليث موصولًا مباشرة بعاقبته النافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص430، 441، تحت «ثمرة تنوع الأوجه الإعرابية في السياق الواحد».","url":""}]},{"id":"s4-456","number":456,"surah":4,"verses":[172],"references":[{"surah":4,"verses":[172]}],"verseLabel":"النساء: 172","question":"ما سرّ التعبير بقوله تعالى: ﴿لن يستنكف المسيح أن يكون عبدًا لله﴾، دون: لن يستكبر؟","answer":"الاستنكاف امتناع ناشئ من أنفة؛ فهو أدق في نفي أن يأنف المسيح من العبودية، ثم ذكر الاستكبار بعده لوعيد من يتعالى عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص443–444، 450–451، تحت «الاستنكاف والاستكبار».","url":""}]},{"id":"s4-457","number":457,"surah":4,"verses":[172],"references":[{"surah":4,"verses":[172]}],"verseLabel":"النساء: 172","question":"ما مناسبة عطف الملائكة المقربين على المسيح في مقام نفي الاستنكاف؟","answer":"ذُكر المسيح والملائكة ممن غلا فيهم بعض البشر؛ فإذا لم يأنف هؤلاء المقربون من عبودية الله فغيرهم أولى، وفي الجمع إبطال لتأليه المسيح والملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص445–446، تحت عنوان «عطف الملائكة على المسيح؛ لأنهم قيل عنهم أبناء الله، وكذلك المسيح»","url":""}]},{"id":"s4-458","number":458,"surah":4,"verses":[172],"references":[{"surah":4,"verses":[172]}],"verseLabel":"النساء: 172","question":"ما دلالة وصف الملائكة بـ﴿المقربين﴾ في هذا السياق؟","answer":"خُص المقربون لعلو درجتهم ومنزلتهم؛ ومع هذه الرفعة لا يستنكفون عن عبادة الله. فالقرب منه لا يُخرج المخلوق عن العبودية له.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص445–446، تحت عنوان «عطف الملائكة على المسيح؛ لأنهم قيل عنهم أبناء الله، وكذلك المسيح»","url":""}]},{"id":"s4-459","number":459,"surah":4,"verses":[172,173],"references":[{"surah":4,"verses":[172,173]}],"verseLabel":"النساء: 172–173","question":"ما دلالة الجمع بين الاستنكاف والاستكبار في الوعيد؟","answer":"الاستنكاف امتناع ناشئ عن أنفة وتصور نقص، أما الاستكبار فطلب الكبر والترفع، والجمع يستوعب صور الامتناع عن عبادة الله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص450، تحت «الاستنكاف والاستكبار»","url":""}]},{"id":"s4-460","number":460,"surah":4,"verses":[174],"references":[{"surah":4,"verses":[174]}],"verseLabel":"النساء: 174","question":"ما دلالة إضافة البرهان إلى الرب في قوله تعالى: ﴿قد جاءكم برهان من ربكم﴾؟","answer":"إضافته إلى الرب تقوي دلالته؛ فما جاء من عند الله برهان صادق مقنع لطالب الحق. وفي إضافة الرب إلى المخاطبين تذكير بتربيته لهم وتبليغهم كمالهم اللائق بهم، وترغيب في امتثال أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص454–455، تحت عنوان «ذكر الربوبية في قوله تعالى: ﴿من ربكم﴾ فيه تقوية لمعنى البرهان»","url":""}]},{"id":"s4-475","number":475,"surah":4,"verses":[174],"references":[{"surah":4,"verses":[174]}],"verseLabel":"النساء: 174","question":"لماذا سُمّي القرآن ﴿نورًا مبينًا﴾؟","answer":"سُمّي نورًا لأن الأحكام تتبين به كما تتبين الأشياء بالنور، ولأنه سبب لوقوع نور الإيمان في القلب؛ ووصفه بأنه مبين يدل على وضوحه وإيضاحه لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص455، تحت عنوان «من أسرار القرآن أن برهانه يؤثر في السامع، ولو كان لا يجيد العربية»","url":""}]},{"id":"s4-461","number":461,"surah":4,"verses":[175],"references":[{"surah":4,"verses":[175]}],"verseLabel":"النساء: 175","question":"ما دلالة الجمع بين الإيمان بالله والاعتصام به؟","answer":"جمع بين الإيمان بالله والتمسك بدينه؛ فالاعتصام يتضمن طلب ما يحفظ صاحبه، وصيغته تدل على الاجتهاد في ذلك. فليس المقصود التصديق وحده، بل ملازمة الدين والاجتهاد في الالتزام به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص455–456، تحت عنوان «الاعتصام بالله استعارة للالتزام بدينه»","url":""}]},{"id":"s4-462","number":462,"surah":4,"verses":[175],"references":[{"surah":4,"verses":[175]}],"verseLabel":"النساء: 175","question":"ما دلالة ترتيب قوله تعالى: ﴿فسيدخلهم في رحمة منه وفضل ويهديهم إليه صراطًا مستقيمًا﴾؟","answer":"وعدهم بالرحمة وهي الجنة، ثم بالفضل وهو الزيادة في الثواب، ثم بالهداية إلى الصراط المستقيم؛ وقد قُدّم الوعد بدخول الجنة على الهداية إليها للمسارعة إلى التبشير بالمقصد الأصلي","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص457–458، تحت «الضمير في قوله ﴿إليه﴾ عائد على الله تعالى، وذلك على حذف مضاف».","url":""}]},{"id":"s4-463","number":463,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما مناسبة ختم السورة بمسألة الكلالة بعد افتتاحها بأحكام الأسرة والمواريث؟","answer":"خُتمت السورة بأحكام الأموال والميراث كما افتُتحت بها، فتحقق التوافق بين البداية والخاتمة. وفي توزيع أحكام الفرائض على أول السورة وأثنائها وآخرها إظهار لشدة الاهتمام بها وتدرج في عرضها يعين على قبولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص473، تحت عنوان «حكمة تأخير آية الكلالة إلى نهاية السورة؛ لتعلقها بتمام ما سلف»","url":""}]},{"id":"s4-464","number":464,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ حذف متعلق الاستفتاء أولًا ثم إظهاره في قوله تعالى: ﴿يستفتونك قل الله يفتيكم في الكلالة﴾؟","answer":"حُذف متعلق ﴿يستفتونك﴾ لدلالة ﴿يفتيكم في الكلالة﴾ عليه وتجنب التكرار، وأُظهر في جواب الفتوى للعناية بأمر الكلالة وكثرة السؤال عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص463–464، تحت «أثر الإيجاز بالحذف في قوله تعالى: ﴿يستفتونك﴾».","url":""}]},{"id":"s4-465","number":465,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما دلالة التصريح باسم الله في قوله تعالى: ﴿قل الله يفتيكم في الكلالة﴾؟","answer":"صُرّح باسم الله لئلا يُتوهم أن الرسول مصدر الفتوى؛ فالله هو المفتي والمشرع، والرسول مبلّغ حكمه، وفي ذلك توكيد لثبوت الحكم ودوامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص465–466، تحت «سر ورود لفظ الجلالة ﴿الله﴾ في قوله: ﴿قل الله يفتيكم﴾».","url":""}]},{"id":"s4-466","number":466,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ التعبير بقوله تعالى: ﴿إن امرؤ هلك﴾، دون: مات؟","answer":"اختير ﴿هلك﴾ لما فيه من معنى الفناء وانقطاع الأثر؛ فناسب حال الكلالة التي تنقطع فيها ذرية الميت ولا يكون له ولد، بخلاف مجرد الإخبار بالموت","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص467، تحت «سر التعبير بلفظ الهالك في قوله: ﴿إن امرؤ هلك﴾»","url":""}]},{"id":"s4-467","number":467,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ عدم التصريح بالوالد في قوله تعالى: ﴿ليس له ولد وله أخت﴾ مع أن الكلالة تكون بغير والد ولا ولد؟","answer":"اكتفى بانتفاء الولد لأن حكم الأخت المذكور واسم الكلالة يدلان على انتفاء الوالد؛ فلو وجد الأب لم ترث الأخت هذا الفرض، فحذفه إيجاز لدلالة الحكم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص467–468، تحت «سر الاقتصار على نفي الولد، مع أن نفي الوالد معتبر في الكلالة».","url":""}]},{"id":"s4-468","number":468,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ زيادة ﴿اثنتين﴾ في قوله تعالى: ﴿فإن كانتا اثنتين﴾ مع دلالة ألف الاثنين عليها؟","answer":"من توجيهات المصدر أن ألف التثنية قد تدل على اثنين موصوفين بصفة، فجاء العدد «اثنتين» مجردًا من الصفة لتعيين العدد المقصود. ويعرض المصدر كذلك اعتراضًا بأن ضمير التثنية نفسه يدل على العدد، فلا يُذكر التوجيه كأنه خالٍ من الخلاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص469–470، تحت «ما فائدة قوله: ﴿اثنتين﴾ مع أن لفظ ﴿كانتا﴾ لا يفسر إلا بهذا العدد؟».","url":""}]},{"id":"s4-469","number":469,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ التعبير بقوله تعالى: ﴿يبين الله لكم أن تضلوا﴾، دون: لئلا تضلوا؟","answer":"التقدير: يبين الله لكم كراهة أن تضلوا، أو يبين لكم لئلا تضلوا؛ فحذف ما دل عليه مقام البيان، وجاء المصدر المؤول موجزًا في بيان غاية الفتوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص471، تحت «الإيجاز بالحذف، وتعدد تقدير المحذوف، وأثره في المعنى».","url":""}]},{"id":"s4-470","number":470,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما مناسبة ختم السورة بقوله تعالى: ﴿والله بكل شيء عليم﴾؟","answer":"تفاصيل المواريث مبنية على علم محيط بالقرابات والمصالح والعواقب، فتعَلّل الخاتمة الأحكام بعلم الله وتدعو إلى التسليم، كما تستقل بعموم علمه بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص471–472، تحت «التذييل لتعليل الأحكام بقوله تعالى: ﴿والله بكل شيء عليم﴾».","url":""}]},{"id":"s4-471","number":471,"surah":4,"verses":[176],"references":[{"surah":4,"verses":[176]}],"verseLabel":"النساء: 176","question":"ما سرّ بدء فتوى الكلالة بقوله تعالى: ﴿يَسْتَفْتُونَكَ﴾ بلا واو، مع مجيء فتوى النساء قبلها: ﴿وَيَسْتَفْتُونَكَ فِي النِّسَاءِ﴾ بالواو؟","answer":"فتوى الكلالة استئناف مستقل في خاتمة السورة بعد انقضاء السياق السابق، أما فتوى النساء فعُطفت بالواو على أحكام النساء المتصلة قبلها؛ فالحرف يكشف صلة كل سؤال بسياقه.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44175","url":""}]},{"id":"s4-476","number":476,"surah":4,"verses":[1,176],"references":[{"surah":4,"verses":[1,176]}],"verseLabel":"النساء: 1، 176","question":"ما سر التناسب بين فاتحة سورة النساء وخاتمتها؟","answer":"بدأت بخلق الإنسان وبثّ ذريته في الأرض، وانتهت بهلاكه: ﴿إِنِ امْرُؤٌا هَلَكَ لَيْسَ لَهُ وَلَدٌ﴾، فهي صورة لبدء الحياة ونهايتها. وابتدأت بإيتاء اليتامى أموالهم وهم يستقبلون الحياة، واختتمت بتقسيم تركة من ودّع الحياة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص257–258.","url":""}]},{"id":"s4-477","number":477,"surah":4,"verses":[2],"references":[{"surah":4,"verses":[2]}],"verseLabel":"النساء: 2","question":"ما سر التعبير بـ﴿وَلَا تَتَبَدَّلُوا الْخَبِيثَ بِالطَّيِّبِ﴾ بتاءين، مع قوله في الأحزاب: ﴿وَلَا أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَاجٍ﴾ بتاء واحدة؟","answer":"آية الأحزاب حكم مقصور على الرسول ﷺ وحده، فهو منهي عن أن يتبدّل بأزواجه أزواجًا، فحذف من الفعل. أما آية النساء فحكم عام للمسلمين على مر العصور، فجاء بالصيغة الطويلة للحدث الطويل الممتد، وبالصيغة القصيرة للحدث المقصور على شخص واحد.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص11–12.","url":""}]},{"id":"s4-478","number":478,"surah":4,"verses":[69],"references":[{"surah":4,"verses":[69]}],"verseLabel":"النساء: 69","question":"ما سر ترتيب المذكورين في ﴿وَمَن يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَٰئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِم مِّنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ﴾؟","answer":"هو من التقديم بحسب الفضل والشرف، فقدّم اسم الله على الرسول، ثم جعل الصديقين صنفًا بعد الأنبياء، وذكر بعدهم الشهداء، ثم عموم الصالحين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص54. الآيات 71–104","url":""}]},{"id":"s4-479","number":479,"surah":4,"verses":[95],"references":[{"surah":4,"verses":[95]}],"verseLabel":"النساء: 95","question":"ما دلالة النفي بـ«لا» في ﴿لَّا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ وَالْمُجَاهِدُونَ﴾؟","answer":"النفي بـ«لا» هنا لنفي الاستواء في المستقبل، أي في الآخرة، فعدم استواء القاعدين والمجاهدين يظهر أثره يوم الجزاء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج2، ص96.","url":""}]},{"id":"s4-480","number":480,"surah":4,"verses":[107],"references":[{"surah":4,"verses":[107]}],"verseLabel":"النساء: 107","question":"ما سر ختم الآية بـ﴿أَثِيمًا﴾ والتعبير بـ﴿مَن كَانَ﴾، مع قوله في الحج: ﴿إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ﴾؟","answer":"السياق في النساء في الخيانة والآثام، وقد تكرر فيه ذكر الإثم، والخائن أثيم، فناسب الختم بـ«أثيم». وآية الحج حكم عام لعموم المسلمين فجاءت بـ«كل»، أما آية النساء ففي جماعة مخصوصة سرقوا طعامًا ورموا بالسرقة غيرهم، فلم يأت بصيغة العموم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص175–176.","url":""}]},{"id":"s4-481","number":481,"surah":4,"verses":[9],"references":[{"surah":4,"verses":[9]}],"verseLabel":"النساء: 9","question":"ما سر جمع «ضعيف» على «ضِعاف» في ﴿وَلْيَخْشَ الَّذِينَ لَوْ تَرَكُوا مِنْ خَلْفِهِمْ ذُرِّيَّةً ضِعَافًا﴾، وعلى «ضُعفاء» في البقرة: ﴿وَلَهُ ذُرِّيَّةٌ ضُعَفَاءُ﴾؟","answer":"«الضِّعاف» للضعف المادي، والمراد في آية النساء ذرية فقراء محتاجون إلى المال. أما «الضعفاء» فللضعف المعنوي، أي العجز عن القيام بالأمر، بدليل أن أباهم في آية البقرة له جنة فيها من كل الثمرات، وإنما هم محتاجون إلى من يقوم بأمرهم.","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص146–147.","url":""}]},{"id":"s4-482","number":482,"surah":4,"verses":[10],"references":[{"surah":4,"verses":[10]}],"verseLabel":"النساء: 10","question":"ما سر جمع «يتيم» على «اليتامى» دون «الأيتام» في ﴿إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَىٰ ظُلْمًا﴾؟","answer":"بناء «فَعالى» يُجمع عليه ما صار آفة وبلية على أصحابه، فجمعه على «اليتامى» تشنيعًا لفعلة الآكل: فهؤلاء مهضومون أثّر فيهم اليتم حتى صار بلية نازلة بهم، فكيف تطيب نفس بأكل أموالهم ظلمًا؟ أما «الأيتام» فجمع ليس فيه إشارة إلى أثر اليتم عليهم.","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص143.","url":""}]},{"id":"s4-504","number":504,"surah":4,"verses":[10],"references":[{"surah":4,"verses":[10]}],"verseLabel":"النساء: 10","question":"ما سرّ التعبير بـ﴿يَأْكُلُونَ أَمْوَالَ الْيَتَامَى﴾ بدلًا من «يأخذون أموال اليتامى»؟","answer":"عبّر بالأكل لأنه أعمّ وجوه الانتفاع بالمال وأهمّها، وهو أبلغ من مجرد الأخذ؛ فالأكل يصوّر الاستيلاء التام على المال واستهلاكه بحيث لا يُرجى إرجاعه. وفيه تشنيعٌ لفعلهم وتصويرٌ لجشعهم، فضلًا عن مناسبته لقوله بعده: ﴿إِنَّمَا يَأْكُلُونَ فِي بُطُونِهِمْ نَارًا﴾، فكان الجزاء من جنس العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص649، تحت «بلاغة إيثار فعل الأكل»، والعنوان الجزئي «كسوة الباطن أهم أسباب جمع المال».","url":""}]},{"id":"s4-483","number":483,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما سر التعبير بـ«يُوصِيكُمْ» من «أوصى» في ﴿يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ﴾ دون «وصّى»؟","answer":"يستعمل القرآن «وصّى» بالتشديد لأمور الدين والأمور المعنوية لما فيه من المبالغة، ويستعمل «أوصى» للأمور المادية كالمواريث. وهذه الآية في قسمة المواريث فجاء بـ«يوصيكم».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص14؛ بلاغة الكلمة، ص59.","url":""}]},{"id":"s4-484","number":484,"surah":4,"verses":[11],"references":[{"surah":4,"verses":[11]}],"verseLabel":"النساء: 11","question":"ما دلالة «كان» في ﴿فَرِيضَةً مِّنَ اللَّهِ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا﴾؟","answer":"الآية في تشريع أمر لا يعلم البشر حقيقته، إذ قال قبله: ﴿لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا﴾، والمشرّع ينبغي أن يعلم الأمر قبل وقوعه. فلما ذكر جهل الإنسان المستمر جاء بـ«كان» للدلالة على علم الله وحكمته القديمين منذ الأزل.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص215–216.","url":""}]},{"id":"s4-485","number":485,"surah":4,"verses":[17],"references":[{"surah":4,"verses":[17]}],"verseLabel":"النساء: 17","question":"ما دلالة «ثمّ» في ﴿لِلَّذِينَ يَعْمَلُونَ السُّوءَ بِجَهَالَةٍ ثُمَّ يَتُوبُونَ مِن قَرِيبٍ﴾؟","answer":"ليست «ثم» هنا للتراخي في الزمان، وإلا تناقضت مع قوله ﴿مِن قَرِيبٍ﴾، وإنما دخلت لبُعد ما بين الحالين: عمل السوء والتوبة. وفي «الكشاف» نحو هذا في دلالة «ثم» على الاستبعاد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج3، ص242.","url":""}]},{"id":"s4-486","number":486,"surah":4,"verses":[25],"references":[{"surah":4,"verses":[25]}],"verseLabel":"النساء: 25","question":"ما سر ختم آية الإماء بـ﴿وَاللَّهُ غَفُورٌ رَّحِيمٌ﴾ دون توكيد بـ«إنّ»؟","answer":"السياق في إقامة الحد على من يأتي الفاحشة، وليس هذا مقام توكيد المغفرة، بخلاف آية البقرة الواردة في مناسك الحج: ﴿وَاسْتَغْفِرُوا اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ﴾، فهو أولى المقامات بتوكيد المغفرة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص138–139.","url":""}]},{"id":"s4-487","number":487,"surah":4,"verses":[28],"references":[{"surah":4,"verses":[28]}],"verseLabel":"النساء: 28","question":"ما سر بناء الفعل للمجهول في ﴿وَخُلِقَ الْإِنسَانُ ضَعِيفًا﴾؟","answer":"المقام مقام ذكر جانب الضعف من طبيعة البشر، والله لا ينسب الفعل إلى نفسه في مقام الذم، بخلاف مقام المدح والتفضل كقوله: ﴿لَقَدْ خَلَقْنَا الْإِنسَانَ فِي أَحْسَنِ تَقْوِيمٍ﴾. ونظيره ﴿خُلِقَ الْإِنسَانُ مِنْ عَجَلٍ﴾ و﴿إِنَّ الْإِنسَانَ خُلِقَ هَلُوعًا﴾.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص154؛ على طريق التفسير البياني، ج2، ص248.","url":""}]},{"id":"s4-488","number":488,"surah":4,"verses":[36],"references":[{"surah":4,"verses":[36]}],"verseLabel":"النساء: 36","question":"ما سر التوكيد بـ«إنّ» في ﴿إِنَّ اللَّهَ لَا يُحِبُّ مَن كَانَ مُخْتَالًا فَخُورًا﴾، مع تركه في الحديد: ﴿وَاللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ﴾؟","answer":"الكلام في سورة النساء على العلاقات بين الناس وإحسان المعاملة، فقد أمر بالإحسان إلى الوالدين وذي القربى واليتامى والمساكين والجار حتى انتهى إلى ملك اليمين، فناسب التوكيد كما في لقمان. أما آية الحديد فليست في آداب المعاملة ولا في العلاقات بين الناس فلم يؤكد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص332–333.","url":""}]},{"id":"s4-489","number":489,"surah":4,"verses":[59],"references":[{"surah":4,"verses":[59]}],"verseLabel":"النساء: 59","question":"ما سر إفراد الخطاب في ﴿ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾، مع قوله في التوبة: ﴿ذَلِكُمْ خَيْرٌ لَّكُمْ﴾؟","answer":"تأتي الكاف مطابقة للجمع حين يقتضي السياق الإطالة والتوسع، وسياق التوبة في الجهاد ممتد طويل فجاء بـ«ذلكم». وسبب آخر للإفراد في النساء أنه التفت بعدها إلى خطاب المفرد: ﴿أَلَمْ تَرَ إِلَى الَّذِينَ يَزْعُمُونَ﴾، بخلاف آية التوبة فالكلام فيها كله للمخاطبين.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص102.","url":""}]},{"id":"s4-490","number":490,"surah":4,"verses":[61,160],"references":[{"surah":4,"verses":[61,160]}],"verseLabel":"النساء: 61، 160","question":"ما سر التعبير بـ﴿صُدُودًا﴾ في ﴿رَأَيْتَ الْمُنَافِقِينَ يَصُدُّونَ عَنكَ صُدُودًا﴾، وبـ«الصَّدّ» في ﴿وَبِصَدِّهِمْ عَن سَبِيلِ اللَّهِ كَثِيرًا﴾؟","answer":"«الصَّدّ» مصدر الفعل المتعدي وهو بمعنى المنع، فاستعمله في الذين هادوا لأنهم يمنعون عن سبيل الله. أما «الصُّدود» فمصدر الفعل اللازم وهو بمعنى الإعراض، فاستعمله في المنافقين المعرضين عن الرسول ﷺ.","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص21.","url":""}]},{"id":"s4-491","number":491,"surah":4,"verses":[78],"references":[{"surah":4,"verses":[78]}],"verseLabel":"النساء: 78","question":"ما دلالة «أينما» في ﴿أَيْنَمَا تَكُونُوا يُدْرِككُّمُ الْمَوْتُ﴾ دون «حيثما»؟","answer":"«أينما» أشمل وأعم من «حيثما»، فاستُعملت هنا للدلالة على امتداد يد الموت إلى كل مكان، فلا يحجز الإنسانَ عنه شيء أينما كان.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص84.","url":""}]},{"id":"s4-503","number":503,"surah":4,"verses":[78],"references":[{"surah":4,"verses":[78]}],"verseLabel":"النساء: 78","question":"ما سر التعبير بـ«لو» دون «إن» في ﴿وَلَوْ كُنتُمْ فِي بُرُوجٍ مُشَيَّدَةٍ﴾؟","answer":"«لو» تدل على البعد، وقصارى ما يستطيعه الإنسان في حفظ نفسه أن يكون في بروج مشيدة، فجاء بـ«لو» الدالة على أبعد الفروض، ومع ذلك يدركه الموت.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص91.","url":""}]},{"id":"s4-492","number":492,"surah":4,"verses":[82],"references":[{"surah":4,"verses":[82]}],"verseLabel":"النساء: 82","question":"ما سر التعبير بـ«يتدبرون» في ﴿أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا﴾ دون «يدّبّرون»؟","answer":"المقام يحتاج إلى طول تدبر وتأمل من جهتين: أن النظر شامل للقرآن كله لا لقسم منه، وأنه نظر في نفي الاختلاف بين آياته وتخريج ما يبدو مختلفًا لأول وهلة. فجاء بـ«يتدبر» الدال على التدبر العقلي والنظر الاستدلالي.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص42.","url":""}]},{"id":"s4-493","number":493,"surah":4,"verses":[92],"references":[{"surah":4,"verses":[92]}],"verseLabel":"النساء: 92","question":"ما سر التعبير بـ«مِن» في ﴿تَوْبَةً مِّنَ اللَّهِ﴾، مع قوله في التوبة والشورى: ﴿يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ﴾؟","answer":"ذكر «مِن» ليبيّن الجهة التي تقبل التوبة وهو الله، وذكر «عن» في الآيتين الأخريين ليبيّن طالب التوبة وهم العباد، أي يقبل التوبة الصادرة عنهم. وفي «روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج1، ص46–47.","url":""}]},{"id":"s4-494","number":494,"surah":4,"verses":[92,93],"references":[{"surah":4,"verses":[92,93]}],"verseLabel":"النساء: 92–93","question":"ما سر التعبير بالماضي في ﴿وَمَن قَتَلَ مُؤْمِنًا خَطَأً﴾، وبالمضارع في ﴿وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا﴾؟","answer":"القتل الخطأ لا يتكرر وهو قليل فجاء بالماضي، أما القتل العمد فهو الإصرار على قتل المؤمن ويتكرر وقوعه، فجاء بصيغة المضارع الدالة على الاستمرار والتجدد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص59؛ النحو العربي، ج2، ص457.","url":""}]},{"id":"s4-495","number":495,"surah":4,"verses":[95,103],"references":[{"surah":4,"verses":[95,103]}],"verseLabel":"النساء: 95، 103","question":"ما سر التعبير بـ﴿الْقَاعِدُونَ﴾ في آية الجهاد، وبـ﴿قُعُودًا﴾ في ﴿فَاذْكُرُوا اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِكُمْ﴾؟","answer":"خصّ القرآن «القُعود» جمع قاعد بالقعود الحقيقي، و«القاعدين» بمعنى القعود عن الجهاد، فلم ترد «قاعدون» في القرآن إلا بهذا المعنى. فجاء في آية الجهاد بـ«القاعدون»، وفي آية الذكر بـ«قعودًا».","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص123–124.","url":""}]},{"id":"s4-496","number":496,"surah":4,"verses":[97],"references":[{"surah":4,"verses":[97]}],"verseLabel":"النساء: 97","question":"ما سر التعبير بـ﴿تَوَفَّاهُمُ﴾ بحذف إحدى التاءين في ﴿إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ ظَالِمِي أَنفُسِهِمْ﴾، و﴿تَتَوَفَّاهُمُ﴾ في النحل؟","answer":"الذين في النحل هم الظالمون أنفسهم من الكافرين على وجه العموم، أما الذين في النساء فهم المستضعفون منهم، فهم قسم منهم. فلما كانوا أقل حذف من الفعل إشارة إلى الاقتطاع من الحدث وقلته، فناسب بين الفعل وكثرة الحدث.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص11.","url":""}]},{"id":"s4-497","number":497,"surah":4,"verses":[107],"references":[{"surah":4,"verses":[107]}],"verseLabel":"النساء: 107","question":"ما سر صيغة المبالغة في ﴿إِنَّ اللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمًا﴾، مع قوله في الأنفال: ﴿إِنَّ اللَّهَ لَا يُحِبُّ الْخَائِنِينَ﴾؟","answer":"آية النساء في قوم مبالغين في الخيانة، ولذا قال قبلها ﴿يَخْتَانُونَ﴾ على وزن «يفتعلون» المفيد للمبالغة، ثم ذكر صفاتهم من الاستخفاء والتبييت ورمي البريء. أما آية الأنفال ففي قوم لم يخونوا بعد، وإنما خيفت منهم الخيانة، فقال «الخائنين».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص331–332.","url":""}]},{"id":"s4-498","number":498,"surah":4,"verses":[135],"references":[{"surah":4,"verses":[135]}],"verseLabel":"النساء: 135","question":"ما سر التعبير بـ«لو» في ﴿كُونُوا قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ وَلَوْ عَلَىٰ أَنفُسِكُمْ﴾؟","answer":"«لو» تدل على البعد، والإنسان أبعد ما يكون عن أن يشهد على نفسه، فجاء بـ«لو» للدلالة على أن القيام بالقسط مطلوب ولو بلغ هذا الحد البعيد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص91.","url":""}]},{"id":"s4-499","number":499,"surah":4,"verses":[136],"references":[{"surah":4,"verses":[136]}],"verseLabel":"النساء: 136","question":"ما سر تأخير اليوم الآخر في ﴿وَمَن يَكْفُرْ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ وَالْيَوْمِ الْآخِرِ﴾، مع تقديمه في آية البرّ في البقرة؟","answer":"السياق في البقرة في ذكر اليوم الآخر وما أعدّ فيه لمن عصاه فقدّمه، أما في النساء فالسياق في الإيمان بالله ورسله والتفريق بينهم، ولم يُذكر اليوم الآخر فيه، فأخّره مناسبةً للسياق.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج2، ص16–17.","url":""}]},{"id":"s4-500","number":500,"surah":4,"verses":[157],"references":[{"surah":4,"verses":[157]}],"verseLabel":"النساء: 157","question":"ما دلالة النفي بـ«ما» في ﴿وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ﴾ دون «لم»؟","answer":"جاء النفي بـ«ما» ردًّا على قولهم: ﴿إِنَّا قَتَلْنَا الْمَسِيحَ﴾، و«ما» آكد في النفي من «لم».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص193.","url":""}]},{"id":"s4-501","number":501,"surah":4,"verses":[162],"references":[{"surah":4,"verses":[162]}],"verseLabel":"النساء: 162","question":"ما سر نصب ﴿وَالْمُقِيمِينَ الصَّلَاةَ﴾ مع أنه معطوف على مرفوع في آية ﴿لَّٰكِنِ الرَّاسِخُونَ فِي الْعِلْمِ﴾؟","answer":"هو من القطع، ويكون للمدح بتقدير «أمدح» أو «أخصّ». وخُصّت الصلاة بذلك لأنها أهم العبادات الظاهرة، وهي فرض عين لا يسقط بحال.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج1، ص47.","url":""}]},{"id":"s4-502","number":502,"surah":4,"verses":[171],"references":[{"surah":4,"verses":[171]}],"verseLabel":"النساء: 171","question":"ما سر قوله: ﴿وَلَا تَقُولُوا عَلَى اللَّهِ إِلَّا الْحَقَّ﴾ في النساء، و﴿لَا تَغْلُوا فِي دِينِكُمْ غَيْرَ الْحَقِّ﴾ في المائدة؟","answer":"الغلو لا يكون حقًّا بحال، فلا يصح أن يقال «لا تغلوا إلا الحق». أما القول على الله فقد يكون حقًّا وقد يكون باطلًا، فصحّ الاستثناء المفرّغ في آية النساء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج2، ص36.","url":""}]},{"id":"s5-1","number":1,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: السورة","question":"ما سرّ تسمية السورة بـ﴿المائدة﴾؟","answer":"سُمّيت سورة المائدة لاختصاصها بذكر المائدة التي طلب الحواريون من عيسى عليه السلام أن يسأل ربه إنزالها، ولم ترد قصتها في سورة أخرى. وسُمّيت أيضًا سورة العقود لافتتاحها بالأمر بالوفاء بالعقود.","sources":[{"label":"ابن عاشور، *التحرير والتنوير*، مقدمة سورة المائدة؛ النص المنشور","url":"https://quran.com/ar/al-maidah/info"}]},{"id":"s5-2","number":2,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما مناسبة افتتاح سورة المائدة بالأمر: ﴿أوفوا بالعقود﴾؟","answer":"افتتحت بالوفاء لأن السورة تشتمل على عقود ومواثيق كثيرة مع الله وبين الناس، وعلى أحكام الحلال والحرام والشهادة؛ فجاء المطلع براعة استهلال لمقاصدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص493–494، تحت «براعة الاستهلال في افتتاح السورة بالأمر بالإيفاء بالعقود»","url":""}]},{"id":"s5-3","number":3,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"لماذا جاء الأمر بالوفاء بـ﴿العقود﴾ معرفًا من غير تقييد بنوع منها؟","answer":"التعريف للاستغراق؛ فيشمل ما أوجبه الله على عباده وما يعقده الناس بينهم من التزامات صحيحة، فلا يختص بعقد معين. وفي هذا العموم جمع لوجوه الوفاء التي تفصلها السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص495، تحت «التعريف في العقود للاستغراق، في قوله: ﴿أوفوا بالعقود﴾»","url":""}]},{"id":"s5-4","number":4,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما الصورة في التعبير عن العهود بـ﴿العقود﴾؟","answer":"العقد في الأصل ربط طرفين ربطًا محكمًا، فاستعير للعهد الذي يلزم صاحبه ولا يحله بالهوى؛ وفي الصورة معنى التوثيق والقوة واللزوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص496، تحت «دلالة الاستعارة التصريحية في قوله تعالى: ﴿أوفوا بالعقود﴾»","url":""}]},{"id":"s5-5","number":5,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما مناسبة ذكر تحليل بهيمة الأنعام عقب الأمر بالوفاء بالعقود؟","answer":"بعد الأمر الجامع بالوفاء بدأ بتفصيل أول ما عقده الله عليهم من أحكام الحلال والحرام؛ فصار تحليل الأنعام وما استثني منها تطبيقًا مباشرًا للعقد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص497–498، تحت «المناسبة بين الوفاء بالعقود، وحل بهيمة الأنعام للمؤمنين»","url":""}]},{"id":"s5-6","number":6,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما سرّ بناء قوله تعالى: ﴿أُحلت لكم﴾ للمجهول؟","answer":"بُني الفعل لما لم يسم فاعله لأن الفاعل معلوم؛ فالمخاطبون مؤمنون يقرون بأن المنعم والمشرّع هو الله وحده. وفي الإخبار بإحلال الأنعام لهم إظهار لرحمته وكرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص497، تحت عنوان «دلالة بناء الفعل (أحل) لما لم يسم فاعله، في قوله: ﴿أحلت لكم بهيمة الأنعام﴾»","url":""}]},{"id":"s5-7","number":7,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما دلالة إضافة ﴿بهيمة﴾ إلى ﴿الأنعام﴾ في قوله تعالى: ﴿بهيمة الأنعام﴾؟","answer":"لفظ البهيمة أعم، وإضافته إلى الأنعام تبين الجنس الذي يتعلق به الحل وتحتَرز من دخول ما حُرّم من البهائم؛ فلا تُحمل الإباحة على عموم لفظ البهيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص499، تحت عنوان «الاحتراز بذكر المضاف إليه في قوله تعالى: ﴿أحلت لكم بهيمة الأنعام﴾»","url":""}]},{"id":"s5-8","number":8,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما سرّ إجمال المستثنى في قوله تعالى: ﴿إلا ما يتلى عليكم﴾؟","answer":"أُجمل المستثنى هنا، ثم بُيّن في قوله: ﴿حرمت عليكم الميتة والدم﴾ وما بعدها؛ فالعبارة تحيل إلى آيات التحريم التي تفصّل ما خرج من الإباحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص500، تحت «الاستثناء في قوله: ﴿إلا ما يتلى عليكم﴾ استثناء من بهيمة الأنعام»","url":""}]},{"id":"s5-9","number":9,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما سرّ التعبير بقوله تعالى: ﴿غير محلي الصيد وأنتم حرم﴾ بدل التصريح: وحرم عليكم الصيد في الإحرام؟","answer":"جاء النهي في صورة حال تقيد المخاطبين وقت الانتفاع بالإباحة: أحلت لكم الأنعام حال كونكم غير مستحلين للصيد وأنتم محرمون؛ فجمع التركيب سعة النعمة وحدها في جملة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص502، تحت «ترادف جملتين حاليتين لبيان المستثنى، والتدرج في صيغ التحريم»","url":""}]},{"id":"s5-10","number":10,"surah":5,"verses":[1],"references":[{"surah":5,"verses":[1]}],"verseLabel":"المائدة: 1","question":"ما مناسبة ختم أول آية بقوله تعالى: ﴿إن الله يحكم ما يريد﴾؟","answer":"الخاتمة تقرر أن التحليل والتحريم حكم الله وحده، وأن استثناء الصيد حال الإحرام داخل في سلطانه التشريعي، فلا تخضع الحدود لأهواء الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504، تحت «جملة التذييل لتعليل الحكم، بقوله: ﴿إن الله يحكم ما يريد﴾»","url":""}]},{"id":"s5-11","number":11,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة تكرار نداء المؤمنين في أول الآية الثانية بعد وروده في الآية الأولى؟","answer":"جُدد نداء المؤمنين تنبيهًا لهم واستنهاضًا لعزائمهم وتذكيرًا بما ألزمهم الإيمان من طاعة الله، لئلا يحملهم ما سبق من صدّ المشركين على انتهاك الشعائر والاعتداء","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص509، تحت «سر تكرار عبارة النداء بقوله: ﴿يا أيها الذين آمنوا﴾ في هذه الآية وسابقتها»","url":""}]},{"id":"s5-12","number":12,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما الصورة في قوله تعالى: ﴿لا تحلوا شعائر الله﴾؟","answer":"استُعير الإحلال لانتهاك الشعائر؛ فصُورت حرمتها بشيء مربوط يُفكّ، وحلُّ هذا الرباط يصور استباحة ما وجب صونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص510، تحت «الاستعارة ودلالتها في قوله تعالى: ﴿لا تحلوا شعائر الله﴾»","url":""}]},{"id":"s5-13","number":13,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة إضافة الشعائر إلى اسم الله في قوله تعالى: ﴿شعائر الله﴾؟","answer":"أضيفت الشعائر إلى اسم الله لتشريفها وتعظيمها، وللتهويل من استباحتها أو التهاون بحرمتها","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص509–510، تحت «إضافة الشعائر إلى لفظ الجلالة للتشريف، في قوله تعالى: ﴿شعائر الله﴾»","url":""}]},{"id":"s5-14","number":14,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"لماذا خُص الهدي بالذكر بعد النهي العام عن إحلال شعائر الله؟","answer":"هو تخصيص بعد تعميم لتشريف الهدي وزيادة العناية به؛ فهو من أعظم الشعائر، وفيه نفع للناس وبذل لما تضن به النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص510–511، تحت عنوان «سر تخصيص قوله ﴿ولا الهدي﴾ بالذكر في الآية الكريمة»","url":""}]},{"id":"s5-15","number":15,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما سرّ إسناد الإحلال إلى ﴿الشهر الحرام﴾ مع أن المقصود انتهاك حرمته؟","answer":"أُطلق الشهر وأريد القتال الواقع فيه، فعبر بالمحل عن الحالّ فيه على سبيل المجاز المرسل؛ والمقصود النهي عن استحلال القتال في الزمن الحرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص510، تحت «دلالة المجاز المرسل في قوله تعالى: ﴿ولا الشهر الحرام﴾»","url":""}]},{"id":"s5-16","number":16,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما مناسبة تخصيص ﴿القلائد﴾ بالذكر بعد ﴿الهدي﴾ وهي منه؟","answer":"القلائد العلامة الظاهرة التي يعرف بها الهدي فيأمن، وتخصيصها بعد عموم الهدي يشدد حرمة ما ظهر شعاره حتى لا يُعتدى عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص511–512، تحت «التخصيص بعد التعميم، في قوله: ﴿ولا الهدي ولا القلائد﴾»","url":""}]},{"id":"s5-17","number":17,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"لماذا قيل ﴿ولا آمين البيت الحرام﴾، ولم يقل: ولا قاصدي مكة؟","answer":"لأن مكة قد تُقصد لتجارة ونحوها، أما ذكر البيت الحرام فيدل على قصد الحج، ويستحضر حرمة البيت وحرمة قاصديه؛ فناسب النهي عن التعرض لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص512–513، تحت «قوله: ﴿ولا آمين البيت الحرام﴾، دون أن يقول: ولا آمين مكة؟»","url":""}]},{"id":"s5-18","number":18,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"كيف يُفهم ابتغاء الرضوان في قوله تعالى: ﴿يبتغون فضلًا من ربهم ورضوانًا﴾ مع دخول المشركين في قاصدي البيت زمن النزول؟","answer":"من أوجه التفسير أن المشركين كانوا يقصدون بحجهم ابتغاء رضوان الله، أو يظنون أنهم ينالونه؛ فالعبارة تحكي ما يطلبونه وما يزعمونه، ولا تقتضي حصول الرضوان لهم مع شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص514، تحت عنوان «دلالة الرضوان في قول الرحمن: ﴿يبتغون فضلًا من ربهم ورضوانًا﴾»","url":""}]},{"id":"s5-19","number":19,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة الأمر في قوله تعالى: ﴿وإذا حللتم فاصطادوا﴾؛ أهو للوجوب؟","answer":"الأمر بعد حظر الصيد حال الإحرام يرفع المنع ويعيد الإباحة، ولا يوجب الصيد؛ فالسياق صرف صيغة الأمر من الطلب إلى الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص515–516، تحت «الغرض من الأمر في قوله: ﴿فاصطادوا﴾ غايته التيسير»","url":""}]},{"id":"s5-20","number":20,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"لماذا استُعمل ﴿يجرمنكم﴾ في النهي عن أثر البغض في الاعتداء؟","answer":"اختير لفظ «جرم» مع مقاربته معنى الكسب لزيادة التنفير من الاعتداء على قاصدي البيت؛ فهو يصله بمعنى الجريمة ويشدد الزجر عن أن يحمل البغض على العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص518، تحت «إيثار التعبير بلفظ (جرم) على (كسب) في قوله ﴿ولا يجرمنكم شنآن قوم﴾»","url":""}]},{"id":"s5-21","number":21,"surah":5,"verses":[2,8],"references":[{"surah":5,"verses":[2,8]}],"verseLabel":"المائدة: 2، 8","question":"لماذا حُذفت «على» في ﴿أن تعتدوا﴾، وأُثبتت في ﴿على ألا تعدلوا﴾؟","answer":"الأولى تنهى عن اعتداء ناشئ عن واقعة الصد عن المسجد الحرام، أما الثانية فتقرر النهي العام المستمر عن ترك العدل؛ فجاء إثبات «على» في الثانية لزيادة التأكيد، لأن حكمها أعم وأشمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص523–524، تحت «من متشابه النظم»","url":""}]},{"id":"s5-22","number":22,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما مناسبة الانتقال من أحكام الحج والصيد إلى قوله تعالى: ﴿وتعاونوا على البر والتقوى ولا تعاونوا على الإثم والعدوان﴾؟","answer":"بعد النهي عن الانتقام ممن صدوا المؤمنين عمّم المبدأ: تكون المعاملة تعاونًا على الخير وصيانة الحدود، لا تعاونًا على المعصية والاعتداء؛ فارتقى من الواقعة إلى قاعدة اجتماعية شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص519–520، تحت «علاقة جملة ﴿وتعاونوا على البر والتقوى﴾ بما قبلها»","url":""}]},{"id":"s5-23","number":23,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة الجمع بين ﴿البر والتقوى﴾ ومقابلتهما بـ﴿الإثم والعدوان﴾؟","answer":"قابل الأمر بالتعاون على الخير والتقوى بالنهي عن التعاون على ما يفسد صاحبه أو يعتدي به على غيره. فاجتمع الحث على تبادل المعونة والإحسان مع منع التعاون على وجوه الفساد، وقوّت المقابلة المعنى أمرًا ونهيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص521، تحت عنوان «بلاغة المقابلة في قوله تعالى: ﴿وتعاونوا على البر والتقوى ولا تعاونوا على الإثم والعدوان﴾»","url":""}]},{"id":"s5-24","number":24,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما دلالة تقديم ﴿الإثم﴾ على ﴿العدوان﴾؟","answer":"قُدّم الإثم لعمومه وشموله، ولأنه طريق إلى العدوان؛ فمن لم يمتنع عن معصية الله لم يردعه ذلك عن الاعتداء على الناس. فالنهي يتناول أصل المخالفة ثم ما يتعدى ضرره إلى الغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص521–522، تحت «النكتة في تقديم الإثم على العدوان، مع كونهما معًا ضررًا ومفسدة»","url":""}]},{"id":"s5-25","number":25,"surah":5,"verses":[2],"references":[{"surah":5,"verses":[2]}],"verseLabel":"المائدة: 2","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله شديد العقاب﴾؟","answer":"لما كثرت النواهي عن انتهاك الشعائر والاعتداء والتعاون على الإثم جاءت الخاتمة زجرًا يضمن جدية الحدود؛ فمن خالفها فالله شديد العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص522، تحت «وجه ارتباط التذييل في قوله: ﴿إن الله شديد العقاب﴾ بما قبله»","url":""}]},{"id":"s5-26","number":26,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ بناء ﴿حرمت عليكم الميتة﴾ للمفعول في المائدة، وبناء ﴿إنما حرم عليكم الميتة﴾ للفاعل في البقرة؟","answer":"يبين المصدر أن بناء الفعل للمفعول في المائدة يناسب علم المؤمنين بأن المحرِّم هو الله وحده. أما البناء للفاعل في البقرة فيناسب الرد على من ينسب التحليل والتحريم إلى علمائه؛ لتقرير أن التحريم حق لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص535، تحت عنوان «سر التعبير بالبناء للفاعل في موضع البقرة في قوله: ﴿إنما حرم﴾، وبالبناء للمفعول في موضع المائدة»","url":""}]},{"id":"s5-27","number":27,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿حرمت عليكم الميتة﴾ مع أن المقصود أكلها؟","answer":"التحريم يتعلق بأفعال المكلفين، والتقدير: حُرّم عليكم أكل الميتة؛ فحُذف المضاف وأقيمت الميتة مقامه، اعتمادًا على فهم الفعل المقصود من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص531، تحت «دلالة حذف المضاف وإقامة المضاف إليه مقامه في قوله ﴿حرمت عليكم الميتة﴾»","url":""}]},{"id":"s5-28","number":28,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"لماذا خُص لحم الخنزير بالذكر في المحرمات؟","answer":"اللحم معظم ما يؤكل من الحيوان، وسائر أجزائه تابعة له في الحكم. وخُص لحم الخنزير بالذكر زيادةً في التغليظ على من اعتاد أكله، مع شمول التحريم لسائر أجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص534، تحت «دلالة ذكر اللحم وإضافته إلى الخنزير في الآية الكريمة»","url":""}]},{"id":"s5-29","number":29,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ تقديم ﴿لغير الله﴾ في قوله تعالى في المائدة: ﴿وما أهل لغير الله به﴾، وتأخيره في البقرة: ﴿وما أهل به لغير الله﴾؟","answer":"في البقرة كان المقام مقام الرزق والطعام، فقُدم ﴿به﴾ العائد إلى المذبوح؛ أما المائدة فمقامها بيان من يملك التحليل والتحريم وإبطال من يجعله لغير الله، فقُدم ﴿لغير الله﴾ لأنه موضع العناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص536، تحت عنوان «السر في تقديم الجار والمجرور ﴿به﴾ على ﴿لغير الله﴾ في قوله: ﴿وما أهل به لغير الله﴾، وسر تأخيره في آية المائدة في قوله: ﴿وما أهل لغير الله به﴾»","url":""}]},{"id":"s5-30","number":30,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة تفصيل المنخنقة والموقوذة والمتردية والنطيحة بعد دخولها في عموم الميتة؟","answer":"فُصّلت هذه الصور بعد عموم الميتة لأنها كانت معروفةً مأكولةً في الجاهلية، ولئلا يظن أحد إباحة بعضها؛ فبيّن أنها داخلة في حكم الميتة","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص532، تحت «دلالة عطف قوله تعالى ﴿والمنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع إلا ما ذكيتم﴾ على الميتة»","url":""}]},{"id":"s5-31","number":31,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما وجه الإيجاز في قوله تعالى: ﴿وما أكل السبع﴾ مع أن الحكم يتعلق بما بقي من الفريسة؟","answer":"التقدير: وما أكل منه السبع؛ فحُذف الجار والمجرور «منه» إيجازًا. أما الجزء الذي أكله السبع فقد ذهب، وإنما يتعلق الحكم بما بقي من الفريسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص538، تحت عنوان «بلاغة الإيجاز والمجاز في قوله: ﴿وما أكل السبع﴾»","url":""}]},{"id":"s5-611","number":611,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة نسبة الأكل إلى السبع في قوله تعالى: ﴿وما أكل السبع﴾ دون التعبير بالافتراس؟","answer":"المراد ما افترسه السبع فأماته، سواء أكل منه أم لم يأكل؛ لأنه افترسه ليأكله. ففي التعبير مجاز مرسل أُطلق فيه الأكل، وهو الغاية المسببة للافتراس، وأريد الافتراس الذي أفضى إلى موت الفريسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص539، تحت عنوان «دلالة نسبة الأكل إلى السبع دون الافتراس في قوله: ﴿وما أكل السبع﴾»","url":""}]},{"id":"s5-32","number":32,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿إلا ما ذكيتم﴾، دون: إلا ما ذبحتم؟","answer":"التذكية إتمام الذبح الشرعي الذي تطيب به الذبيحة، وهي أوسع وأدق من مجرد إحداث الذبح؛ لأنها تقيد الاستثناء بإدراك الحيوان حيًا واستيفاء التذكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص540–541، تحت «سر التعبير بقوله ﴿إلا ما ذكيتم﴾ دون إلا ما ذبحتم»","url":""}]},{"id":"s5-33","number":33,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة ذكر ﴿وما ذبح على النصب﴾ بعد قوله تعالى: ﴿وما أهل لغير الله به﴾؟","answer":"ما أُهل لغير الله به يلحظ الاسم المقصود عند الذبح، وما ذبح على النصب يلحظ المكان والشعيرة الوثنية ولو لم يسم اسم الصنم؛ فذكرهما يسد طريقي الشرك في القصد والمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص543، تحت «سر عطف قوله ﴿وما ذبح على النصب﴾ على قوله ﴿وما أهل لغير الله به﴾»","url":""}]},{"id":"s5-34","number":34,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة إدخال الاستقسام بالأزلام في سياق المطعومات المحرمة؟","answer":"من وجوه اتصالها بالسياق أن الاستقسام كان يجري في تقسيم لحم الجزور بالميسر؛ فبعد بيان المحرم من الأطعمة نُهي عن طريقة محرمة في تحصيله وتقسيمه. ويعرض المصدر أيضًا وجهًا يربط العطف بإبطال خرافات الجاهلية في طلب معرفة ما قُسم لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص545، تحت عنوان «دلالة عطف قوله: ﴿وأن تستقسموا بالأزلام﴾ على ما قبله»","url":""}]},{"id":"s5-35","number":35,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"إلام يعود اسم الإشارة المفرد في قوله تعالى: ﴿ذلكم فسق﴾ بعد المذكورات المتعددة؟","answer":"يجوز أن يعود إلى الاستقسام بالأزلام خاصة، ويجوز أن يعود إلى جميع ما تقدم بتقدير: تناول هذه المحرمات فسق؛ فالإفراد باعتبار ذلك المقدر","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص548، تحت «نكتة التعبير باسم الإشارة في قوله تعالى ﴿ذلكم فسق﴾»","url":""}]},{"id":"s5-36","number":36,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ وصف المذكور بقوله تعالى: ﴿ذلكم فسق﴾، دون الاكتفاء بوصفه بالحرام؟","answer":"الفسق خروج عن طاعة الله، وهو يلائم الاستقسام والنصب لما فيهما من شعيرة جاهلية وتمرد على حكم الله؛ فليس الحكم منعًا فقهيًا مجردًا بل انحرافًا عقديًا وعمليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص549، تحت «سر وصف الوقوع في المحرمات بالفسق في قوله ﴿ذلكم فسق﴾»","url":""}]},{"id":"s5-37","number":37,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة مجيء قوله تعالى: ﴿اليوم يئس الذين كفروا من دينكم﴾ وسط أحكام المطعومات؟","answer":"جاءت الجملة اعتراضًا يؤكد حكم المحرمات ويعين على تقبله؛ فذكّرت المؤمنين بأن هذه الأحكام إكمال لدينهم وإصلاح لحالهم، وقد انقطع طمع الكافرين في إبطاله. فاجتمع التشديد في الحكم مع التبشير والامتنان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص549–550، تحت «دلالة موقع قوله تعالى ﴿اليوم يئس الذين كفروا من دينكم فلا تخشوهم واخشون﴾ بين آية المحرمات وآية الرخصة»","url":""}]},{"id":"s5-38","number":38,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة حذف ياء المتكلم في قوله تعالى: ﴿واخشون﴾؟","answer":"يربط المصدر إثبات الياء في البقرة بشدة الملابسات التي دعت إلى التحذير من خشية الناس. أما هنا فقد ظهرت قوة المسلمين وضعف موجب خشية الكافرين، فناسب ذلك حذف الياء في ﴿واخشون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص553–554، تحت «سر إثبات الياء في ﴿واخشوني﴾ في آية البقرة، وحذفها في موضعي المائدة»","url":""}]},{"id":"s5-39","number":39,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تكرار ﴿اليوم﴾ في قوله تعالى: ﴿اليوم يئس﴾ ثم ﴿اليوم أكملت﴾؟","answer":"أعيد لفظ «اليوم» لتعداد المنن وإبراز كل منها نعمة مستقلة: يأس الكافرين وعدم خشيتهم، ثم إكمال الدين وإتمام النعمة وارتضاء الإسلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص556–557، تحت «دلالة إعادة لفظ ﴿اليوم﴾ في قوله ﴿اليوم أكملت لكم دينكم﴾»","url":""}]},{"id":"s5-40","number":40,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿أكملت لكم دينكم﴾، دون: أكملت ديني؟","answer":"أضيف الدين إلى المخاطبين لترغيبهم في تحمّل تكاليفه وتبعاته والذبّ عن حياضه؛ فهو دينهم الذي أكمله الله لهم وارتضاه، وهم القائمون به","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557، تحت «سر إضافة الدين إلى المخاطبين في قوله تعالى ﴿اليوم أكملت لكم دينكم﴾»","url":""}]},{"id":"s5-41","number":41,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما الفرق بين الإكمال في قوله تعالى: ﴿أكملت لكم دينكم﴾، والإتمام في قوله: ﴿وأتممت عليكم نعمتي﴾؟","answer":"الإكمال يلحظ بلوغ الدين كماله وخلوه من النقص والخلل، والإتمام يلحظ استيفاء النعمة أجزائها وأسبابها حتى تبلغ تمامها؛ فاختلاف الفعلين يلائم اختلاف جهة وصف الدين والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص559–560، تحت عنوان «الفرق بين الكمال والتمام في قوله: ﴿اليوم أكملت لكم دينكم وأتممت عليكم نعمتي﴾»","url":""}]},{"id":"s5-42","number":42,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تعدية ﴿أكملت﴾ باللام في قوله تعالى: ﴿أكملت لكم دينكم﴾؟","answer":"اللام تدل على اختصاص المخاطبين بهذا الكمال، وتبرز كمال عناية الله بالمؤمنين؛ فقد تولى سبحانه إكمال الدين لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557–558، تحت عنوان «دلالة تعدية الفعل ﴿أكملت﴾ بحرف اللام في قوله: ﴿أكملت لكم﴾»","url":""}]},{"id":"s5-612","number":612,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تعدية ﴿أتممت﴾ بحرف ﴿على﴾ في قوله تعالى: ﴿وأتممت عليكم نعمتي﴾؟","answer":"يفيد الحرف معنى الاستعلاء، فيشير إلى علو هذه النعمة وأنها محض فضل من الله، وإلى شمولها للمخاطبين وإحاطتها بهم من كل جانب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص558، تحت عنوان «دلالة تعدية الفعل ﴿وأتممت﴾ في قوله تعالى: ﴿وأتممت عليكم نعمتي﴾ بحرف (على)»","url":""}]},{"id":"s5-43","number":43,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"لماذا أضيفت النعمة إلى الله في قوله ﴿وأتممت عليكم نعمتي﴾؟","answer":"أضيفت إليه لتشريفها والتذكير بأنه وليّها ومسديها؛ فهو الذي أتمها عليهم منّةً وتفضلًا. فتستحضر الإضافة عظمة العطاء ومصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص557، تحت «دلالة إضافة النعمة إليه سبحانه في قوله ﴿وأتممت عليكم نعمتي﴾»","url":""}]},{"id":"s5-44","number":44,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة تقديم ﴿لكم﴾ في قوله تعالى: ﴿ورضيت لكم الإسلام دينًا﴾؟","answer":"التقديم يفيد الاختصاص؛ فقد اختار الله لهذه الأمة الإسلام دينًا، وخصها بهذا الوصف. فيبرز موقع «لكم» عنايته بالمخاطبين وما اختاره لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص561، تحت «دلالة تقديم الجار والمجرور ﴿لكم﴾ في قوله ﴿ورضيت لكم الإسلام دينًا﴾»","url":""}]},{"id":"s5-45","number":45,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة العودة إلى حكم المضطر في المخمصة بعد إعلان كمال الدين؟","answer":"لما تمت الجمل الاعتراضية عاد السياق إلى تتمة أحكام المحرمات، فذكر رخصة المضطر؛ وبذلك اتصل ما بعد الاعتراض بما قبله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص561، تحت «مناسبة قوله تعالى ﴿فمن اضطر﴾ لما قبلها»","url":""}]},{"id":"s5-46","number":46,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير عن شدة الجوع بـ﴿مخمصة﴾؟","answer":"المخمصة المجاعة الشديدة التي تخمص فيها البطون، أي تضمر وتلتصق من الجوع؛ فاللفظ يصور أثر الضرورة في الجسد ولا يدل على جوع عادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص563، تحت «سر التعبير بالمخمصة دون الجوع في قوله ﴿فمن اضطر في مخمصة﴾»","url":""}]},{"id":"s5-47","number":47,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما الصورة في قوله تعالى: ﴿غير متجانف لإثم﴾؟","answer":"التجانف هو الميل؛ فالقيد يصور المضطر غير مائل إلى المحرم ميل المتشهي المستطيب، وإنما يأخذ منه عند خوف الهلاك بقدر ما يحفظ حياته","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص563–564، تحت «دلالة التعبير بقوله ﴿غير متجانف لإثم﴾»","url":""}]},{"id":"s5-48","number":48,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما مناسبة ختم حكم المضطر بقوله تعالى: ﴿فإن الله غفور رحيم﴾ مع أنه غير متعمد للمعصية؟","answer":"الخاتمة تطمئن المضطر وتؤكد رفع الحرج والإثم عنه في تناوله المحرم على الوجه المرخَّص فيه؛ فالمغفرة والرحمة هنا متصلتان بالتيسير عليه وحفظ حياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص564، تحت عنوان «دلالة الصيغة في صفتي المغفرة والرحمة في قوله: ﴿فإن الله غفور رحيم﴾»","url":""}]},{"id":"s5-49","number":49,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"كيف ترتبط صور الميتة المفصلة في المائدة بالمحرمات المجملة في الأنعام؟","answer":"صور المنخنقة والموقوذة والمتردية والنطيحة وما أكل السبع داخلة في جنس الميتة؛ فذكرها في المائدة تفصيل لما أجمل في الأنعام، وليس مجرد زيادة عدد الأسماء دليلًا على اختلاف الأصول المحرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج12، ص373–374، تحت «الحصر المستفاد من النفي والاستثناء»","url":""}]},{"id":"s5-50","number":50,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما مناسبة سؤالهم: ﴿ماذا أحل لهم﴾ بعد تفصيل المحرمات؟","answer":"لما سمعوا تفصيل المحرمات توجهت نفوسهم إلى معرفة ما أُحل لهم، فجاء السؤال والجواب انتقالًا من بيان حدود المنع إلى بيان المباح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص568، تحت عنوان «دلالة فصل جملة ﴿يسألونك ماذا أحل لهم﴾ عن الآية قبلها»","url":""}]},{"id":"s5-51","number":51,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما دلالة إعادة الفعل في الجواب: ﴿قل أحل لكم الطيبات﴾؟","answer":"تكرار الفعل يقرر أن التحليل والتحريم أمر شرعي يُتلقى من الله، وفيه امتنان وإعلام بأن ما أحله هو الطيب دون غيره؛ فيبطل جعل أهواء الناس معيارًا للحل والحرمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص570، تحت «دلالة تكرار الفعل ﴿أحل﴾ في قوله ﴿يسألونك ماذا أحل لهم قل أحل لكم الطيبات﴾»","url":""}]},{"id":"s5-52","number":52,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"لماذا عُبّر عن الحلال بقوله تعالى ﴿الطيبات﴾؟","answer":"أصل الطيب الطهارة والزكاء وحسن الأثر؛ فوصف الأطعمة به يشير إلى حسنها وسلامتها من المضرة، ويبين علة تحليلها، كما يدل على أن ضد الحلال هنا هو الخبيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص571، تحت عنوان «دلالة التعبير عن الحلال بالطيبات في قوله: ﴿قل أحل لكم الطيبات﴾»","url":""}]},{"id":"s5-53","number":53,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما سرّ تسمية حيوانات الصيد المدرَّبة ﴿الجوارح﴾؟","answer":"الجوارح من الجرح بمعنى الكسب، لأنها تكسب الصيد لصاحبها، ومن الجرح الحسي لأنها تمسكه بمخالبها أو أنيابها؛ فجمع الاسم فعلها وأثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص571–572، تحت «دلالة تسمية الكواسب من السباع ونحوها بالجوارح»","url":""}]},{"id":"s5-54","number":54,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما سرّ التعبير بقوله تعالى: ﴿مكلبين﴾ مع دخول جوارح من الطير في الحكم؟","answer":"التكليب تعليم الجوارح الصيد، واشتق من الكلب لأنه أشهر ما يدرب عليه وأكثره استعمالًا؛ فغلب اسمه على مهنة التعليم مع شمول الحكم لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص572، تحت عنوان «دلالة التعبير بالمكلب دون المعلم»","url":""}]},{"id":"s5-55","number":55,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما وجه البلاغة في الفصل في قوله تعالى ﴿تعلمونهن مما علمكم الله﴾؟","answer":"ترد الجملة العلم إلى منحة الله؛ فطرائق تعليم الجوارح إلهام منه، أو معرفة مكتسبة بالعقل الذي منحه للإنسان، أو بما عرّفه من علامات الجارحة المعلَّمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص573، تحت «بلاغة الفصل في قوله تعالى ﴿تعلمونهن مما علمكم الله﴾»","url":""}]},{"id":"s5-56","number":56,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما سرّ تعدية الإمساك بـ﴿على﴾ في قوله تعالى: ﴿مما أمسكن عليكم﴾، دون: لكم؟","answer":"عُدي الإمساك بـ﴿على﴾ للإيحاء بما على صاحب الجارحة من تبعة ومسؤولية في التحقق من شروط الحل، كالتسمية وكون الجارحة معلمة وألا تمسك الصيد لنفسها؛ بخلاف اللام التي قد توهم مجرد الاختصاص والإباحة بلا قيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص574، تحت «سر العدول عن اللام إلى على في ﴿فكلوا مما أمسكن عليكم﴾»","url":""}]},{"id":"s5-57","number":57,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما الذي أفاده التعبير بالضمير في ﴿واذكروا اسم الله عليه﴾؟","answer":"أوجز الضمير وأتاح أكثر من مرجع في السياق؛ فيجوز رده إلى إرسال الجوارح على الصيد، فتكون التسمية عند الإرسال، أو إلى ما أمسكن، فتكون عند إدراك ذكاة المصيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص576، تحت «بلاغة التعبير بالضمير في عليه بدلًا من الظاهر»","url":""}]},{"id":"s5-58","number":58,"surah":5,"verses":[4],"references":[{"surah":5,"verses":[4]}],"verseLabel":"المائدة: 4","question":"ما مناسبة ختم أحكام الصيد بقوله تعالى: ﴿إن الله سريع الحساب﴾؟","answer":"ختمت الآية بسرعة الحساب للتخويف من التساهل في شروط الصيد؛ فالله يعلم حقيقة التذكية وما يخفى من أحوالها، ويجازي المحسن ويعاقب المسيء","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص577، تحت «سر التعبير بقوله ﴿سريع الحساب﴾ خلافًا لفاصلة الآية السابقة»","url":""}]},{"id":"s5-59","number":59,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما دلالة تكرار قوله تعالى: ﴿اليوم أحل لكم الطيبات﴾ بعد قوله: ﴿قل أحل لكم الطيبات﴾؟","answer":"أعيد حكم الحل للتأكيد والتوطئة لما بعده من إباحة طعام أهل الكتاب، مع تعداد نعم الله والامتنان بسعة ما أباح للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص584، تحت عنوان «دلالة إعادة حكم حل الطيبات في قوله تعالى: ﴿اليوم أحل لكم الطيبات﴾»","url":""}]},{"id":"s5-60","number":60,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]},{"surah":9,"verses":[29]}],"verseLabel":"المائدة: 5؛ التوبة: 29","question":"لماذا قيل في إباحة الطعام: ﴿وطعام الذين أوتوا الكتاب حل لكم﴾، دون الاكتفاء بقول: طعام أهل الكتاب؟","answer":"يشير الوصف إلى من يدينون بالتوراة والإنجيل ويعرفون كتابهم؛ فلا يكفي مجرد الانتساب إلى أهل الكتاب ممن لا يعرفون دينهم ولا يدينون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص584، تحت عنوان «دلالة التعبير بـ﴿أوتوا الكتاب﴾ دون أهل الكتاب في قوله: ﴿وطعام الذين أوتوا الكتاب﴾»","url":""}]},{"id":"s5-613","number":613,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]},{"surah":9,"verses":[29]}],"verseLabel":"المائدة: 5؛ التوبة: 29","question":"ما دلالة التذكير بإيتاء الكتاب بعد قوله في التوبة: ﴿ولا يدينون دين الحق﴾؟","answer":"في بيان أنهم أوتوا الكتاب تشديد للذم؛ فقد جاءهم الكتاب الهادي إلى الحق، ثم نبذوا دين الحق الذي جاءتهم به كتبهم. فالتذكير بما عرفوه يزيد تقبيح مخالفتهم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص101، تحت عنوان «سر البيان في قوله: ﴿من الذين أوتوا الكتاب﴾»","url":""}]},{"id":"s5-614","number":614,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]},{"surah":9,"verses":[29]}],"verseLabel":"المائدة: 5؛ التوبة: 29","question":"لماذا قُيّد المذكورون في آية التوبة بوصف ﴿من الذين أوتوا الكتاب﴾؟","answer":"يميّز الوصف أهل الكتاب من المشركين في الحكم المذكور في الآية؛ فإيتاؤهم الكتاب وصف له أثر في نوع المعاملة، وليس مجرد تسمية للجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص102، تحت عنوان «سر التعبير والتقييد بقوله: ﴿أوتوا الكتاب﴾، دون: (أهل الكتاب)»","url":""}]},{"id":"s5-61","number":61,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما دلالة قوله تعالى: ﴿وطعامكم حل لهم﴾ مع أن المقصود بيان ما يحل للمؤمنين؟","answer":"تقرر الجملة جواز إطعام المسلمين أهلَ الكتاب من طعامهم، بعد بيان حل طعام أهل الكتاب لهم؛ فتكتمل الإباحة من الجانبين، ويتجلى تيسير المعاملة والمخالطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص585، تحت «دلالة عطف ﴿وطعامكم حل لهم﴾ على ما قبلها»","url":""}]},{"id":"s5-62","number":62,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿حل لكم﴾، دون: أحل لكم؟","answer":"في التعبير بالمصدر توكيد ومبالغة لإزالة توهم التحريم؛ فقد يتردد المؤمن في طعام أهل الكتاب بعد سماع ما سبق من أحكام المنع، فجاء ﴿حل لكم﴾ تقريرًا قويًا للإباحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص585، تحت «سر العدول عن الفعل أحل إلى المصدر حل»","url":""}]},{"id":"s5-63","number":63,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما مناسبة الجمع في آية واحدة بين طعام أهل الكتاب والزواج من نسائهم؟","answer":"عُطف حكم الطعام وحكم النكاح على تحليل الطيبات بالواو، مع استقلال كل حكم بمعناه؛ فالعطف يجمع بيان الإباحة في السياق دون أن يزيل ما يختص به كل حكم من قيود.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586–587، تحت عنوان «سر عطف تبادل الأطعمة ومنكوحات أهل الكتاب على تحليل الطيبات بالواو»","url":""}]},{"id":"s5-64","number":64,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"لماذا ذُكرت ﴿المحصنات من المؤمنات﴾ قبل محصنات أهل الكتاب مع أن حل المؤمنات معلوم؟","answer":"جاء ذكر المؤمنات توطئة وتمهيدًا لذكر محصنات أهل الكتاب، وإلحاقهن بهن في حكم الحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586، تحت عنوان «بلاغة الإيجاز في قوله: ﴿والمحصنات من المؤمنات﴾»","url":""}]},{"id":"s5-615","number":615,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما دلالة تخصيص المحصنات بوصف ﴿من المؤمنات﴾ مع إباحة محصنات أهل الكتاب بعدها؟","answer":"يوضح المصدر أن تخصيصهن بوصف الإيمان هنا مسوق لبيان الأفضلية، وليس لنفي حل الكتابيات؛ فقد نص السياق نفسه على إباحتهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586–587، تحت عنوان «سر عطف تبادل الأطعمة ومنكوحات أهل الكتاب على تحليل الطيبات بالواو»","url":""}]},{"id":"s5-65","number":65,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ تقييد حل الزواج بقوله تعالى: ﴿المحصنات﴾، دون: نساء الذين أوتوا الكتاب؟","answer":"قُيد الحل بالمحصنات لأن الإحصان من المنعة، والمراد هنا الحرائر العفيفات؛ فالإباحة متعلقة بمن اجتمع فيها وصف الحرية والعفة، لا بمجرد الانتساب إلى أهل الكتاب","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص586، تحت «بلاغة الإيجاز في قوله ﴿والمحصنات من المؤمنات﴾»","url":""}]},{"id":"s5-66","number":66,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"لماذا قيل ﴿إذا آتيتموهن أجورهن﴾ بـ«إذا» دون «إن»؟","answer":"جاءت «إذا» لتأكيد إيتاء المهر، لأن أداء هذا الحق مما ينبغي تحققه؛ أما «إن» فقد توهم تعليق الوفاء به على أمر مشكوك فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص587، تحت «سر التعبير بإذا دون إن في قوله ﴿إذا آتيتموهن أجورهن﴾»","url":""}]},{"id":"s5-67","number":67,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ تسمية المهور في قوله تعالى: ﴿إذا آتيتموهن أجورهن﴾؟","answer":"شُبّه المهر بالأجر من جهة كونه عوضًا ماليًا عن المنافع المترتبة على عقد النكاح؛ فالتعبير يقرب معنى استحقاقه ويؤكد وجوب أدائه، مع اختلاف عقد النكاح عن الإجارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص587، تحت «دلالة تسمية المهور أجورًا في قوله ﴿إذا آتيتموهن أجورهن﴾»","url":""}]},{"id":"s5-68","number":68,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما الفرق بين السفاح واتخاذ الأخدان في قوله تعالى: ﴿محصنين غير مسافحين ولا متخذي أخدان﴾؟","answer":"السفاح هنا المجاهرة بالزنا، واتخاذ الأخدان إسراره مع صديق أو صديقة؛ فنفى التعبير الفاحشة في صورتها الظاهرة والخفية، وأكد قصد العفة بالنكاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص588، تحت عنوان «دلالة الحالين في قوله: ﴿محصنين غير مسافحين ولا متخذي أخدان﴾»","url":""}]},{"id":"s5-69","number":69,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما مناسبة الانتقال من إباحة الطعام والزواج إلى قوله تعالى: ﴿ومن يكفر بالإيمان فقد حبط عمله﴾؟","answer":"إباحة نكاح الكتابية لا تعني تصحيح دينها؛ فجاءت الخاتمة تحذر من أن تجر هذه الصلة إلى الميل عن الإيمان، وتؤكد أن الكفر يحبط العمل ويؤول بصاحبه إلى الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص590، تحت «دلالة فاصلة الآية الكريمة»","url":""}]},{"id":"s5-70","number":70,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن يكفر بالإيمان﴾، دون: ومن لم يؤمن؟","answer":"وُجّه الكفر إلى الإيمان نفسه، كأنه حقيقة متعينة واحدة؛ للإشارة إلى أن الإيمان الحق هو الاعتقاد الصحيح، وما يخالفه لا يصح أن يُجعل إيمانًا آخر موازيًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص589، تحت «سر العدول عن أن يقول ومن لم يؤمن إلى قوله ﴿ومن يكفر بالإيمان﴾»","url":""}]},{"id":"s5-71","number":71,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما الصورة في قوله تعالى: ﴿حبط عمله﴾؟","answer":"الحبط في الأصل فساد ينتفخ به بطن الدابة ثم يهلكها، فاستعير للعمل الذي يبدو موجودًا ثم يسقط أثره وثوابه بسبب الكفر؛ صورة خسارة بعد توهم النماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص581، 589، تحت «دلالة التعبير بالفعل ﴿حبط﴾ في قوله ﴿ومن يكفر بالإيمان فقد حبط عمله﴾»","url":""}]},{"id":"s5-72","number":72,"surah":5,"verses":[5],"references":[{"surah":5,"verses":[5]}],"verseLabel":"المائدة: 5","question":"ما مناسبة قوله تعالى: ﴿وهو في الآخرة من الخاسرين﴾ بعد حبوط العمل؟","answer":"ضم ذكر الخسران في الآخرة إلى حبوط العمل لتأكيد التحذير من الكفر؛ فلا تنفع صاحبه قرباته التي فقدت شرط قبولها، ويضيع ثوابها وما يرجوه من الفوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص589–590، تحت عنوان «دلالة التعبير بالفعل ﴿حبط﴾ في قوله: ﴿ومن يكفر بالإيمان فقد حبط عمله﴾»","url":""}]},{"id":"s5-73","number":73,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"لماذا قيل ﴿أو جاء أحد منكم من الغائط﴾، ولم يقل: أو جئتم من الغائط؟","answer":"تجنب التعبير إسناد هذا الفعل إلى المخاطبين مباشرة، وأسنده إلى فرد غير معين؛ مراعاةً لأدب الخطاب وحياء السامع، مع وضوح الحكم المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص608، تحت «علة صرف إسناد الفعل الخادش إلى المخاطبين بإسناده إلى أحد غير معين»","url":""}]},{"id":"s5-74","number":74,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"كيف يُفهم قوله تعالى: ﴿إذا قمتم إلى الصلاة فاغسلوا وجوهكم﴾ مع أن الوضوء يسبق الدخول فيها؟","answer":"القيام إلى الشيء يأتي بمعنى إرادة الشروع فيه والتوجه إليه؛ أي إذا أردتم القيام إلى الصلاة وأنتم محدثون فتوضؤوا، كما يقال: إذا قرأت فاستعذ، أي إذا أردت القراءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص595–596، تحت عنوان «المجاز المرسل وأثره في إبراز المعنى في قوله تعالى: ﴿إذا قمتم إلى الصلاة﴾»","url":""}]},{"id":"s5-75","number":75,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"لماذا أُدخل مسح الرأس بين غسل اليدين وغسل الرجلين في آية الوضوء؟","answer":"للعناية بمسح الرأس حتى لا يتهاون به، فيأخذ من الاهتمام ما تأخذه الأعضاء المغسولة؛ وفي تقديمه على غسل الرجلين تنبيه إلى أهمية الترتيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص601–602، تحت عنوان «القراءات الواردة في قوله: ﴿وأرجلكم﴾، وأثرها في المعنى والأحكام»","url":""}]},{"id":"s5-616","number":616,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما وجه مجاورة الأرجل للرؤوس في قراءة الجر في آية الوضوء؟","answer":"من التوجيهات التي يذكرها المصدر التنبيه إلى الاقتصاد في صب الماء على الرجلين؛ فهما مظنة الإسراف، فجاءت مجاورتهما للممسوح تذكيرًا بتقليل الماء مع استيفاء الغسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص602–603، تحت عنوان «دلالة اشتراك المتعاطفين في الوصف في قوله: ﴿وامسحوا برؤوسكم وأرجلكم﴾»","url":""}]},{"id":"s5-76","number":76,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة ﴿إلى المرافق﴾ و﴿إلى الكعبين﴾؟","answer":"تحدد ﴿إلى﴾ غاية الجزء المغسول، لكن دخول الغاية في الغسل لا يحسمه الحرف وحده، بل يُعرف بالدليل. ويذكر المصدر دخول المرفقين والكعبين في الغسل اعتمادًا على البيان النبوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص599، تحت عنوان «دلالات التعبير بحرف الانتهاء ﴿إلى﴾ في قوله تعالى: ﴿وأيديكم إلى المرافق﴾»","url":""}]},{"id":"s5-77","number":77,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿وإن كنتم جنبًا فاطهروا﴾، دون: فاغتسلوا؟","answer":"اختير ﴿فاطهروا﴾ للدلالة على الاغتسال مع المبالغة والاجتهاد في إيصال الماء إلى جميع أجزاء البدن؛ لأن أثر الجنابة المعنوي يعم الجسد كله","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص606، تحت عنوان «دلالة ﴿فاطهروا﴾ على الحكم الشرعي، وسر تعليق الشرط بأداة الشك ﴿وإن﴾»","url":""}]},{"id":"s5-78","number":78,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما الصورة في قوله تعالى: ﴿أو على سفر﴾، دون: أو مسافرين؟","answer":"يدل ﴿على سفر﴾ على العزم عليه والاستعداد له، فيتناول من شرع فيه ولو لم يجاوز حد الحضر؛ فالتعبير يلائم مقام التخفيف والتيسير في بيان الرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص606–607، تحت «سر العدول عن لفظ مسافرين إلى قوله ﴿على سفر﴾»","url":""}]},{"id":"s5-79","number":79,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ الكناية في قوله تعالى: ﴿أو جاء أحد منكم من الغائط﴾؟","answer":"الغائط في الأصل المكان المنخفض الذي يقصده الإنسان ليستتر، ثم كُني بالمجيء منه عن قضاء الحاجة؛ فحفظ التعبير الأدب وتجنب التصريح بما يستقبح ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص608، تحت عنوان «علة الكناية عن قضاء الحاجة في قوله: ﴿أو جاء أحد منكم من الغائط﴾»","url":""}]},{"id":"s5-80","number":80,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سرّ الكناية بقوله تعالى: ﴿أو لامستم النساء﴾؟","answer":"الملامسة كناية عن الجماع؛ عُدل إليها لتنزيه الخطاب عن التصريح بما يُستحيا من ذكره، مع دلالة اللفظ القريب على المقصود. ففي اختيارها وضوح المعنى وأدب التعبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص610–611، تحت «مزية الكناية وأثرها في المعنى في قوله ﴿أو لامستم النساء﴾»","url":""}]},{"id":"s5-81","number":81,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما دلالة وصف الصعيد بالطيب في قوله تعالى: ﴿فتيمموا صعيدًا طيبًا﴾؟","answer":"التيمم هو القصد، والصعيد وجه الأرض، والطيب الطاهر؛ أي اقصدوا عند فقد الماء أو تعذر استعماله جزءًا طاهرًا من جنس الأرض، فجمع اللفظ القصد والبديل وصفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص612، تحت عنوان «دلالة وصف الصعيد بالطيب في قوله تعالى: ﴿فتيمموا صعيدًا طيبًا﴾»","url":""}]}]);
